        var lifetimePrice = isGuest ? '—' : (p.lifetimeEnabled && p.priceLifetime ? formatVnd(p.priceLifetime) : '—');
        var sku = isGuest ? 'Website công khai' : (p.apple || p.google || p.web || '—');
