  font-size: var(--ifx-text-title-md-size);
  color: var(--ix-text-primary);
  letter-spacing: var(--ifx-letter-spacing-tight);
}

/* Main content area */
.ix-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  height: 100vh;
  margin-left: var(--ix-sidebar-w);
  overflow: hidden;
  transition: margin-left 0.25s ease;
}

/* Desktop: thu gọn sidebar — chỉ còn icon */
.ix-layout.ix-sidebar-collapsed .ix-sidebar {
  width: var(--ix-sidebar-w-collapsed);
}
.ix-layout.ix-sidebar-collapsed .ix-main {
  margin-left: var(--ix-sidebar-w-collapsed);
}
.ix-layout.ix-sidebar-collapsed .ix-brand-name,
.ix-layout.ix-sidebar-collapsed .ix-menu-label,
.ix-layout.ix-sidebar-collapsed .ix-menu-header,
.ix-layout.ix-sidebar-collapsed .ix-menu-arrow,
.ix-layout.ix-sidebar-collapsed .ix-menu-badge {
  display: none;
}
.ix-layout.ix-sidebar-collapsed .ix-brand {
  justify-content: center;
  padding: 0;
  gap: 0;
}
.ix-layout.ix-sidebar-collapsed .ix-menu-item {
  justify-content: center;
  align-items: center;
  padding: 10px 0;
  gap: 0;
}
.ix-layout.ix-sidebar-collapsed .ix-menu-icon {
  width: auto;
  margin: 0;
}
.ix-layout.ix-sidebar-collapsed .ix-menu-item.active::before {
  display: none;
}
.ix-layout.ix-sidebar-collapsed .ix-menu-sub,
.ix-layout.ix-sidebar-collapsed .ix-menu-item.open + .ix-menu-sub {
  display: none !important;
}

/* Mobile drawer + overlay */
.ix-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--color-scrim);
  z-index: var(--ifx-z-overlay);
}
.ix-overlay.ix-overlay-visible { display: block; }
.ix-body-noscroll { overflow: hidden; }

@media (max-width: 1199.98px) {
  .ix-sidebar {
    transform: translateX(-100%);
    width: var(--ix-sidebar-w);
  }
  .ix-sidebar.ix-sidebar-open { transform: translateX(0); }
  .ix-main { margin-left: 0; }
  .ix-layout.ix-sidebar-collapsed .ix-sidebar { width: var(--ix-sidebar-w); }
  .ix-layout.ix-sidebar-collapsed .ix-main { margin-left: 0; }
  .ix-layout.ix-sidebar-collapsed .ix-brand-name,
  .ix-layout.ix-sidebar-collapsed .ix-menu-label,
  .ix-layout.ix-sidebar-collapsed .ix-menu-header,
  .ix-layout.ix-sidebar-collapsed .ix-menu-arrow,
  .ix-layout.ix-sidebar-collapsed .ix-menu-badge {
    display: revert;
  }
  .ix-layout.ix-sidebar-collapsed .ix-brand {
    justify-content: flex-start;
    padding: 0 var(--ifx-space-20);
    gap: var(--ifx-inline-md);
  }
  .ix-layout.ix-sidebar-collapsed .ix-menu-item {
    justify-content: flex-start;
    padding: 9px 20px;
    gap: var(--ifx-inline-md);
  }
  .ix-layout.ix-sidebar-collapsed .ix-menu-item.active::before {
    display: block;
  }
}

/* Navbar */
.ix-navbar {
  height: var(--ix-navbar-h);
  background: var(--ix-bg-navbar);
  border-bottom: 1px solid var(--ix-border);
  display: flex;
  align-items: center;
  padding: 0 var(--ifx-space-container);
  gap: var(--ifx-gap-sm);
  position: sticky;
  top: 0;
  z-index: var(--ifx-z-sticky);
}

/* Content area — scroll nội bộ, không scroll body */
.ix-content {
  flex: 1;
  min-height: 0;
  padding: var(--ifx-space-container);
  overflow-y: auto;
  overflow-x: hidden;
}
.ix-content::-webkit-scrollbar { width: 6px; }
.ix-content::-webkit-scrollbar-thumb {
  background: var(--ix-border);
  border-radius: 4px;
}

/* -----------------------------------------------------------------
   4. NAVIGATION MENU
   ----------------------------------------------------------------- */
.ix-menu {
  flex: 1;
  padding: var(--ifx-space-12) 0;
}
.ix-menu-header {
  padding: var(--ifx-inset-card) 4px;
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-semibold);
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: var(--ix-text-muted);
}
.ix-menu-item {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-md);
  padding: 9px 20px;
  color: var(--ix-text-secondary);
  cursor: pointer;
  position: relative;
  transition: background 0.15s, color 0.15s;
  text-decoration: none;
  user-select: none;
}
.ix-menu-item:hover {
  background: var(--ix-bg-hover);
  color: var(--ix-text-primary);
}
.ix-menu-item.active {
  background: var(--ix-bg-active);
  color: var(--ix-accent);
}
.ix-menu-item.active::before {
  content: '';
  position: absolute;
  left: 0; top: 4px; bottom: 4px;
  width: 3px;
  background: var(--ix-accent);
  border-radius: 0 3px 3px 0;
}
.ix-menu-icon {
  font-size: var(--ifx-font-size-18);
  width: 20px;
  text-align: center;
  flex-shrink: 0;
}
.ix-menu-label {
  flex: 1;
  font-size: 13.5px;
}
.ix-menu-arrow {
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-muted);
  transition: transform 0.2s;
}
.ix-menu-item.open .ix-menu-arrow { transform: rotate(90deg); }

/* Submenu */
.ix-menu-sub {
  list-style: none;
  display: none;
  padding: 4px 0;
}
.ix-menu-item.open + .ix-menu-sub { display: block; }
.ix-menu-sub .ix-menu-item { padding-left: 50px; font-size: var(--ifx-font-size-14); }

/* -----------------------------------------------------------------
   5. NAVBAR ELEMENTS
   ----------------------------------------------------------------- */
.ix-search {
  flex: 1;
  max-width: 280px;
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
  background: var(--ix-bg-input);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius);
  padding: 0 12px;
  height: 36px;
  color: var(--ix-text-muted);
  font-size: var(--ifx-font-size-14);
  cursor: text;
}
.ix-search i { font-size: var(--ifx-font-size-16); }
.ix-search input {
  background: none;
  border: none;
  outline: none;
  color: var(--ix-text-primary);
  font-size: var(--ifx-font-size-14);
  width: 100%;
  font-family: var(--ix-font);
}
.ix-search input::placeholder { color: var(--ix-text-muted); }

.ix-nav-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: var(--ifx-space-4);
}
.ix-nav-btn {
  width: 36px; height: 36px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--ix-text-secondary);
  cursor: pointer;
  position: relative;
  transition: background 0.15s;
  background: none;
  border: none;
}
.ix-nav-btn:hover { background: var(--ix-bg-hover); color: var(--ix-text-primary); }
.ix-nav-btn i { font-size: var(--ifx-font-size-20); }
.ix-nav-dot {
  position: absolute;
  top: 6px; right: 6px;
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--ix-danger);
  border: 2px solid var(--ix-bg-navbar);
}
.ix-avatar {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--ix-accent-soft);
  border: 2px solid var(--ix-accent);
  display: flex; align-items: center; justify-content: center;
  font-weight: var(--ifx-font-weight-semibold); font-size: var(--ifx-font-size-14);
  color: var(--ix-accent);
  cursor: pointer;
  margin-left: 4px;
}
.ix-avatar img {
  width: 100%; height: 100%;
  border-radius: 50%; object-fit: cover;
}
.ix-avatar-online { position: relative; }
.ix-avatar-online::after {
  content: '';
  position: absolute;
  bottom: 1px; right: 1px;
  width: 9px; height: 9px;
  border-radius: 50%;
  background: var(--ix-success);
  border: 2px solid var(--ix-bg-navbar);
}

/* -----------------------------------------------------------------
   6. PAGE HEADER
   ----------------------------------------------------------------- */
.ix-page-title {
  margin-bottom: var(--ifx-space-4);
  color: var(--ix-text-primary);
}

/* Headings → typography.css (.ix-h1 … .ix-h6) */

.ix-breadcrumb {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-sm);
  font-size: var(--ifx-text-body-sm-size);
  color: var(--ix-text-muted);
  margin-bottom: var(--ifx-stack-lg);
}
.ix-breadcrumb a {
  color: var(--ix-text-secondary);
  text-decoration: none;
}
.ix-breadcrumb a:hover { color: var(--ix-accent); }

/* -----------------------------------------------------------------
   7. GRID
   ----------------------------------------------------------------- */
.ix-grid { display: grid; gap: var(--ifx-grid-gutter); }
.ix-grid-1  { grid-template-columns: 1fr; }
.ix-grid-2  { grid-template-columns: repeat(2, 1fr); }
.ix-grid-3  { grid-template-columns: repeat(3, 1fr); }
.ix-grid-4  { grid-template-columns: repeat(4, 1fr); }
.ix-grid-auto { grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }

/* -----------------------------------------------------------------
   8. CARD
   ----------------------------------------------------------------- */
.ix-card {
  background: var(--ix-bg-card);
  border-radius: var(--ix-radius-lg);
  border: 1px solid var(--ix-border);
}
.ix-card-header {
  padding: var(--ifx-inset-card-header);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}
/* Card title/subtitle → typography.css */

.ix-card-body { padding: var(--ifx-inset-card-body); }
.ix-card-footer {
  padding: var(--ifx-inset-card-footer);
  border-top: 1px solid var(--ix-border);
}

/* -----------------------------------------------------------------
   9. STAT / METRIC CARD
   ----------------------------------------------------------------- */
.ix-stat-card {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: var(--ifx-inset-card);
  display: flex;
  align-items: center;
  gap: var(--ifx-gap-md);
}
.ix-stat-icon {
  width: 44px; height: 44px;
  border-radius: var(--ix-radius);
  display: flex; align-items: center; justify-content: center;
  font-size: var(--ifx-font-size-24);
  flex-shrink: 0;
}
.ix-stat-icon.accent  { background: var(--ix-accent-soft);  color: var(--ix-accent);  }
.ix-stat-icon.success { background: var(--ix-success-soft); color: var(--ix-success); }
.ix-stat-icon.warning { background: var(--ix-warning-soft); color: var(--ix-warning); }
.ix-stat-icon.danger  { background: var(--ix-danger-soft);  color: var(--ix-danger);  }
.ix-stat-icon.info    { background: var(--ix-info-soft);    color: var(--ix-info);    }
.ix-card-title { margin-bottom: 2px; }

/* Stat typography → typography.css (.ix-stat-value, .ix-stat-trend) */
.ix-stat-label {
  color: var(--ix-text-muted);
  margin-bottom: var(--ifx-space-4);
}
.ix-stat-trend { margin-top: var(--ifx-space-4); }
.ix-stat-trend.up   { color: var(--ix-success); }
.ix-stat-trend.down { color: var(--ix-danger); }

/* -----------------------------------------------------------------
   10. BADGE / CHIP
   ----------------------------------------------------------------- */
.ix-badge {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-semibold);
  line-height: 1;
  padding: var(--ifx-space-badge-y) var(--ifx-space-badge-x);
  border-radius: 20px;
}
.ix-badge-primary { background: var(--ix-accent); color: var(--color-text-on-primary); }
.ix-badge-danger  { background: var(--ix-danger); color: var(--color-text-on-danger); }
.ix-badge-success { background: var(--ix-success); color: var(--color-text-on-success); }
.ix-badge-warning { background: var(--ix-warning); color: var(--color-text-on-warning); }
.ix-badge-info    { background: var(--ix-info); color: var(--color-text-on-info); }

.ix-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--ifx-inline-xs);
  padding: var(--ifx-space-chip-y) var(--ifx-space-chip-x);
  border-radius: 20px;
  font-size: var(--ifx-text-body-sm-size);
  font-weight: var(--ifx-font-weight-medium);
}
.ix-chip-primary { background: var(--ix-accent-soft);  color: var(--ix-accent);  }
.ix-chip-success { background: var(--ix-success-soft); color: var(--ix-success); }
.ix-chip-warning { background: var(--ix-warning-soft); color: var(--ix-warning); }
.ix-chip-danger  { background: var(--ix-danger-soft);  color: var(--ix-danger);  }
.ix-chip-info    { background: var(--ix-info-soft);    color: var(--ix-info);    }
.ix-chip-outline {
  background: transparent;
  border: 1px solid var(--ix-border);
  color: var(--ix-text-secondary);
}

/* -----------------------------------------------------------------
   11. BUTTONS
   ----------------------------------------------------------------- */
.ix-btn {
  display: inline-flex;
  align-items: center;
  gap: var(--ifx-space-button-icon-gap);
  padding: var(--ifx-space-button-y) var(--ifx-space-button-x);
  border-radius: var(--ix-radius);
  font-size: var(--ifx-text-btn-md-size);
  font-weight: var(--ifx-text-btn-md-weight);
  cursor: pointer;
  border: none;
  transition: all 0.15s;
  font-family: var(--ifx-font-primary);
  text-decoration: none;
  white-space: nowrap;
}
.ix-btn-primary {
  background: var(--ix-accent);
  color: var(--color-text-on-primary);
}
.ix-btn-primary:hover { background: var(--ix-accent-hover); }
.ix-btn-primary:active { transform: scale(0.98); }

.ix-btn-success { background: var(--ix-success); color: var(--color-text-on-success); }
.ix-btn-danger  { background: var(--ix-danger);  color: var(--color-text-on-danger); }
.ix-btn-warning { background: var(--ix-warning); color: var(--color-text-on-warning); }

.ix-btn-outline {
  background: transparent;
  color: var(--ix-text-secondary);
  border: 1px solid var(--ix-border);
}
.ix-btn-outline:hover {
  background: var(--ix-bg-hover);
  color: var(--ix-text-primary);
}
.ix-btn-ghost {
  background: transparent;
  color: var(--ix-text-secondary);
  border: none;
}
.ix-btn-ghost:hover { background: var(--ix-bg-hover); color: var(--ix-text-primary); }

.ix-btn-icon {
  width: 32px; height: 32px;
  padding: 0;
  justify-content: center;
  background: transparent;
  color: var(--ix-text-secondary);
  border: 1px solid transparent;
  border-radius: var(--ix-radius);
}
.ix-btn-icon:hover { background: var(--ix-bg-hover); color: var(--ix-text-primary); }

.ix-btn-sm { padding: var(--ifx-space-button-sm-y) var(--ifx-space-button-sm-x); font-size: var(--ifx-font-size-12); }
.ix-btn-lg { padding: var(--ifx-space-button-lg-y) var(--ifx-space-button-lg-x); font-size: var(--ifx-font-size-16); }

/* -----------------------------------------------------------------
   12. FORM ELEMENTS
   ----------------------------------------------------------------- */
.ix-form-group { margin-bottom: var(--ifx-stack-md); }
.ix-label {
  display: block;
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-medium);
  color: var(--ix-text-secondary);
  margin-bottom: var(--ifx-inline-sm);
}
.ix-input,
.ix-select,
.ix-textarea {
  width: 100%;
  background: var(--ix-bg-input);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius);
  padding: var(--ifx-space-input-y) var(--ifx-space-input-x);
  color: var(--ix-text-primary);
  font-size: var(--ifx-font-size-14);
  font-family: var(--ix-font);
  transition: border-color 0.15s;
  outline: none;
}
.ix-input:focus,
.ix-select:focus,
.ix-textarea:focus {
  border-color: var(--ix-accent);
  box-shadow: 0 0 0 3px var(--ix-accent-soft);
}
.ix-input::placeholder { color: var(--ix-text-muted); }
.ix-textarea { resize: vertical; min-height: 80px; }
.ix-select { appearance: none; cursor: pointer; }

/* -----------------------------------------------------------------
   13. TABLE
   ----------------------------------------------------------------- */
.ix-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--ifx-font-size-14);
}
.ix-table th {
  text-align: left;
  padding: 10px 12px;
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-semibold);
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: var(--ix-text-muted);
  border-bottom: 1px solid var(--ix-border);
  white-space: nowrap;
}
.ix-table td {
  padding: var(--ifx-space-12);
  border-bottom: 1px solid var(--ix-border);
  color: var(--ix-text-secondary);
  vertical-align: middle;
}
.ix-table tbody tr:last-child td { border-bottom: none; }
.ix-table tbody tr:hover td { background: rgba(255,255,255,0.02); }
.ix-table-responsive { overflow-x: auto; }

/* -----------------------------------------------------------------
   14. PROGRESS BAR
   ----------------------------------------------------------------- */
.ix-progress {
  height: 6px;
  background: var(--ix-bg-input);
  border-radius: 3px;
  overflow: hidden;
}
.ix-progress-bar {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s ease;
  background: var(--ix-accent);
}
.ix-progress-success .ix-progress-bar { background: var(--ix-success); }
.ix-progress-warning .ix-progress-bar { background: var(--ix-warning); }
.ix-progress-danger  .ix-progress-bar { background: var(--ix-danger); }
.ix-progress-info    .ix-progress-bar { background: var(--ix-info); }
.ix-progress-lg { height: 10px; border-radius: 5px; }

/* -----------------------------------------------------------------
   15. AVATAR
   ----------------------------------------------------------------- */
.ix-avatar-sm {
  width: 28px; height: 28px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-semibold);
  flex-shrink: 0;
}
.ix-avatar-md {
  width: 38px; height: 38px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-semibold);
  flex-shrink: 0;
}
.ix-avatar-lg {
  width: 56px; height: 56px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--ifx-font-size-20);
  font-weight: var(--ifx-font-weight-semibold);
  flex-shrink: 0;
}
.ix-avatar-accent  { background: var(--ix-accent-soft);  color: var(--ix-accent); }
.ix-avatar-success { background: var(--ix-success-soft); color: var(--ix-success); }
.ix-avatar-warning { background: var(--ix-warning-soft); color: var(--ix-warning); }
.ix-avatar-danger  { background: var(--ix-danger-soft);  color: var(--ix-danger); }
.ix-avatar-info    { background: var(--ix-info-soft);    color: var(--ix-info); }

/* -----------------------------------------------------------------
   16. DIVIDER
   ----------------------------------------------------------------- */
.ix-divider {
  border: none;
  border-top: 1px solid var(--ix-border);
  margin: 12px 0;
}

/* -----------------------------------------------------------------
   17. LIST
   ----------------------------------------------------------------- */
.ix-list { list-style: none; }
.ix-list-item {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-12);
  padding: 10px 0;
  border-bottom: 1px solid var(--ix-border);
}
.ix-list-item:last-child { border-bottom: none; }

/* -----------------------------------------------------------------
   18. DROPDOWN
   ----------------------------------------------------------------- */
.ix-dropdown { position: relative; display: inline-block; }
.ix-dropdown-menu {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  min-width: 160px;
  padding: 6px 0;
  z-index: var(--ifx-z-sticky);
  box-shadow: var(--shadow-dropdown);
  display: none;
}
.ix-dropdown.open .ix-dropdown-menu { display: block; }
.ix-dropdown-item {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-sm);
  padding: var(--ifx-space-8) 16px;
  color: var(--ix-text-secondary);
  cursor: pointer;
  transition: var(--transition-color);
  text-decoration: none;
}
.ix-dropdown-item:hover { background: var(--ix-bg-hover); color: var(--ix-text-primary); }
.ix-dropdown-divider {
  border: none;
  border-top: 1px solid var(--ix-border);
  margin: 4px 0;
}

/* -----------------------------------------------------------------
   19. MODAL
   ----------------------------------------------------------------- */
.ix-modal-overlay {
  position: fixed; inset: 0;
  background: var(--color-scrim);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: var(--ifx-z-modal);
}
.ix-modal {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  width: 520px;
  max-width: calc(100vw - 32px);
  max-height: calc(100vh - 64px);
  display: flex;
  flex-direction: column;
}
.ix-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--ifx-inset-card-header);
  border-bottom: 1px solid var(--ix-border);
}
.ix-modal-title { font-size: var(--ifx-font-size-16); font-weight: var(--ifx-font-weight-semibold); color: var(--ix-text-primary); }
.ix-modal-body { padding: var(--ifx-inset-dialog); overflow-y: auto; flex: 1; }
.ix-modal-footer {
  padding: var(--ifx-inset-card-footer);
  border-top: 1px solid var(--ix-border);
  display: flex;
  gap: var(--ifx-gap-xs);
  justify-content: flex-end;
}

/* -----------------------------------------------------------------
   20. TOAST / ALERT
   ----------------------------------------------------------------- */
.ix-alert {
  padding: var(--ifx-inset-widget);
  border-radius: var(--ix-radius);
  border-left: 4px solid;
  display: flex;
  align-items: flex-start;
  gap: var(--ifx-inline-md);
  margin-bottom: var(--ifx-space-12);
}
.ix-alert-primary { background: var(--ix-accent-soft);  border-color: var(--ix-accent);  color: var(--ix-accent);  }
.ix-alert-success { background: var(--ix-success-soft); border-color: var(--ix-success); color: var(--ix-success); }
.ix-alert-warning { background: var(--ix-warning-soft); border-color: var(--ix-warning); color: var(--ix-warning); }
.ix-alert-danger  { background: var(--ix-danger-soft);  border-color: var(--ix-danger);  color: var(--ix-danger);  }
.ix-alert-info    { background: var(--ix-info-soft);    border-color: var(--ix-info);    color: var(--ix-info);    }
.ix-alert-title { font-weight: var(--ifx-font-weight-semibold); font-size: var(--ifx-font-size-14); }
.ix-alert-text  { font-size: var(--ifx-font-size-14); color: var(--ix-text-secondary); margin-top: 2px; }

/* -----------------------------------------------------------------
   21. UTILITY CLASSES
   ----------------------------------------------------------------- */
.ix-text-primary   { color: var(--ix-text-primary) !important; }
.ix-text-secondary { color: var(--ix-text-secondary) !important; }
.ix-text-muted     { color: var(--ix-text-muted) !important; }
.ix-text-accent    { color: var(--ix-accent) !important; }
.ix-text-success   { color: var(--ix-success) !important; }
.ix-text-warning   { color: var(--ix-warning) !important; }
.ix-text-danger    { color: var(--ix-danger) !important; }
.ix-text-info      { color: var(--ix-info) !important; }

.ix-fw-400 { font-weight: var(--ifx-font-weight-regular); }
.ix-fw-500 { font-weight: var(--ifx-font-weight-medium); }
.ix-fw-600 { font-weight: var(--ifx-font-weight-semibold); }
.ix-fw-700 { font-weight: var(--ifx-font-weight-bold); }

/* Font-size utilities → typography.css (.ix-fs-*) */

.ix-d-flex      { display: flex; }
.ix-align-center { align-items: center; }
.ix-justify-between { justify-content: space-between; }
/* gap/margin/padding utilities → spacing.css */

.ix-rounded    { border-radius: var(--ix-radius); }
.ix-rounded-lg { border-radius: var(--ix-radius-lg); }
.ix-rounded-full { border-radius: 50%; }

/* -----------------------------------------------------------------
   22. SCROLLBAR (global)
   ----------------------------------------------------------------- */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--ix-border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: rgba(207,211,236,0.25); }

/* -----------------------------------------------------------------
   23. FILTER BAR (User List pattern)
   ----------------------------------------------------------------- */
.ix-filter-bar {
  padding: var(--ifx-inset-card);
  border-bottom: 1px solid var(--ix-border);
}
.ix-filter-bar-title {
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-primary);
  margin-bottom: var(--ifx-space-12);
}
.ix-filter-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--ifx-space-12);
}
.ix-filter-row-2 { grid-template-columns: repeat(2, 1fr); }
.ix-filter-row-4 { grid-template-columns: repeat(4, 1fr); }

/* -----------------------------------------------------------------
   24. OFFCANVAS / DRAWER
   ----------------------------------------------------------------- */
.ix-offcanvas {
  position: fixed;
  top: 0; right: 0; bottom: 0;
  width: 400px;
  max-width: 100vw;
  background: var(--ix-bg-card);
  border-left: 1px solid var(--ix-border);
  z-index: 1050;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform 0.3s ease;
}
.ix-offcanvas.open { transform: translateX(0); }
.ix-offcanvas-overlay {
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1040;
  display: none;
}
.ix-offcanvas-overlay.open { display: block; }
.ix-offcanvas-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--ifx-inset-card);
  border-bottom: 1px solid var(--ix-border);
  flex-shrink: 0;
}
.ix-offcanvas-title {
  font-size: var(--ifx-font-size-16);
  font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-primary);
}
.ix-offcanvas-body {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
}
.ix-offcanvas-footer {
  padding: var(--ifx-inset-card);
  border-top: 1px solid var(--ix-border);
  display: flex;
  gap: var(--ifx-space-8);
  flex-shrink: 0;
}

/* -----------------------------------------------------------------
   25. TABLE ACTIONS ROW (search + export + add button)
   ----------------------------------------------------------------- */
.ix-table-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--ifx-space-12) 20px;
  gap: var(--ifx-space-12);
  flex-wrap: wrap;
}
.ix-table-search {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
  background: var(--ix-bg-input);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius);
  padding: 0 12px;
  height: 36px;
  min-width: 220px;
}
.ix-table-search i { font-size: var(--ifx-font-size-16); color: var(--ix-text-muted); }
.ix-table-search input {
  background: none; border: none; outline: none;
  color: var(--ix-text-primary); font-size: var(--ifx-font-size-14);
  font-family: var(--ix-font); width: 100%;
}
.ix-table-search input::placeholder { color: var(--ix-text-muted); }
.ix-table-actions { display: flex; gap: var(--ifx-space-8); align-items: center; }

/* -----------------------------------------------------------------
   26. PAGINATION
   ----------------------------------------------------------------- */
.ix-pagination {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-4);
  padding: var(--ifx-space-12) 20px;
}
.ix-page-btn {
  min-width: 32px; height: 32px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--ix-radius);
  font-size: var(--ifx-font-size-14); cursor: pointer;
  color: var(--ix-text-secondary);
  background: none;
  border: 1px solid transparent;
  transition: all 0.15s;
}
.ix-page-btn:hover { background: var(--ix-bg-hover); color: var(--ix-text-primary); }
.ix-page-btn.active {
  background: var(--ix-accent);
  color: #fff;
  border-color: var(--ix-accent);
}
.ix-page-btn:disabled { opacity: 0.4; cursor: not-allowed; }
.ix-page-info {
  font-size: var(--ifx-font-size-14); color: var(--ix-text-muted);
  margin-left: auto;
}

/* -----------------------------------------------------------------
   27. STAT CARD — horizontal variant (User List style)
   ----------------------------------------------------------------- */
.ix-stat-card-h {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: var(--ifx-inset-card);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ifx-space-12);
}
.ix-stat-card-h .ix-stat-info { flex: 1; }
.ix-stat-card-h .ix-stat-label {
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-medium);
  color: var(--ix-text-primary);
  margin-bottom: var(--ifx-space-4);
}
.ix-stat-card-h .ix-stat-value {
  font-size: var(--ifx-font-size-24);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-primary);
  line-height: 1;
  margin-bottom: var(--ifx-space-4);
}
.ix-stat-card-h .ix-stat-sub {
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
}
.ix-stat-card-h .ix-stat-icon {
  width: 48px; height: 48px;
  border-radius: var(--ix-radius);
  display: flex; align-items: center; justify-content: center;
  font-size: 26px;
  flex-shrink: 0;
}

/* -----------------------------------------------------------------
   28. FOOTER
   ----------------------------------------------------------------- */
.ix-footer {
  padding: var(--ifx-space-16) 24px;
  border-top: 1px solid var(--ix-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-muted);
  flex-wrap: wrap;
  gap: var(--ifx-space-8);
  margin-top: auto;
}
.ix-footer a { color: var(--ix-text-secondary); text-decoration: none; }
.ix-footer a:hover { color: var(--ix-accent); }
.ix-footer-links { display: flex; gap: var(--ifx-space-16); }

/* -----------------------------------------------------------------
   29. CHECKBOX (table row select)
   ----------------------------------------------------------------- */
.ix-checkbox {
  width: 16px; height: 16px;
  border-radius: 3px;
  border: 2px solid var(--ix-border);
  background: var(--ix-bg-input);
  cursor: pointer;
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all 0.15s;
}
.ix-checkbox:checked {
  background: var(--ix-accent);
  border-color: var(--ix-accent);
}
.ix-checkbox:checked::after {
  content: '';
  width: 8px; height: 5px;
  border-left: 2px solid #fff;
  border-bottom: 2px solid #fff;
  transform: rotate(-45deg) translate(1px, -1px);
}
.ix-checkbox:indeterminate {
  background: var(--ix-accent);
  border-color: var(--ix-accent);
}
.ix-checkbox:indeterminate::after {
  content: '';
  width: 8px; height: 2px;
  background: #fff;
}

/* -----------------------------------------------------------------
   30. USER ROW AVATAR (inline in table)
   ----------------------------------------------------------------- */
.ix-user-cell {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-md);
}
.ix-user-name {
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-medium);
  color: var(--ix-text-primary);
  line-height: 1.3;
}
.ix-user-email {
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
}

/* -----------------------------------------------------------------
   31. ROLE CARD GRID (Roles page)
   ----------------------------------------------------------------- */
.ix-role-card {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: var(--ifx-space-16);
}
.ix-role-card__top,
.ix-role-card__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.ix-role-card__count {
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-muted);
}
.ix-role-card--add {
  flex-direction: row;
  align-items: center;
  gap: var(--ifx-space-20);
}
.ix-role-card__add-body { flex: 1; }
.ix-role-card__add-hint {
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
  margin: 0;
}
.ix-role-card__add-icon {
  font-size: 64px;
  color: var(--ix-accent);
  opacity: 0.3;
  flex-shrink: 0;
}
.ix-avatar-group {
  display: flex;
  align-items: center;
}
.ix-avatar-group .ix-avatar-sm {
  margin-left: -8px;
  border: 2px solid var(--ix-bg-card);
}
.ix-avatar-group .ix-avatar-sm:first-child { margin-left: 0; }
.ix-avatar-group-count {
  width: 28px; height: 28px;
  border-radius: 50%;
  background: var(--ix-bg-hover);
  border: 2px solid var(--ix-bg-card);
  display: inline-flex; align-items: center; justify-content: center;
  font-size: var(--ifx-font-size-10); font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-secondary);
  margin-left: -8px;
}
.ix-role-name {
  font-size: var(--ifx-font-size-16); font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-primary);
  margin-bottom: 2px;
}
.ix-role-edit {
  font-size: var(--ifx-font-size-14); color: var(--ix-accent);
  text-decoration: none; cursor: pointer;
  background: none; border: none; padding: 0;
  font-family: inherit;
}
.ix-role-edit:hover { text-decoration: underline; }

.ix-input[readonly],
.ix-input:disabled {
  opacity: 0.72;
  cursor: not-allowed;
  background: var(--ix-bg-hover);
  color: var(--ix-text-secondary);
}
.ix-field-hint {
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  margin-top: var(--ifx-space-4);
}

/* -----------------------------------------------------------------
   32. PERMISSION TABLE (Role modal)
   ----------------------------------------------------------------- */
.ix-perm-table { width: 100%; border-collapse: collapse; font-size: var(--ifx-font-size-14); }
.ix-perm-group-row td {
  padding: 14px 12px 6px;
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ix-text-muted);
  border-bottom: none;
  background: rgba(255, 255, 255, 0.02);
}
.ix-perm-table td { padding: 10px 12px; border-bottom: 1px solid var(--ix-border); }
.ix-perm-table tr:last-child td { border-bottom: none; }
.ix-perm-name { font-weight: var(--ifx-font-weight-medium); color: var(--ix-text-primary); white-space: nowrap; }
.ix-perm-actions { display: flex; gap: var(--ifx-space-16); justify-content: flex-end; }
.ix-perm-check {
  display: flex; align-items: center; gap: var(--ifx-inline-sm);
  font-size: var(--ifx-font-size-14); color: var(--ix-text-secondary);
  cursor: pointer;
}

/* -----------------------------------------------------------------
   33. TOP 10 MARKET BLOCK — multi-line compare (Ngành / Họ / Chủ đề)
   ----------------------------------------------------------------- */
.ix-top10-market {
  --ix-top10-h: 340px;
  --ix-top10-yw: 52px;
  --ix-top10-rw: 168px;
  position: relative;
  min-height: var(--ix-top10-h);
}
.ix-top10-market__inner {
  display: grid;
  grid-template-columns: var(--ix-top10-yw) 1fr var(--ix-top10-rw);
  gap: 0 12px;
  align-items: stretch;
  min-height: var(--ix-top10-h);
}
.ix-top10-market__yaxis {
  position: relative;
  height: var(--ix-top10-h);
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  font-variant-numeric: tabular-nums;
}
.ix-top10-market__ytick {
  position: absolute;
  right: 0;
  transform: translateY(-50%);
  line-height: 1;
  white-space: nowrap;
}
.ix-top10-market__plot {
  position: relative;
  height: var(--ix-top10-h);
  min-width: 0;
}
.ix-top10-market__plot svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}
.ix-top10-market__grid-line {
  stroke: rgba(207, 211, 236, 0.08);
  stroke-width: 1;
  stroke-dasharray: 4 4;
}
.ix-top10-market__zero-line {
  stroke: rgba(207, 211, 236, 0.35);
  stroke-width: 1;
}
.ix-top10-market__line {
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.ix-top10-market__xlabels {
  display: flex;
  justify-content: space-between;
  margin-top: var(--ifx-space-8);
  padding: 0 2px;
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  font-variant-numeric: tabular-nums;
}
.ix-top10-market__legend {
  position: relative;
  height: var(--ix-top10-h);
  font-size: var(--ifx-font-size-12);
}
.ix-top10-market__legend-item {
  position: absolute;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
  transform: translateY(-50%);
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ix-top10-market__legend-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.ix-top10-market__legend-name {
  color: var(--ix-text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
}
.ix-top10-market__legend-val {
  margin-left: auto;
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-semibold);
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}
.ix-top10-market__legend-val.is-up { color: var(--ix-success); }
.ix-top10-market__legend-val.is-down { color: var(--ix-danger); }
.ix-top10-market__legend-val.is-flat { color: var(--ix-text-muted); }
.ix-top10-market__axis-label {
  font-size: var(--ifx-font-size-10);
  fill: var(--ix-text-muted);
  font-family: var(--ix-font);
}
.ix-top10-market__crosshair {
  stroke: rgba(207, 211, 236, 0.2);
  stroke-width: 1;
  stroke-dasharray: 3 3;
  pointer-events: none;
}

/* -----------------------------------------------------------------
   34. CHART PLACEHOLDER CARD
   ----------------------------------------------------------------- */
.ix-chart-placeholder {
  height: 200px;
  background: linear-gradient(
    135deg,
    rgba(105,108,255,0.06) 0%,
    rgba(105,108,255,0.02) 100%
  );
  border-radius: var(--ix-radius);
  display: flex; align-items: center; justify-content: center;
  color: var(--ix-text-muted); font-size: var(--ifx-font-size-14);
}

/* -----------------------------------------------------------------
   34. WIDGET SEPARATOR (eCommerce / Product List hero strip)
   ----------------------------------------------------------------- */
.ix-widget-separator {
  display: flex;
  align-items: stretch;
  flex-wrap: wrap;
}
.ix-widget-separator-item {
  flex: 1;
  min-width: 200px;
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ifx-space-12);
  border-right: 1px solid var(--ix-border);
}
.ix-widget-separator-item:last-child { border-right: none; }
.ix-widget-sep-label {
  font-size: var(--ifx-font-size-14); color: var(--ix-text-secondary);
  margin-bottom: var(--ifx-space-4);
}
.ix-widget-sep-value {
  font-size: var(--ifx-font-size-24); font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-primary); line-height: 1;
  margin-bottom: var(--ifx-space-4);
}
.ix-widget-sep-sub { font-size: var(--ifx-font-size-12); color: var(--ix-text-muted); }

/* -----------------------------------------------------------------
   35. TABS (nav pills / horizontal tabs)
   ----------------------------------------------------------------- */
.ix-tabs {
  display: flex;
  gap: 2px;
  background: var(--ix-bg-input);
  border-radius: var(--ix-radius);
  padding: 3px;
  width: fit-content;
}
.ix-tab {
  padding: 6px 14px;
  border-radius: calc(var(--ix-radius) - 2px);
  font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-medium);
  color: var(--ix-text-muted);
  cursor: pointer;
  transition: all .15s;
  border: none; background: none;
  font-family: var(--ix-font);
}
.ix-tab:hover { color: var(--ix-text-primary); }
.ix-tab.active {
  background: var(--ix-bg-card);
  color: var(--ix-text-primary);
  box-shadow: 0 1px 4px rgba(0,0,0,0.3);
}

.ix-nav-pills { display: flex; flex-direction: column; gap: 2px; }
.ix-nav-pill {
  display: flex; align-items: center; gap: var(--ifx-space-8);
  padding: 9px 14px;
  border-radius: var(--ix-radius);
  font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-medium);
  color: var(--ix-text-secondary);
  cursor: pointer; border: none;
  background: none; font-family: var(--ix-font);
  transition: all .15s; text-align: left;
}
.ix-nav-pill:hover { background: var(--ix-bg-hover); color: var(--ix-text-primary); }
.ix-nav-pill.active { background: var(--ix-bg-active); color: var(--ix-accent); }

/* -----------------------------------------------------------------
   36. TWO-COLUMN LAYOUT (Add Product)
   ----------------------------------------------------------------- */
.ix-layout-main { display: flex; gap: var(--ifx-space-24); align-items: flex-start; }
.ix-layout-main-col { flex: 1; min-width: 0; }
.ix-layout-side-col { width: 320px; flex-shrink: 0; }

/* -----------------------------------------------------------------
   37. HERO BANNER CARD (eCommerce congratulations)
   ----------------------------------------------------------------- */
.ix-hero-card {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: 20px 24px;
  display: flex;
  align-items: center;
  gap: var(--ifx-space-20);
}
.ix-hero-card-body { flex: 1; }
.ix-hero-card-img {
  width: 120px; flex-shrink: 0; text-align: center;
}
.ix-hero-card-img i { font-size: 80px; color: var(--ix-accent); opacity: 0.5; }

/* -----------------------------------------------------------------
   38. INLINE STAT ROW (eCommerce stats strip)
   ----------------------------------------------------------------- */
.ix-stat-row {
  display: flex; flex-wrap: wrap; gap: var(--ifx-space-20);
}
.ix-stat-row-item {
  display: flex; align-items: center; gap: var(--ifx-space-12);
}
.ix-stat-row-icon {
  width: 36px; height: 36px;
  border-radius: var(--ix-radius);
  display: flex; align-items: center; justify-content: center;
  font-size: var(--ifx-font-size-18); flex-shrink: 0;
}
.ix-stat-row-label { font-size: var(--ifx-font-size-12); color: var(--ix-text-muted); }
.ix-stat-row-value { font-size: var(--ifx-font-size-16); font-weight: var(--ifx-font-weight-semibold); color: var(--ix-text-primary); }

/* -----------------------------------------------------------------
   39. FILE UPLOAD DROP ZONE
   ----------------------------------------------------------------- */
.ix-dropzone {
  border: 2px dashed var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: 40px 20px;
  text-align: center;
  cursor: pointer;
  transition: border-color .2s, background .2s;
}
.ix-dropzone:hover {
  border-color: var(--ix-accent);
  background: var(--ix-accent-soft);
}
.ix-dropzone-icon { font-size: 40px; color: var(--ix-text-muted); margin-bottom: var(--ifx-space-12); }
.ix-dropzone-title { font-size: var(--ifx-font-size-16); font-weight: var(--ifx-font-weight-medium); color: var(--ix-text-primary); margin-bottom: var(--ifx-space-4); }
.ix-dropzone-sub { font-size: var(--ifx-font-size-14); color: var(--ix-text-muted); margin-bottom: var(--ifx-space-12); }

/* -----------------------------------------------------------------
   40. SWITCH TOGGLE
   ----------------------------------------------------------------- */
.ix-switch {
  position: relative;
  display: inline-block;
  width: 40px; height: 22px;
  flex-shrink: 0;
}
.ix-switch input { opacity: 0; width: 0; height: 0; }
.ix-switch-slider {
  position: absolute; inset: 0;
  background: var(--ix-bg-input);
  border: 1px solid var(--ix-border);
  border-radius: 11px;
  cursor: pointer;
  transition: background .2s;
}
.ix-switch-slider::before {
  content: '';
  position: absolute;
  width: 16px; height: 16px;
  left: 2px; top: 2px;
  background: var(--ix-text-muted);
  border-radius: 50%;
  transition: transform .2s;
}
.ix-switch input:checked + .ix-switch-slider {
  background: var(--ix-accent);
  border-color: var(--ix-accent);
}
.ix-switch input:checked + .ix-switch-slider::before {
  transform: translateX(18px);
  background: #fff;
}

/* -----------------------------------------------------------------
   41. TIMELINE (Order Details / Shipping Activity)
   ----------------------------------------------------------------- */
.ix-timeline { list-style: none; padding: 0; margin: 0; }
.ix-timeline-item {
  position: relative;
  padding-left: 28px;
  padding-bottom: 20px;
}
.ix-timeline-item:last-child { padding-bottom: 0; }
.ix-timeline-item::before {
  content: '';
  position: absolute;
  left: 7px; top: 20px; bottom: 0;
  width: 2px;
  background: var(--ix-border);
}
.ix-timeline-item:last-child::before { display: none; }
.ix-timeline-dot {
  position: absolute;
  left: 0; top: 4px;
  width: 16px; height: 16px;
  border-radius: 50%;
  border: 2px solid var(--ix-accent);
  background: var(--ix-bg-card);
}
.ix-timeline-dot.filled { background: var(--ix-accent); }
.ix-timeline-dot.success { border-color: var(--ix-success); }
.ix-timeline-dot.filled.success { background: var(--ix-success); }
.ix-timeline-dot.muted { border-color: var(--ix-border); }
.ix-timeline-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--ifx-space-4);
}
.ix-timeline-title { font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-semibold); color: var(--ix-text-primary); }
.ix-timeline-time { font-size: var(--ifx-font-size-12); color: var(--ix-text-muted); }
.ix-timeline-body { font-size: var(--ifx-font-size-14); color: var(--ix-text-muted); }

/* -----------------------------------------------------------------
   42. DETAIL PAGE LAYOUT
   ----------------------------------------------------------------- */
.ix-detail-layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: var(--ifx-space-24);
  align-items: flex-start;
}
.ix-info-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: var(--ifx-font-size-14);
  margin-bottom: 6px;
}
.ix-info-row:last-child { margin-bottom: 0; }
.ix-info-label { color: var(--ix-text-muted); }
.ix-info-value { font-weight: var(--ifx-font-weight-medium); color: var(--ix-text-primary); }

/* -----------------------------------------------------------------
   43. REFERRAL STEP CARDS
   ----------------------------------------------------------------- */
.ix-referral-steps {
  display: flex;
  gap: var(--ifx-space-24);
  flex-wrap: wrap;
  justify-content: space-between;
}
.ix-referral-step {
  flex: 1;
  min-width: 160px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: var(--ifx-space-8);
}
.ix-referral-step-icon {
  width: 72px; height: 72px;
  border-radius: 50%;
  border: 2px dashed var(--ix-accent);
  display: flex; align-items: center; justify-content: center;
  font-size: 36px;
  color: var(--ix-accent);
  flex-shrink: 0;
}
.ix-referral-step-title { font-size: var(--ifx-font-size-14); color: var(--ix-text-secondary); }
.ix-referral-step-reward { font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-bold); color: var(--ix-accent); }

/* -----------------------------------------------------------------
   44. CHAT LAYOUT
   ----------------------------------------------------------------- */
.ix-chat-layout {
  display: flex;
  height: calc(100vh - 140px);
  min-height: 600px;
  overflow: hidden;
  border-radius: var(--ix-radius-lg);
  border: 1px solid var(--ix-border);
  background: var(--ix-bg-card);
}
.ix-chat-sidebar {
  width: 280px;
  flex-shrink: 0;
  border-right: 1px solid var(--ix-border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.ix-chat-sidebar-header {
  padding: var(--ifx-inset-widget);
  border-bottom: 1px solid var(--ix-border);
  flex-shrink: 0;
}
.ix-chat-list {
  flex: 1;
  overflow-y: auto;
  padding: var(--ifx-space-8) 0;
}
.ix-chat-item {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-md);
  padding: 10px 16px;
  cursor: pointer;
  transition: background .15s;
}
.ix-chat-item:hover { background: var(--ix-bg-hover); }
.ix-chat-item.active { background: var(--ix-bg-active); }
.ix-chat-item-name { font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-medium); color: var(--ix-text-primary); line-height: 1.2; }
.ix-chat-item-preview { font-size: var(--ifx-font-size-12); color: var(--ix-text-muted); }
.ix-chat-item-time { font-size: var(--ifx-font-size-10); color: var(--ix-text-muted); white-space: nowrap; }
.ix-chat-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-width: 0;
}
.ix-chat-header {
  padding: var(--ifx-space-12) 20px;
  border-bottom: 1px solid var(--ix-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}
.ix-chat-body {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: var(--ifx-space-16);
}
.ix-chat-msg {
  display: flex;
  gap: var(--ifx-inline-md);
  align-items: flex-end;
}
.ix-chat-msg.sent { flex-direction: row-reverse; }
.ix-chat-bubble {
  max-width: 60%;
  padding: 10px 14px;
  border-radius: 12px;
  font-size: var(--ifx-font-size-14);
  line-height: 1.5;
  color: var(--ix-text-primary);
  background: var(--ix-bg-hover);
}
.ix-chat-msg.sent .ix-chat-bubble {
  background: var(--ix-accent);
  color: #fff;
}
.ix-chat-time { font-size: var(--ifx-font-size-10); color: var(--ix-text-muted); margin-top: var(--ifx-space-4); }
.ix-chat-footer {
  padding: var(--ifx-inset-widget);
  border-top: 1px solid var(--ix-border);
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
  flex-shrink: 0;
}
.ix-chat-input {
  flex: 1;
  background: var(--ix-bg-input);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius);
  padding: var(--ifx-space-8) 14px;
  font-size: var(--ifx-font-size-14);
  font-family: var(--ix-font);
  color: var(--ix-text-primary);
  outline: none;
}
.ix-chat-input:focus { border-color: var(--ix-accent); }
.ix-chat-profile {
  width: 240px;
  flex-shrink: 0;
  border-left: 1px solid var(--ix-border);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  padding: 20px 16px;
  gap: var(--ifx-space-20);
}

/* -----------------------------------------------------------------
   45. WIZARD / STEPPER
   ----------------------------------------------------------------- */
.ix-wizard-wrap {
  display: flex;
  gap: 0;
  background: var(--ix-bg-card);
  border-radius: var(--ix-radius-lg);
  border: 1px solid var(--ix-border);
  overflow: hidden;
}
.ix-wizard-steps {
  width: 240px;
  flex-shrink: 0;
  border-right: 1px solid var(--ix-border);
  padding: var(--ifx-space-container) 0;
  display: flex;
  flex-direction: column;
}
.ix-wizard-step-item {
  display: flex;
  align-items: flex-start;
  gap: var(--ifx-space-12);
  padding: 14px 20px;
  cursor: pointer;
  position: relative;
}
.ix-wizard-step-item:not(:last-child)::after {
  content: '';
  position: absolute;
  left: 31px; top: 50px;
  width: 2px;
  height: calc(100% - 20px);
  background: var(--ix-border);
}
.ix-wizard-step-item.active::after,
.ix-wizard-step-item.done::after { background: var(--ix-accent); }
.ix-wstep-circle {
  width: 34px; height: 34px;
  border-radius: 50%;
  border: 2px solid var(--ix-border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--ifx-font-size-16);
  color: var(--ix-text-muted);
  background: var(--ix-bg-card);
  flex-shrink: 0;
  z-index: 1;
}
.ix-wizard-step-item.active .ix-wstep-circle {
  border-color: var(--ix-accent);
  color: var(--ix-accent);
  background: rgba(105,108,255,.08);
}
.ix-wizard-step-item.done .ix-wstep-circle {
  border-color: var(--ix-success);
  color: #fff;
  background: var(--ix-success);
}
.ix-wstep-title { font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-semibold); color: var(--ix-text-primary); }
.ix-wstep-sub { font-size: var(--ifx-font-size-10); color: var(--ix-text-muted); }
.ix-wizard-body { flex: 1; padding: 32px; min-width: 0; }
.ix-wizard-panel { display: none; }
.ix-wizard-panel.active { display: block; }
.ix-wizard-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 24px;
}
.ix-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--ifx-space-16);
  margin-bottom: var(--ifx-space-16);
}
.ix-radio-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--ifx-space-12);
  margin-bottom: 20px;
}
.ix-radio-card {
  border: 2px solid var(--ix-border);
  border-radius: var(--ix-radius);
  padding: var(--ifx-space-16) 12px;
  text-align: center;
  cursor: pointer;
  transition: border-color .15s, background .15s;
}
.ix-radio-card:hover,
.ix-radio-card.selected {
  border-color: var(--ix-accent);
  background: rgba(105,108,255,.05);
}
.ix-radio-card-icon { font-size: var(--ifx-font-size-28); color: var(--ix-accent); margin-bottom: 6px; }
.ix-radio-card-title { font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-semibold); color: var(--ix-text-primary); margin-bottom: 2px; }
.ix-radio-card-sub { font-size: var(--ifx-font-size-10); color: var(--ix-text-muted); }

/* -----------------------------------------------------------------
   46. AUTH PAGES
   ----------------------------------------------------------------- */
.ix-auth-root {
  min-height: 100vh;
  background: var(--ix-bg-body);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--ix-font);
}
.ix-auth-card {
  width: 100%;
  max-width: 420px;
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: 36px 40px;
}
.ix-auth-brand {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--ifx-inline-md);
  margin-bottom: var(--ifx-space-24);
}
.ix-auth-brand-name {
  font-size: var(--ifx-font-size-20);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-primary);
}
.ix-auth-title {
  font-size: var(--ifx-font-size-20);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-primary);
  margin-bottom: var(--ifx-space-4);
}
.ix-auth-sub {
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-muted);
  margin-bottom: var(--ifx-space-24);
}
.ix-auth-divider {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-12);
  margin: 20px 0;
  color: var(--ix-text-muted);
  font-size: var(--ifx-font-size-12);
}
.ix-auth-divider::before,
.ix-auth-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--ix-border);
}
.ix-auth-socials {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--ifx-space-8);
}
.ix-social-btn {
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1px solid var(--ix-border);
  display: flex; align-items: center; justify-content: center;
  font-size: var(--ifx-font-size-16);
  cursor: pointer;
  background: none;
  color: var(--ix-text-secondary);
  transition: all .15s;
  text-decoration: none;
}
.ix-social-btn:hover { border-color: var(--ix-accent); color: var(--ix-accent); }
.ix-social-btn.facebook:hover { color: #1877f2; border-color: #1877f2; }
.ix-social-btn.twitter:hover  { color: #1da1f2; border-color: #1da1f2; }
.ix-social-btn.github:hover   { color: #cfd3ec;  border-color: #cfd3ec; }
.ix-social-btn.google:hover   { color: #ea4335; border-color: #ea4335; }
.ix-auth-footer {
  text-align: center;
  margin-top: var(--ifx-space-16);
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-muted);
}
.ix-auth-footer a { color: var(--ix-accent); text-decoration: none; }
.ix-auth-footer a:hover { text-decoration: underline; }
.ix-auth-back {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--ifx-space-4);
  font-size: var(--ifx-font-size-14);
  color: var(--ix-accent);
  text-decoration: none;
  margin-top: var(--ifx-space-16);
}
.ix-auth-back:hover { text-decoration: underline; }
.ix-auth-remember {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 16px 0;
  font-size: var(--ifx-font-size-14);
}
.ix-auth-remember a { color: var(--ix-accent); text-decoration: none; font-size: var(--ifx-font-size-14); }
.ix-auth-check {
  display: flex;
  align-items: center;
  gap: 7px;
  cursor: pointer;
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-secondary);
}
.ix-otp-row {
  display: flex;
  gap: var(--ifx-space-8);
  justify-content: center;
  margin: var(--ifx-space-16) 0;
}
.ix-otp-digit {
  flex: 0 0 2.75rem;
  max-width: 3rem;
  text-align: center;
  padding-left: 0;
  padding-right: 0;
  font-size: var(--ifx-font-size-24);
  font-weight: 600;
  letter-spacing: 0;
}
.ix-input-password-wrap { position: relative; }
.ix-input-password-wrap .ix-input { padding-right: 40px; }
.ix-input-password-toggle {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  cursor: pointer;
  color: var(--ix-text-muted);
  font-size: var(--ifx-font-size-16);
  padding: 0;
  line-height: 1;
}

/* -----------------------------------------------------------------
   47. USER PROFILE (ADM-USR-002 pattern)
   ----------------------------------------------------------------- */
.ix-profile-grid {
  display: flex;
  gap: var(--ifx-space-24);
  align-items: flex-start;
}
.ix-profile-sidebar {
  width: 300px;
  flex-shrink: 0;
}
.ix-profile-hero {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 40px 24px 28px;
  text-align: center;
}
.ix-profile-avatar {
  width: 90px; height: 90px;
  border-radius: 50%;
  border: 3px solid var(--ix-accent);
  object-fit: cover;
  background: var(--ix-accent);
  display: flex; align-items: center; justify-content: center;
  font-size: var(--ifx-font-size-32); font-weight: var(--ifx-font-weight-bold); color: #fff;
  margin-bottom: var(--ifx-space-12);
  overflow: hidden;
}
.ix-profile-name {
  font-size: var(--ifx-font-size-18); font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-primary); margin-bottom: 6px;
}
.ix-profile-stats {
  display: flex; gap: 0;
  border-top: 1px solid var(--ix-border);
  border-bottom: 1px solid var(--ix-border);
  margin: 20px -24px;
  width: calc(100% + 48px);
}
.ix-profile-stat {
  flex: 1;
  padding: 14px 8px;
  text-align: center;
  border-right: 1px solid var(--ix-border);
}
.ix-profile-stat:last-child { border-right: none; }
.ix-profile-stat-value {
  font-size: var(--ifx-font-size-18); font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-primary); line-height: 1.1;
}
.ix-profile-stat-label {
  font-size: var(--ifx-font-size-10); color: var(--ix-text-muted); margin-top: 2px;
}
.ix-detail-list { list-style: none; padding: 0; margin: 0; }
.ix-detail-list li {
  display: flex; align-items: flex-start;
  gap: var(--ifx-space-8); padding: 7px 0;
  border-bottom: 1px solid var(--ix-border);
  font-size: var(--ifx-font-size-14);
}
.ix-detail-list li:last-child { border-bottom: none; }
.ix-detail-label {
  font-weight: var(--ifx-font-weight-semibold); color: var(--ix-text-primary);
  min-width: 90px; flex-shrink: 0;
}
.ix-detail-val { color: var(--ix-text-secondary); }
.ix-plan-card {
  border: 2px solid var(--ix-accent);
  border-radius: var(--ix-radius-lg);
  background: rgba(105,108,255,.04);
}
.ix-plan-price {
  display: flex; align-items: flex-start; gap: 2px;
  color: var(--ix-accent);
}
.ix-plan-price-cur { font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-semibold); margin-top: var(--ifx-space-4); }
.ix-plan-price-num { font-size: 36px; font-weight: 800; line-height: 1; }
.ix-plan-price-per { font-size: var(--ifx-font-size-12); color: var(--ix-text-muted); margin-top: auto; margin-bottom: var(--ifx-space-4); }
.ix-plan-feat {
  font-size: var(--ifx-font-size-14); color: var(--ix-text-secondary);
  display: flex; align-items: center; gap: 7px;
  padding: 5px 0;
}
.ix-ref-box {
  background: linear-gradient(135deg, rgba(105,108,255,.12) 0%, rgba(105,108,255,.04) 100%);
  border: 1px solid rgba(105,108,255,.3);
  border-radius: var(--ix-radius-lg);
  padding: 20px;
}
.ix-ref-row {
  display: flex; gap: var(--ifx-space-8); align-items: center;
  margin-top: var(--ifx-space-8);
}
.ix-ref-input {
  flex: 1; background: var(--ix-bg-input);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius);
  padding: var(--ifx-space-input-y) var(--ifx-space-input-x);
  font-size: var(--ifx-font-size-14); font-family: monospace;
  color: var(--ix-text-primary);
  outline: none;
}
.ix-layer-f0 {
  background: rgba(105,108,255,.15); color: var(--ix-accent);
  padding: 2px 8px; border-radius: 20px; font-size: var(--ifx-font-size-10); font-weight: var(--ifx-font-weight-semibold);
}
.ix-layer-f1 {
  background: rgba(40,199,111,.15); color: var(--ix-success);
  padding: 2px 8px; border-radius: 20px; font-size: var(--ifx-font-size-10); font-weight: var(--ifx-font-weight-semibold);
}
.ix-layer-f2 {
  background: rgba(255,159,67,.15); color: var(--ix-warning);
  padding: 2px 8px; border-radius: 20px; font-size: var(--ifx-font-size-10); font-weight: var(--ifx-font-weight-semibold);
}
.ix-aff-summary {
  display: grid; grid-template-columns: repeat(4,1fr); gap: 0;
  border-bottom: 1px solid var(--ix-border);
}
.ix-aff-sum-item {
  padding: var(--ifx-inset-card);
  border-right: 1px solid var(--ix-border);
}
.ix-aff-sum-item:last-child { border-right: none; }
.ix-aff-sum-val {
  font-size: var(--ifx-font-size-20); font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-primary); line-height: 1.1;
}
.ix-aff-sum-label { font-size: var(--ifx-font-size-12); color: var(--ix-text-muted); margin-top: 2px; }
.ix-aff-sum-accent { color: var(--ix-success); }
.ix-layer-info {
  display: flex; gap: var(--ifx-inline-md); flex-wrap: wrap;
  padding: var(--ifx-space-12) 20px; border-bottom: 1px solid var(--ix-border);
  align-items: center;
}
.ix-layer-pill {
  display: flex; align-items: center; gap: var(--ifx-inline-sm);
  font-size: var(--ifx-font-size-12); color: var(--ix-text-secondary);
  background: var(--ix-bg-hover);
  padding: 4px 10px; border-radius: 20px;
}
.ix-layer-pill strong { color: var(--ix-text-primary); }
.ix-profile-tabs {
  display: flex; gap: var(--ifx-space-4); flex-wrap: wrap;
  margin-bottom: var(--ifx-space-24);
}
.ix-profile-tab {
  display: flex; align-items: center; gap: var(--ifx-inline-sm);
  padding: var(--ifx-space-8) 16px; border-radius: var(--ix-radius);
  font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-medium);
  color: var(--ix-text-secondary);
  cursor: pointer; transition: all .15s;
  text-decoration: none;
  border: none; background: none;
  font-family: var(--ix-font);
}
.ix-profile-tab:hover { background: var(--ix-bg-hover); color: var(--ix-text-primary); }
.ix-profile-tab.active {
  background: var(--ix-accent);
  color: #fff;
}
.ix-tab-content { display: none; }
.ix-tab-content.active { display: block; }
.ix-act-timeline { list-style: none; padding: 0; margin: 0; }
.ix-act-item {
  display: flex; gap: 14px;
  padding: 14px 0;
  border-bottom: 1px solid var(--ix-border);
}
.ix-act-item:last-child { border-bottom: none; }
.ix-act-dot {
  width: 32px; height: 32px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: var(--ifx-font-size-16); flex-shrink: 0; margin-top: 2px;
}
.ix-act-title { font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-semibold); color: var(--ix-text-primary); margin-bottom: 2px; }
.ix-act-desc { font-size: var(--ifx-font-size-12); color: var(--ix-text-muted); }
.ix-act-time { font-size: var(--ifx-font-size-10); color: var(--ix-text-muted); white-space: nowrap; flex-shrink: 0; margin-top: var(--ifx-space-4); }
.ix-modal-overlay[data-profile-modal] {
  display: none;
  position: fixed; inset: 0;
  background: rgba(0,0,0,.55); z-index: 1000;
  align-items: center; justify-content: center;
}
.ix-modal-overlay[data-profile-modal].open { display: flex; }
.ix-modal-box {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: 32px;
  width: 100%; max-width: 520px;
  position: relative;
}
.ix-modal-close {
  position: absolute; top: 16px; right: 16px;
  background: none; border: none; cursor: pointer;
  color: var(--ix-text-muted); font-size: var(--ifx-font-size-20);
}
.ix-modal-sub { font-size: var(--ifx-font-size-14); color: var(--ix-text-muted); margin-bottom: var(--ifx-space-24); }
@media (max-width: 900px) {
  .ix-profile-grid { flex-direction: column; }
  .ix-profile-sidebar { width: 100%; }
  .ix-aff-summary { grid-template-columns: repeat(2,1fr); }
}

/* Hub / checklist */
.ix-menu-item--muted { opacity: 0.55; pointer-events: none; }
.ix-hub-table { width: 100%; border-collapse: collapse; font-size: var(--ifx-font-size-14); }
.ix-hub-table th, .ix-hub-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--ix-border);
  text-align: left;
  vertical-align: top;
}
.ix-hub-table th { color: var(--ix-text-muted); font-weight: var(--ifx-font-weight-semibold); }
.ix-hub-ok { color: var(--ix-success); }
.ix-hub-partial { color: var(--ix-warning); }
.ix-hub-miss { color: var(--ix-danger); }
.ix-hub-gd2 { color: var(--ix-text-muted); }

/* Preview Environment — canvas nhận bề rộng duy nhất từ IfluxViewportRegistry. */
.ix-preview-viewport__canvas {
  width: var(--ifx-preview-viewport-width);
  max-width: none;
  container-type: inline-size;
}

/**
 * iFlux fonts — Be Vietnam Pro (self-host, no Google Fonts)
 * Chỉ 4 weight dùng thật: 200 / 400 / 600 / 800.
 * Đã subset Latin + Latin-Ext + tiếng Việt → woff2 (~30KB/file).
 * Mono/numeric: dùng font hệ thống (khai báo trong typography.css).
 */
@font-face {
  font-family: 'Be Vietnam Pro';
  font-style: normal;
  font-weight: 200;
  font-display: swap;
  src: url('./fonts/BeVietnamPro-200.woff2') format('woff2');
}
@font-face {
  font-family: 'Be Vietnam Pro';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('./fonts/BeVietnamPro-400.woff2') format('woff2');
}
@font-face {
  font-family: 'Be Vietnam Pro';
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url('./fonts/BeVietnamPro-600.woff2') format('woff2');
}
@font-face {
  font-family: 'Be Vietnam Pro';
  font-style: normal;
  font-weight: 800;
  font-display: swap;
  src: url('./fonts/BeVietnamPro-800.woff2') format('woff2');
}

