/**
 * iFlux Foundation — Color Primitives (Layer 1)
 * Raw palette. UI dùng semantic tokens trong semantic/theme.css — KHÔNG dùng trực tiếp trong component.
 */
:root {
  /* Brand — Navy */
  --ifx-color-navy-50:  #eef1fa;
  --ifx-color-navy-100: #d5dcf2;
  --ifx-color-navy-200: #aab8e5;
  --ifx-color-navy-300: #7f94d8;
  --ifx-color-navy-400: #5470cb;
  --ifx-color-navy-500: #3a56b5;
  --ifx-color-navy-600: #1b3587;
  --ifx-color-navy-700: #152a6b;
  --ifx-color-navy-800: #0f1f50;
  --ifx-color-navy-900: #0a1438;

  /* Brand — Orange */
  --ifx-color-orange-50:  #fff4ed;
  --ifx-color-orange-100: #ffe4d1;
  --ifx-color-orange-200: #ffc9a3;
  --ifx-color-orange-300: #ffa96f;
  --ifx-color-orange-400: #ff8840;
  --ifx-color-orange-500: #f26522;
  --ifx-color-orange-600: #d95518;
  --ifx-color-orange-700: #b34412;
  --ifx-color-orange-800: #8c350e;
  --ifx-color-orange-900: #662709;

  /* Feedback */
  --ifx-color-green-400:  #33b894;
  --ifx-color-green-500:  #00a67e;
  --ifx-color-green-600:  #008566;
  --ifx-color-red-400:    #ef5a6f;
  --ifx-color-red-500:    #e8304a;
  --ifx-color-red-600:    #c4243b;
  --ifx-color-amber-400:  #fcd34d;
  --ifx-color-amber-500:  #fbbf24;
  --ifx-color-amber-600:  #d97706;
  --ifx-color-cyan-400:   #38d9f5;
  --ifx-color-cyan-500:   #03c3ec;
  --ifx-color-cyan-600:   #0299b8;

  /* Market — trần / sàn (VN) */
  --ifx-color-purple-500: #a855f7;
  --ifx-alpha-purple-10:  rgba(168, 85, 247, 0.10);

  /* Neutral — UI slate (dark surfaces) */
  --ifx-color-slate-50:  #f5f5f9;
  --ifx-color-slate-100: #ececf1;
  --ifx-color-slate-200: #cfd3ec;
  --ifx-color-slate-300: #a1acb8;
  --ifx-color-slate-400: #8592a3;
  --ifx-color-slate-500: #697a8d;
  --ifx-color-slate-600: #5f6582;
  --ifx-color-slate-700: #3a3b55;
  --ifx-color-slate-800: #2b2c40;
  --ifx-color-slate-850: #232333;
  --ifx-color-slate-900: #1e1e2d;
  --ifx-color-slate-950: #16161f;

  /* Chart palette — series Top 10 / compare (10 màu, token only) */
  --ifx-color-chart-1:  var(--ifx-color-violet-500);
  --ifx-color-chart-2:  var(--ifx-color-lime-500);
  --ifx-color-chart-3:  var(--ifx-color-amber-550);
  --ifx-color-chart-4:  var(--ifx-color-red-450);
  --ifx-color-chart-5:  var(--ifx-color-cyan-500);
  --ifx-color-chart-6:  var(--ifx-color-orange-500);
  --ifx-color-chart-7:  var(--ifx-color-violet-400);
  --ifx-color-chart-8:  var(--ifx-color-green-500);
  --ifx-color-chart-9:  #e91e8c;
  --ifx-color-chart-10: #b4b7bd;

  /* Alpha helpers */
  --ifx-alpha-white-4:  rgba(255, 255, 255, 0.04);
  --ifx-alpha-white-8:  rgba(255, 255, 255, 0.08);
  --ifx-alpha-white-12: rgba(255, 255, 255, 0.12);
  --ifx-alpha-white-16: rgba(255, 255, 255, 0.16);
  --ifx-alpha-white-20: rgba(207, 211, 236, 0.2);
  --ifx-alpha-black-4:  rgba(0, 0, 0, 0.04);
