  --ifx-alpha-black-12: rgba(0, 0, 0, 0.12);
  --ifx-alpha-black-16: rgba(0, 0, 0, 0.16);
  --ifx-alpha-black-45: rgba(0, 0, 0, 0.45);
  --ifx-alpha-black-60: rgba(0, 0, 0, 0.60);

  /* UI accent — violet (dark shell) */
  --ifx-color-violet-500: #696cff;
  --ifx-color-violet-600: #5f61e6;
  --ifx-color-violet-400: #8592ff;
  --ifx-alpha-violet-16: rgba(105, 108, 255, 0.16);

  /* Feedback — dark shell highlights */
  --ifx-color-lime-500: #71dd37;
  --ifx-alpha-lime-16: rgba(113, 221, 55, 0.16);
  --ifx-color-amber-550: #ffab00;
