  --ifx-alpha-cyan-16: rgba(3, 195, 236, 0.16);

  /* Chrome — dark shell */
  --ifx-color-white: #ffffff;
  --ifx-color-border-frost: rgba(207, 211, 236, 0.12);
  --ifx-color-topnav-bg: rgba(43, 44, 64, 0.94);
  --ifx-shadow-topnav: 0 4px 24px rgba(0, 0, 0, 0.18);
  --ifx-alpha-orange-35: rgba(242, 101, 34, 0.35);
  --ifx-alpha-orange-14: rgba(242, 101, 34, 0.14);
  --ifx-alpha-orange-8:  rgba(242, 101, 34, 0.08);
  --ifx-alpha-orange-45: rgba(242, 101, 34, 0.45);
  --ifx-alpha-red-35:    rgba(255, 76, 81, 0.35);
  --ifx-alpha-red-12:    rgba(255, 76, 81, 0.12);

  /* Flow / MCMP tints (giữ đúng màu iFlux legacy) */
  --ifx-alpha-green-500-50: rgba(0, 166, 126, 0.50);
  --ifx-alpha-green-500-45: rgba(0, 166, 126, 0.45);
  --ifx-alpha-green-500-25: rgba(0, 166, 126, 0.25);
  --ifx-alpha-green-500-22: rgba(0, 166, 126, 0.22);
  --ifx-alpha-green-500-12: rgba(0, 166, 126, 0.12);
  --ifx-alpha-red-500-45:   rgba(232, 48, 74, 0.45);
  --ifx-alpha-red-500-25:   rgba(232, 48, 74, 0.25);
  --ifx-alpha-red-500-22:   rgba(232, 48, 74, 0.22);
  --ifx-alpha-red-500-12:   rgba(232, 48, 74, 0.12);
  --ifx-alpha-red-500-10:   rgba(232, 48, 74, 0.10);
  --ifx-alpha-violet-500-4:  rgba(105, 108, 255, 0.04);
  --ifx-alpha-violet-500-6:  rgba(105, 108, 255, 0.06);
  --ifx-alpha-violet-500-3:  rgba(105, 108, 255, 0.03);
  --ifx-alpha-violet-500-12: rgba(105, 108, 255, 0.12);
  --ifx-alpha-amber-550-12:  rgba(255, 171, 0, 0.12);
  --ifx-alpha-muted-12:      rgba(133, 146, 163, 0.12);
  --ifx-alpha-shell-55:      rgba(15, 17, 28, 0.55);
  --ifx-gradient-zone-track: linear-gradient(90deg, var(--ifx-alpha-green-500-25) 0%, var(--ifx-alpha-violet-500-12) 50%, var(--ifx-alpha-red-500-25) 100%);
  --ifx-gradient-zone-fill:  linear-gradient(90deg, var(--ifx-alpha-green-500-45), var(--ifx-alpha-violet-500-12));
  --ifx-gradient-mcmp-energy: linear-gradient(180deg, var(--ifx-color-amber-550), var(--ifx-color-red-500));
  --ifx-gradient-brand-cta: linear-gradient(135deg, var(--ifx-color-orange-500) 0%, var(--ifx-color-red-500) 100%);
}

/**
 * iFlux Foundation — Layout dimensions + breakpoints
 */
:root {
  /* Breakpoints (reference — use in @media) */
  --ifx-bp-xs: 375px;
  --ifx-bp-sm: 640px;
  --ifx-bp-md: 768px;
  --ifx-bp-lg: 1024px;
  --ifx-bp-xl: 1280px;
  --ifx-bp-2xl: 1440px;
  --ifx-bp-3xl: 1600px;

  /* Touch / icon */
  --ifx-size-touch-target: 44px;
  --ifx-size-icon-sm: 16px;
  --ifx-size-icon-md: 20px;
  --ifx-size-icon-lg: 24px;

  /* Avatar */
  --ifx-size-avatar-sm: 28px;
  --ifx-size-avatar-md: 36px;
  --ifx-size-avatar-lg: 48px;

  /* Admin shell */
  --ifx-size-sidebar-w: 260px;
  --ifx-size-sidebar-w-collapsed: 72px;
  --ifx-size-navbar-h: 64px;

  /* User Web shell */
  --ifx-size-topnav-h: 56px;
  --ifx-size-tabbar-h: 60px;
  --ifx-size-nav-drawer-w: 300px;
  --ifx-size-container-max: 1280px;
}

/**
 * iFlux Foundation — Motion / Transition
 */
:root {
  --ifx-duration-instant: 0ms;
  --ifx-duration-fast: 100ms;
  --ifx-duration-normal: 200ms;
  --ifx-duration-slow: 300ms;
  --ifx-duration-slower: 400ms;

  --ifx-ease-default: cubic-bezier(0.4, 0, 0.2, 1);
  --ifx-ease-in: cubic-bezier(0.4, 0, 1, 1);
  --ifx-ease-out: cubic-bezier(0, 0, 0.2, 1);
  --ifx-ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);

  --transition-color: color var(--ifx-duration-fast) var(--ifx-ease-default),
    background-color var(--ifx-duration-fast) var(--ifx-ease-default),
    border-color var(--ifx-duration-fast) var(--ifx-ease-default);
  --transition-transform: transform var(--ifx-duration-normal) var(--ifx-ease-out);
  --transition-opacity: opacity var(--ifx-duration-normal) var(--ifx-ease-default);
  --transition-drawer: transform var(--ifx-duration-slow) var(--ifx-ease-out);
}

/**
 * iFlux Foundation — Radius Primitives + Semantic
 */
:root {
  --ifx-radius-none: 0;
  --ifx-radius-xs: 2px;
  --ifx-radius-sm: 4px;
  --ifx-radius-md: 6px;
  --ifx-radius-lg: 8px;
  --ifx-radius-xl: 12px;
  --ifx-radius-2xl: 16px;
  --ifx-radius-full: 9999px;

  --radius-button: var(--ifx-radius-md);
  --radius-input: var(--ifx-radius-md);
  --radius-card: var(--ifx-radius-lg);
  --radius-badge: var(--ifx-radius-full);
  --radius-chip: var(--ifx-radius-full);
  --radius-modal: var(--ifx-radius-lg);
  --radius-dropdown: var(--ifx-radius-lg);
}

/**
 * iFlux Foundation — Shadow Primitives + Semantic
 */
:root {
  --ifx-shadow-xs: 0 1px 2px var(--ifx-alpha-black-8);
  --ifx-shadow-sm: 0 2px 6px var(--ifx-alpha-black-8);
  --ifx-shadow-md: 0 4px 16px var(--ifx-alpha-black-12);
  --ifx-shadow-lg: 0 8px 24px var(--ifx-alpha-black-16);
  --ifx-shadow-xl: 0 12px 32px var(--ifx-alpha-black-16);

  --shadow-card: var(--ifx-shadow-sm);
  --shadow-dropdown: var(--ifx-shadow-lg);
  --shadow-modal: var(--ifx-shadow-xl);
  --shadow-topnav: var(--ifx-shadow-md);
}

/**
 * iFlux Foundation — Z-index scale
 */
:root {
  --ifx-z-base: 0;
  --ifx-z-raised: 1;
  --ifx-z-dropdown: 100;
  --ifx-z-sticky: 200;
  --ifx-z-topnav: 220;
  --ifx-z-drawer: 230;
  --ifx-z-overlay: 240;
  --ifx-z-modal: 300;
  --ifx-z-toast: 400;
  --ifx-z-onboarding: 500;
}

/**
 * iFlux Foundation — Legacy aliases (Layer 2 → --ix-* / --iflux-*)
 * Giữ tương thích trong khi migrate domain CSS. Không thêm hex mới ở đây.
 */
:root {
  /* Brand shorthand */
  --iflux-navy: var(--ifx-color-navy-600);
  --iflux-navy-hover: var(--ifx-color-navy-700);
  --iflux-orange: var(--ifx-color-orange-500);
  --iflux-success: var(--ifx-color-green-500);
  --iflux-danger: var(--ifx-color-red-500);
  --iflux-warning: var(--ifx-color-amber-500);

  /* Vuexy-compat semantic (--ix-*) */
  --ix-bg-body: var(--color-bg-canvas);
  --ix-bg-card: var(--color-bg-surface);
  --ix-bg-sidebar: var(--color-bg-sidebar);
  --ix-bg-navbar: var(--color-bg-navbar);
  --ix-bg-hover: var(--color-bg-hover);
  --ix-bg-active: var(--color-bg-active);
  --ix-bg-input: var(--color-bg-input);

  --ix-accent: var(--color-action-primary);
  --ix-accent-hover: var(--color-action-primary-hover);
  --ix-accent-soft: var(--color-action-primary-soft);

  --ix-success: var(--color-success);
  --ix-success-soft: var(--color-success-soft);
  --ix-warning: var(--color-warning);
  --ix-warning-soft: var(--color-warning-soft);
  --ix-danger: var(--color-danger);
  --ix-danger-soft: var(--color-danger-soft);
  --ix-info: var(--color-info);
  --ix-info-soft: var(--color-info-soft);

  --ix-text-primary: var(--color-text-primary);
  --ix-text-secondary: var(--color-text-secondary);
  --ix-text-card-title: var(--color-text-card-title);
  --ix-text-muted: var(--color-text-muted);

  --ix-border: var(--color-border-default);

  /* Layout */
  --ix-sidebar-w: var(--ifx-size-sidebar-w);
  --ix-sidebar-w-collapsed: var(--ifx-size-sidebar-w-collapsed);
  --ix-navbar-h: var(--ifx-size-navbar-h);

  /* Radius */
  --ix-radius: var(--radius-button);
  --ix-radius-lg: var(--radius-card);

  /* User Web chrome */
  --ifx-topnav-bg: var(--color-topnav-bg);
  --ifx-topnav-shadow: var(--color-topnav-shadow);
  --ifx-surface-elevated: var(--color-surface-elevated);
  --ifx-overlay-scrim: var(--color-scrim);
  --ifx-nav-drawer-w: var(--ifx-size-nav-drawer-w);
  --ifx-topnav-h: var(--ifx-size-topnav-h);
  --ifx-tabbar-h: var(--ifx-size-tabbar-h);

  /* Market semantic shortcuts */
  --ifx-market-up: var(--color-market-up);
  --ifx-market-down: var(--color-market-down);
  --ifx-market-up-soft: var(--color-market-up-soft);
  --ifx-market-down-soft: var(--color-market-down-soft);
  --ifx-market-ref: var(--color-market-ref);
  --ifx-market-ref-soft: var(--color-market-ref-soft);
  --ifx-market-ceiling: var(--color-market-ceiling);
  --ifx-market-ceiling-soft: var(--color-market-ceiling-soft);
  --ifx-market-floor: var(--color-market-floor);
  --ifx-market-floor-soft: var(--color-market-floor-soft);
  --ifx-flow-in: var(--color-flow-in);
  --ifx-flow-out: var(--color-flow-out);

  /* Chart runtime (ApexCharts / SVG) */
  --ifx-chart-grid: var(--ifx-color-border-frost);
  --ifx-chart-label: var(--ix-text-secondary);
  --ifx-chart-text: var(--ix-text-muted);
  --ifx-chart-annotation-bg: var(--ix-accent-soft);
  --ifx-chart-marker-stroke: var(--color-text-on-primary);
}

/**
 * iFlux — Business Design Tokens (Layer 2b)
 * Domain semantics: market, signal, portfolio, heatmap.
 * Tham chiếu Semantic (--color-*) để theme dark/light đổi đồng bộ.
 */
:root,
[data-theme="dark"] {
  --biz-money-flow-strong-in: var(--color-flow-in);
  --biz-money-flow-strong-out: var(--color-flow-out);

  --biz-signal-confirmed: var(--color-success);
  --biz-signal-pending: var(--color-warning);
  --biz-signal-invalid: var(--color-danger);

  --biz-portfolio-profit: var(--color-market-up);
  --biz-portfolio-loss: var(--color-market-down);

  --biz-heatmap-1: var(--ifx-color-chart-1);
  --biz-heatmap-2: var(--ifx-color-chart-2);
  --biz-heatmap-3: var(--ifx-color-chart-3);
  --biz-heatmap-4: var(--ifx-color-chart-4);
  --biz-heatmap-5: var(--ifx-color-chart-5);
  --biz-heatmap-6: var(--ifx-color-chart-6);
  --biz-heatmap-7: var(--ifx-color-chart-7);
  --biz-heatmap-8: var(--ifx-color-chart-8);
  --biz-heatmap-9: var(--ifx-color-chart-9);
  --biz-heatmap-10: var(--ifx-color-chart-10);
}

[data-theme="light"] {
  --biz-money-flow-strong-in: var(--color-flow-in);
  --biz-money-flow-strong-out: var(--color-flow-out);

  --biz-signal-confirmed: var(--color-success);
  --biz-signal-pending: var(--color-warning);
  --biz-signal-invalid: var(--color-danger);

  --biz-portfolio-profit: var(--color-market-up);
  --biz-portfolio-loss: var(--color-market-down);
}

/**
 * iFlux Foundation — Semantic Color (Layer 2)
 * Dark = admin shell palette (giá trị gốc đã chuẩn hóa trong primitives/color.css).
 * Light = iFlux navy brand.
 */
:root,
[data-theme="dark"] {
  color-scheme: dark;

  /* Surface */
  --color-bg-canvas: var(--ifx-color-slate-850);
  --color-bg-surface: var(--ifx-color-slate-800);
  --color-bg-elevated: var(--ifx-color-slate-700);
  --color-bg-subtle: var(--ifx-color-slate-900);
  --color-bg-input: var(--ifx-color-slate-900);
  --color-bg-hover: var(--ifx-color-slate-700);
  --color-bg-active: var(--ifx-alpha-violet-16);
  --color-bg-sidebar: var(--ifx-color-slate-800);
  --color-bg-navbar: var(--ifx-color-slate-800);

  /* Text */
  --color-text-primary: var(--ifx-color-slate-200);
  --color-text-secondary: var(--ifx-color-slate-400);
  --color-text-muted: var(--ifx-color-slate-600);
  --color-text-disabled: var(--ifx-color-slate-500);
  --color-text-inverse: var(--ifx-color-slate-850);
  --color-text-card-title: var(--ifx-color-text-card-title);
  --color-text-link: var(--ifx-color-violet-500);

  /* Border */
  --color-border-default: var(--ifx-color-border-frost);
  --color-border-strong: rgba(207, 211, 236, 0.2);
  --color-border-subtle: rgba(207, 211, 236, 0.08);
  --color-border-focus: var(--ifx-color-violet-500);

  /* Action */
  --color-action-primary: var(--ifx-color-violet-500);
  --color-action-primary-hover: var(--ifx-color-violet-600);
  --color-action-primary-soft: var(--ifx-alpha-violet-16);
  --color-action-secondary: var(--ifx-color-orange-500);
  --color-action-secondary-hover: var(--ifx-color-orange-600);
  --color-action-secondary-soft: rgba(242, 101, 34, 0.14);

  /* Feedback */
  --color-success: var(--ifx-color-lime-500);
  --color-success-soft: var(--ifx-alpha-lime-16);
  --color-warning: var(--ifx-color-amber-550);
  --color-warning-soft: var(--ifx-alpha-amber-16);
  --color-danger: var(--ifx-color-red-450);
  --color-danger-soft: var(--ifx-alpha-red-16);
  --color-info: var(--ifx-color-cyan-500);
  --color-info-soft: var(--ifx-alpha-cyan-16);

  /* Overlay / chrome */
  --color-scrim: var(--ifx-color-scrim);
  --color-topnav-bg: var(--ifx-color-topnav-bg);
  --color-topnav-shadow: var(--ifx-shadow-topnav);
  --color-surface-elevated: var(--ifx-alpha-white-4);

  /* Market */
  --color-market-up: var(--ifx-color-lime-500);
  --color-market-up-soft: var(--ifx-alpha-lime-16);
  --color-market-down: var(--ifx-color-red-450);
  --color-market-down-soft: var(--ifx-alpha-red-16);
  --color-market-ref: var(--ifx-color-amber-550);
  --color-market-ref-soft: var(--ifx-alpha-amber-16);
  --color-market-ceiling: var(--ifx-color-purple-500);
  --color-market-ceiling-soft: var(--ifx-alpha-purple-10);
  --color-market-floor: var(--ifx-color-cyan-500);
  --color-market-floor-soft: var(--ifx-alpha-cyan-16);
  --color-flow-in: var(--ifx-color-lime-500);
  --color-flow-out: var(--ifx-color-red-450);

  /* Membership tiers */
  --color-tier-free: var(--ifx-color-slate-400);
  --color-tier-premium: var(--ifx-color-violet-500);
  --color-tier-elite: var(--ifx-color-orange-500);

  /* Text on filled surfaces */
  --color-text-on-primary: #ffffff;
  --color-text-on-success: #151d15;
  --color-text-on-warning: #1a1100;
  --color-text-on-danger: #ffffff;
  --color-text-on-info: #00151a;
}

[data-theme="light"] {
  color-scheme: light;

  --color-bg-canvas: var(--ifx-color-slate-50);
  --color-bg-surface: #ffffff;
  --color-bg-elevated: var(--ifx-color-slate-100);
  --color-bg-subtle: var(--ifx-color-slate-100);
  --color-bg-input: #ffffff;
  --color-bg-hover: var(--ifx-color-slate-100);
