  --color-text-primary: var(--ifx-color-slate-700);
  --color-text-secondary: var(--ifx-color-slate-500);
  --color-text-muted: var(--ifx-color-slate-300);
  --color-text-disabled: var(--ifx-color-slate-300);
  --color-text-inverse: #ffffff;
  --color-text-card-title: #2f3349;
