  --color-border-default: rgba(67, 89, 113, 0.14);
  --color-border-strong: rgba(67, 89, 113, 0.22);
  --color-border-subtle: rgba(67, 89, 113, 0.08);
  --color-border-focus: var(--ifx-color-navy-500);

  --color-action-primary: var(--ifx-color-navy-600);
  --color-action-primary-hover: var(--ifx-color-navy-700);
  --color-action-primary-soft: rgba(27, 53, 135, 0.1);
  --color-action-secondary: var(--ifx-color-orange-500);
  --color-action-secondary-hover: var(--ifx-color-orange-600);
  --color-action-secondary-soft: rgba(242, 101, 34, 0.12);

  --color-success: var(--ifx-color-green-500);
  --color-success-soft: rgba(0, 166, 126, 0.12);
  --color-warning: var(--ifx-color-amber-500);
  --color-warning-soft: rgba(251, 191, 36, 0.14);
  --color-danger: var(--ifx-color-red-500);
  --color-danger-soft: rgba(232, 48, 74, 0.1);
  --color-info: var(--ifx-color-cyan-500);
  --color-info-soft: rgba(3, 195, 236, 0.12);

  --color-scrim: rgba(58, 59, 85, 0.45);
  --color-topnav-bg: rgba(255, 255, 255, 0.94);
  --color-topnav-shadow: 0 4px 24px rgba(67, 89, 113, 0.08);
  --color-surface-elevated: rgba(67, 89, 113, 0.04);

  --color-market-up: var(--ifx-color-green-500);
  --color-market-up-soft: rgba(0, 166, 126, 0.12);
  --color-market-down: var(--ifx-color-red-500);
  --color-market-down-soft: rgba(232, 48, 74, 0.1);
  --color-market-ref: var(--ifx-color-amber-600);
  --color-market-ref-soft: rgba(251, 191, 36, 0.14);
  --color-market-ceiling: var(--ifx-color-purple-500);
  --color-market-ceiling-soft: var(--ifx-alpha-purple-10);
  --color-market-floor: var(--ifx-color-cyan-500);
  --color-market-floor-soft: var(--ifx-alpha-cyan-16);
  --color-flow-in: var(--ifx-color-green-500);
  --color-flow-out: var(--ifx-color-red-500);

  --color-tier-free: var(--ifx-color-slate-500);
