  --color-tier-elite: var(--ifx-color-orange-500);

  --color-text-on-primary: #ffffff;
  --color-text-on-success: #151d15;
  --color-text-on-warning: #1a1100;
  --color-text-on-danger: #ffffff;
  --color-text-on-info: #00151a;
}

.ifx-theme-toggle.is-active { color: var(--color-action-primary); }

/**
 * iFlux Spacing Foundation
 * Base 4px · 8pt grid · Foundation → Layout → Component
 * Dùng var(--ifx-space-*) hoặc class .ifx-space-* / .ix-space-*
 */
:root {
  /* ── 1. Base Unit ─────────────────────────────────────────── */
  --ifx-space-unit: 4px;

  /* ── 2. Spacing Scale ─────────────────────────────────────── */
  --ifx-space-0: 0;
  --ifx-space-2: 0.125rem;   /* 2px */
  --ifx-space-4: 0.25rem;    /* 4px */
  --ifx-space-8: 0.5rem;     /* 8px */
  --ifx-space-12: 0.75rem;   /* 12px */
  --ifx-space-16: 1rem;      /* 16px */
  --ifx-space-20: 1.25rem;   /* 20px */
  --ifx-space-24: 1.5rem;    /* 24px */
  --ifx-space-32: 2rem;      /* 32px */
  --ifx-space-40: 2.5rem;    /* 40px */
  --ifx-space-48: 3rem;      /* 48px */
  --ifx-space-56: 3.5rem;    /* 56px */
  --ifx-space-64: 4rem;      /* 64px */
  --ifx-space-80: 5rem;      /* 80px */
  --ifx-space-96: 6rem;      /* 96px */
  --ifx-space-128: 8rem;     /* 128px */
  --ifx-space-160: 10rem;    /* 160px */
  --ifx-space-192: 12rem;    /* 192px */
  --ifx-space-256: 16rem;    /* 256px */

  /* ── 3–5. Padding / Margin / Gap (semantic sizes) ───────── */
  --ifx-padding-xs: var(--ifx-space-8);
  --ifx-padding-sm: var(--ifx-space-12);
  --ifx-padding-md: var(--ifx-space-16);
