  /* ── 6. Inset ─────────────────────────────────────────────── */
  --ifx-inset-card: var(--ifx-space-16) var(--ifx-space-20);
  --ifx-inset-card-header: var(--ifx-space-16) var(--ifx-space-20) 0;
  --ifx-inset-card-body: var(--ifx-space-16) var(--ifx-space-20) var(--ifx-space-20);
