  --ifx-inset-widget: var(--ifx-space-12) var(--ifx-space-16);
  --ifx-inset-panel: var(--ifx-space-20) var(--ifx-space-24);
  --ifx-inset-dialog: var(--ifx-space-24);
  --ifx-inset-sheet: var(--ifx-space-16) var(--ifx-space-20);

  /* ── 7. Layout Spacing ────────────────────────────────────── */
  --ifx-space-container: var(--ifx-space-24);
