  /* ── 8. Component Spacing ─────────────────────────────────── */
  --ifx-space-button-y: var(--ifx-space-8);
  --ifx-space-button-x: var(--ifx-space-16);
  --ifx-space-button-sm-y: var(--ifx-space-4);
  --ifx-space-button-sm-x: var(--ifx-space-12);
