  /* ── 9. Stack Spacing ─────────────────────────────────────── */
  --ifx-stack-xs: var(--ifx-space-8);
  --ifx-stack-sm: var(--ifx-space-12);
  --ifx-stack-md: var(--ifx-space-16);
  --ifx-stack-lg: var(--ifx-space-24);
  --ifx-stack-xl: var(--ifx-space-32);

  /* ── 10. Inline Spacing ─────────────────────────────────────── */
  --ifx-inline-xs: var(--ifx-space-4);
  --ifx-inline-sm: var(--ifx-space-8);
  --ifx-inline-md: var(--ifx-space-12);
  --ifx-inline-lg: var(--ifx-space-16);
  --ifx-inline-xl: var(--ifx-space-24);

  /* ── 11. Grid & Layout ────────────────────────────────────── */
  --ifx-grid-gutter: var(--ifx-space-24);
  --ifx-grid-col-gap: var(--ifx-space-16);
  --ifx-grid-row-gap: var(--ifx-space-24);
