  /* ── 13. Semantic aliases (component-facing) ──────────────── */
  --ifx-space-card: var(--ifx-inset-card);
  --ifx-space-widget: var(--ifx-inset-widget);
  --ifx-space-inline-xs: var(--ifx-inline-xs);
  --ifx-space-inline-sm: var(--ifx-inline-sm);
  --ifx-space-inline-md: var(--ifx-inline-md);
  --ifx-space-stack-xs: var(--ifx-stack-xs);
  --ifx-space-stack-sm: var(--ifx-stack-sm);
  --ifx-space-stack-md: var(--ifx-stack-md);
  --ifx-space-stack-lg: var(--ifx-stack-lg);
  --ifx-space-stack-xl: var(--ifx-stack-xl);
}

