/**
 * iFlux Typography Foundation
 * Primitive tokens + semantic styles + responsive rules.
 * Dùng var(--ifx-*) hoặc class .ifx-typo-* / .ix-typo-*
 */
:root {
  /* ── 1. Font Family ───────────────────────────────────────── */
  /* Be Vietnam Pro self-host (fonts.css). Không còn Inter/JetBrains (Google). */
  --ifx-font-primary: 'Be Vietnam Pro', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --ifx-font-mono: ui-monospace, 'SF Mono', 'Menlo', 'Consolas', monospace;
  --ifx-font-emoji: 'Apple Color Emoji', 'Segoe UI Emoji', 'Noto Color Emoji';
  --ifx-font-system: system-ui, sans-serif;
  --ifx-font-numeric: var(--ifx-font-primary);

  /* Legacy alias */
  --ix-font: var(--ifx-font-primary);
  --ix-font-mono: var(--ifx-font-mono);

  /* ── 2. Font Weight ───────────────────────────────────────────
   * Hệ thống chỉ nạp 4 weight thật: 200 / 400 / 600 / 800.
   * Các tên cũ (thin/light/medium/bold/black = 100/300/500/700/900)
   * được gộp về weight gần nhất để không faux-bold & không vỡ tham chiếu.
   */
  --ifx-font-weight-extralight: 200;
  --ifx-font-weight-regular: 400;
  --ifx-font-weight-semibold: 600;
  --ifx-font-weight-extrabold: 800;

  /* Alias gộp → 4 weight thật (không sinh thêm request font) */
  --ifx-font-weight-thin: 200;     /* 100 → 200 */
  --ifx-font-weight-light: 400;    /* 300 → 400 */
  --ifx-font-weight-medium: 600;   /* 500 → 600 */
  --ifx-font-weight-bold: 800;     /* 700 → 800 */
  --ifx-font-weight-black: 800;    /* 900 → 800 */

  /* ── 3. Font Size Scale (static — gần bản gốc 12/14/16, body +1px) ──
   * SoT duy nhất cho cỡ chữ. KHÔNG hardcode px ở component.
   * Gốc: caption 12 · widget/body 14 · title 16 · heading 18+
   * Body đọc: 15px (+1 so với gốc). Token 12/14 giữ đúng px cũ.
   */
  --ifx-font-size-2xs: 0.625rem;   /* 10px */
  --ifx-font-size-xs:  0.75rem;    /* 12px */
  --ifx-font-size-sm:  0.8125rem;  /* 13px */
  --ifx-font-size-md:  0.9375rem;  /* 15px — body, lớn hơn gốc một chút */
  --ifx-font-size-lg:  1rem;       /* 16px */
  --ifx-font-size-xl:  1.125rem;   /* 18px */
  --ifx-font-size-2xl: 1.25rem;    /* 20px */
  --ifx-font-size-3xl: 1.5rem;     /* 24px */
  --ifx-font-size-4xl: 1.875rem;   /* 30px */
  --ifx-font-size-5xl: 2.25rem;    /* 36px */

  /* Alias không prefix — cùng SoT */
  --font-size-2xs: var(--ifx-font-size-2xs);
  --font-size-xs:  var(--ifx-font-size-xs);
  --font-size-sm:  var(--ifx-font-size-sm);
  --font-size-md:  var(--ifx-font-size-md);
  --font-size-lg:  var(--ifx-font-size-lg);
  --font-size-xl:  var(--ifx-font-size-xl);
  --font-size-2xl: var(--ifx-font-size-2xl);
  --font-size-3xl: var(--ifx-font-size-3xl);
  --font-size-4xl: var(--ifx-font-size-4xl);
  --font-size-5xl: var(--ifx-font-size-5xl);

  /* Legacy numeric tokens — map ĐÚNG px cũ (không upscale lên md/lg) */
  --ifx-font-size-10: var(--ifx-font-size-2xs);
  --ifx-font-size-12: var(--ifx-font-size-xs);
  --ifx-font-size-14: 0.875rem;   /* 14px — widget title, table cell */
  --ifx-font-size-16: var(--ifx-font-size-lg);
  --ifx-font-size-18: var(--ifx-font-size-xl);
  --ifx-font-size-20: 1.25rem;     /* 20px */
  --ifx-font-size-24: var(--ifx-font-size-2xl);
  --ifx-font-size-28: 1.75rem;    /* 28px */
  --ifx-font-size-32: var(--ifx-font-size-3xl);
  --ifx-font-size-40: 2.5rem;     /* 40px */
  --ifx-font-size-48: var(--ifx-font-size-4xl);
  --ifx-font-size-56: 3.5rem;     /* 56px */
  --ifx-font-size-64: var(--ifx-font-size-5xl);
  --ifx-font-size-72: 4.5rem;     /* 72px */

  /* Legacy size aliases */
  --ix-font-size-base: var(--ifx-font-size-14);
  --ix-font-size-card-title: var(--ifx-font-size-16);

  /* ── 4. Line Height (paired + named) ─────────────────────── */
  --ifx-line-height-10: 0.875rem;  /* 14px */
  --ifx-line-height-12: 1rem;      /* 16px */
  --ifx-line-height-14: 1.25rem;   /* 20px */
  --ifx-line-height-16: 1.5rem;    /* 24px */
  --ifx-line-height-18: 1.75rem;   /* 28px */
  --ifx-line-height-20: 1.875rem;  /* 30px */
  --ifx-line-height-24: 2.25rem;   /* 36px */
  --ifx-line-height-28: 2.625rem;  /* 42px */
  --ifx-line-height-32: 2.75rem;   /* 44px */
  --ifx-line-height-40: 3.25rem;   /* 52px */
  --ifx-line-height-48: 3.5rem;    /* 56px */
  --ifx-line-height-56: 4rem;      /* 64px */
  --ifx-line-height-64: 4.5rem;    /* 72px */
  --ifx-line-height-72: 5rem;      /* 80px */

  --ifx-line-height-tight: 1.25;
  --ifx-line-height-normal: 1.5;
  --ifx-line-height-relaxed: 1.625;
  --ifx-line-height-loose: 1.75;

  /* ── 5. Letter Spacing ────────────────────────────────────── */
  --ifx-letter-spacing-tighter: -0.02em;
  --ifx-letter-spacing-tight: -0.01em;
  --ifx-letter-spacing-normal: 0;
  --ifx-letter-spacing-wide: 0.01em;
  --ifx-letter-spacing-wider: 0.02em;
  --ifx-letter-spacing-caps: 0.06em;

  /* ── 7. Paragraph ─────────────────────────────────────────── */
  --ifx-paragraph-spacing: 1em;
  --ifx-paragraph-indent: 1.5em;

  /* ── 9. Semantic Typography (mobile-first) ────────────────── */
  /* Display */
  /* Display — dùng 4xl/5xl fluid; line-height unitless để theo scale */
  --ifx-text-display-xl-size: var(--ifx-font-size-5xl);
  --ifx-text-display-xl-weight: var(--ifx-font-weight-bold);
  --ifx-text-display-xl-line: var(--ifx-line-height-tight);
  --ifx-text-display-xl-tracking: var(--ifx-letter-spacing-tight);

  --ifx-text-display-l-size: var(--ifx-font-size-4xl);
  --ifx-text-display-l-weight: var(--ifx-font-weight-bold);
  --ifx-text-display-l-line: var(--ifx-line-height-tight);
  --ifx-text-display-l-tracking: var(--ifx-letter-spacing-tight);

  --ifx-text-display-m-size: var(--ifx-font-size-3xl);
  --ifx-text-display-m-weight: var(--ifx-font-weight-bold);
  --ifx-text-display-m-line: var(--ifx-line-height-tight);
  --ifx-text-display-m-tracking: var(--ifx-letter-spacing-normal);

  --ifx-text-display-s-size: var(--ifx-font-size-2xl);
  --ifx-text-display-s-weight: var(--ifx-font-weight-bold);
  --ifx-text-display-s-line: var(--ifx-line-height-tight);
  --ifx-text-display-s-tracking: var(--ifx-letter-spacing-normal);

