.ifx-typo-index, .ix-typo-index { font-family: var(--ifx-font-numeric); font-size: var(--ifx-text-index-size); font-weight: var(--ifx-text-index-weight); font-variant-numeric: tabular-nums; }
.ifx-typo-change, .ix-typo-change { font-family: var(--ifx-font-numeric); font-size: var(--ifx-text-change-size); font-weight: var(--ifx-text-change-weight); font-variant-numeric: tabular-nums; }
.ifx-typo-timestamp, .ix-typo-timestamp { font-family: var(--ifx-font-primary); font-size: var(--ifx-text-timestamp-size); font-weight: var(--ifx-text-timestamp-weight); color: var(--ix-text-muted); }

/* Table */
.ifx-typo-table-header, .ix-typo-table-header, .ix-table th {
  font-family: var(--ifx-font-primary);
  font-size: var(--ifx-text-table-header-size);
  font-weight: var(--ifx-text-table-header-weight);
  letter-spacing: var(--ifx-letter-spacing-caps);
  text-transform: uppercase;
}
.ifx-typo-table-cell, .ix-typo-table-cell, .ix-table td {
  font-family: var(--ifx-font-primary);
  font-size: var(--ifx-text-table-cell-size);
  font-weight: var(--ifx-text-table-cell-weight);
}
.ifx-typo-table-cell-dense, .ix-typo-table-cell-dense { font-size: var(--ifx-text-table-cell-dense-size); font-weight: var(--ifx-text-table-cell-dense-weight); }
.ifx-typo-table-footer, .ix-typo-table-footer { font-size: var(--ifx-text-table-footer-size); font-weight: var(--ifx-text-table-footer-weight); }

/* Chart */
.ifx-typo-chart-axis, .ix-typo-chart-axis { font-size: var(--ifx-text-chart-axis-size); }
.ifx-typo-chart-legend, .ix-typo-chart-legend { font-size: var(--ifx-text-chart-legend-size); }
.ifx-typo-chart-tooltip, .ix-typo-chart-tooltip { font-size: var(--ifx-text-chart-tooltip-size); font-weight: var(--ifx-font-weight-medium); }
.ifx-typo-chart-value, .ix-typo-chart-value { font-size: var(--ifx-text-chart-value-size); font-weight: var(--ifx-font-weight-semibold); font-variant-numeric: tabular-nums; }
.ifx-typo-chart-annotation, .ix-typo-chart-annotation { font-size: var(--ifx-text-chart-annotation-size); color: var(--ix-text-muted); }

/* Widget */
.ifx-typo-widget-title, .ix-typo-widget-title {
  font-family: var(--ifx-font-primary);
  font-size: var(--ifx-text-widget-title-size);
  font-weight: var(--ifx-text-widget-title-weight);
  line-height: var(--ifx-text-widget-title-line);
  color: var(--ix-text-primary);
}
.ifx-typo-widget-subtitle, .ix-typo-widget-subtitle { font-size: var(--ifx-text-widget-subtitle-size); font-weight: var(--ifx-text-widget-subtitle-weight); color: var(--ix-text-muted); }
.ifx-typo-widget-value, .ix-typo-widget-value, .ix-stat-value {
  font-family: var(--ifx-font-numeric);
  font-size: var(--ifx-text-widget-value-size);
  font-weight: var(--ifx-text-widget-value-weight);
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  color: var(--ix-text-primary);
}
.ix-stat-label {
  font-size: var(--ifx-text-caption-size);
  font-weight: var(--ifx-text-caption-weight);
  line-height: var(--ifx-text-caption-line);
}
.ifx-typo-widget-change, .ix-typo-widget-change, .ix-stat-trend { font-size: var(--ifx-text-widget-change-size); font-weight: var(--ifx-text-widget-change-weight); font-variant-numeric: tabular-nums; }
.ifx-typo-widget-footer, .ix-typo-widget-footer { font-size: var(--ifx-text-widget-footer-size); font-weight: var(--ifx-text-widget-footer-weight); color: var(--ix-text-muted); }
.ifx-typo-ranking-num, .ix-typo-ranking-num { font-family: var(--ifx-font-numeric); font-size: var(--ifx-text-ranking-num-size); font-weight: var(--ifx-text-ranking-num-weight); font-variant-numeric: tabular-nums; }

/* Status (color from tokens) */
.ifx-typo-status-positive, .ix-typo-status-positive { font-weight: var(--ifx-font-weight-semibold); color: var(--ix-success); font-variant-numeric: tabular-nums; }
.ifx-typo-status-negative, .ix-typo-status-negative { font-weight: var(--ifx-font-weight-semibold); color: var(--ix-danger); font-variant-numeric: tabular-nums; }
.ifx-typo-status-neutral, .ix-typo-status-neutral { font-weight: var(--ifx-font-weight-medium); color: var(--ix-text-secondary); }
.ifx-typo-status-warning, .ix-typo-status-warning { font-weight: var(--ifx-font-weight-semibold); color: var(--ix-warning); }
.ifx-typo-status-info, .ix-typo-status-info { font-weight: var(--ifx-font-weight-medium); color: var(--ix-info); }

