.ifx-fs-xl,  .ix-fs-xl  { font-size: var(--ifx-font-size-xl); }
.ifx-fs-2xl, .ix-fs-2xl { font-size: var(--ifx-font-size-2xl); }
.ifx-fs-3xl, .ix-fs-3xl { font-size: var(--ifx-font-size-3xl); }
.ifx-fs-4xl, .ix-fs-4xl { font-size: var(--ifx-font-size-4xl); }
.ifx-fs-5xl, .ix-fs-5xl { font-size: var(--ifx-font-size-5xl); }

.ifx-fs-10, .ix-fs-10 { font-size: var(--ifx-font-size-10); }
.ifx-fs-12, .ix-fs-12 { font-size: var(--ifx-font-size-12); }
.ifx-fs-14, .ix-fs-14 { font-size: var(--ifx-font-size-14); }
.ifx-fs-16, .ix-fs-16 { font-size: var(--ifx-font-size-16); }
.ifx-fs-18, .ix-fs-18 { font-size: var(--ifx-font-size-18); }
.ifx-fs-20, .ix-fs-20 { font-size: var(--ifx-font-size-20); }
.ifx-fs-24, .ix-fs-24 { font-size: var(--ifx-font-size-24); }
.ifx-fs-28, .ix-fs-28 { font-size: var(--ifx-font-size-28); }
.ifx-fs-32, .ix-fs-32 { font-size: var(--ifx-font-size-32); }
