.ifx-fw-100, .ix-fw-100 { font-weight: var(--ifx-font-weight-thin); }
.ifx-fw-200, .ix-fw-200 { font-weight: var(--ifx-font-weight-extralight); }
.ifx-fw-300, .ix-fw-300 { font-weight: var(--ifx-font-weight-light); }
.ifx-fw-400, .ix-fw-400 { font-weight: var(--ifx-font-weight-regular); }
.ifx-fw-500, .ix-fw-500 { font-weight: var(--ifx-font-weight-medium); }
.ifx-fw-600, .ix-fw-600 { font-weight: var(--ifx-font-weight-semibold); }
.ifx-fw-700, .ix-fw-700 { font-weight: var(--ifx-font-weight-bold); }
.ifx-fw-800, .ix-fw-800 { font-weight: var(--ifx-font-weight-extrabold); }
