.ifx-lh-tight, .ix-lh-tight { line-height: var(--ifx-line-height-tight); }
.ifx-lh-normal, .ix-lh-normal { line-height: var(--ifx-line-height-normal); }
.ifx-lh-relaxed, .ix-lh-relaxed { line-height: var(--ifx-line-height-relaxed); }
.ifx-lh-loose, .ix-lh-loose { line-height: var(--ifx-line-height-loose); }

.ifx-tracking-tighter, .ix-tracking-tighter { letter-spacing: var(--ifx-letter-spacing-tighter); }
.ifx-tracking-tight, .ix-tracking-tight { letter-spacing: var(--ifx-letter-spacing-tight); }
.ifx-tracking-normal, .ix-tracking-normal { letter-spacing: var(--ifx-letter-spacing-normal); }
.ifx-tracking-wide, .ix-tracking-wide { letter-spacing: var(--ifx-letter-spacing-wide); }
.ifx-tracking-wider, .ix-tracking-wider { letter-spacing: var(--ifx-letter-spacing-wider); }

.ifx-uppercase, .ix-uppercase { text-transform: uppercase; }
.ifx-lowercase, .ix-lowercase { text-transform: lowercase; }
