.ifx-underline, .ix-underline { text-decoration: underline; }
.ifx-line-through, .ix-line-through { text-decoration: line-through; }
.ifx-no-underline, .ix-no-underline { text-decoration: none; }

.ifx-font-mono, .ix-font-mono { font-family: var(--ifx-font-mono); }
.ifx-font-numeric, .ix-font-numeric { font-family: var(--ifx-font-numeric); font-variant-numeric: tabular-nums; }

/* Base document
 * html rem root = 16px (100%) — fluid tokens resolve đúng theo rem.
 * KHÔNG gán body-md lên html: sẽ thu nhỏ cả scale rem.
 */
html {
  font-family: var(--ifx-font-primary);
  font-size: 100%;
  line-height: var(--ifx-line-height-normal);
  letter-spacing: var(--ifx-letter-spacing-normal);
}
body {
  font-family: var(--ifx-font-primary);
  font-size: var(--ifx-text-body-md-size);
  font-weight: var(--ifx-text-body-md-weight);
  line-height: var(--ifx-line-height-normal);
  letter-spacing: var(--ifx-letter-spacing-normal);
}

/* Shell menu links — one size token */
.ifx-topnav-link,
.ix-dropdown-item,
.ifx-topnav-drawer-link {
  font-family: var(--ifx-font-primary);
  font-size: var(--ifx-text-label-lg-size);
  font-weight: var(--ifx-text-label-lg-weight);
  line-height: var(--ifx-text-label-lg-line);
}

/* Status badges */
.ix-badge {
  font-family: var(--ifx-font-primary);
  font-size: var(--ifx-text-label-md-size);
  font-weight: var(--ifx-text-label-md-weight);
  line-height: var(--ifx-text-label-md-line);
  letter-spacing: var(--ifx-letter-spacing-wide);
  text-transform: uppercase;
}

/**
 * iFlux Admin UI — utilities.css
 */
.ix-page-stub {
  padding: 48px 32px;
  text-align: center;
}
.ix-page-stub__icon {
  font-size: 48px;
  color: var(--ix-text-muted);
  margin-bottom: 16px;
}
.ix-page-stub__code {
  font-size: 12px;
  color: var(--ix-accent);
  font-weight: 600;
  letter-spacing: 0.04em;
}
.ix-page-stub__title {
  font-size: 20px;
  font-weight: 600;
  color: var(--ix-text-primary);
  margin: 8px 0;
}
.ix-page-stub__desc {
  font-size: 13px;
  color: var(--ix-text-muted);
  max-width: 420px;
  margin: 0 auto 24px;
  line-height: 1.6;
}
.ix-menu-badge {
  font-size: 9px;
  padding: 2px 5px;
  border-radius: 4px;
  margin-left: auto;
  background: var(--ix-bg-hover);
  color: var(--ix-text-muted);
}
.ix-hub-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.ix-hub-table th, .ix-hub-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--ix-border);
  text-align: left;
}
.ix-hub-ok { color: var(--ix-success); }
.ix-hub-partial { color: var(--ix-warning); }
.ix-hub-miss { color: var(--ix-danger); }
.ix-hub-gd2 { color: var(--ix-text-muted); }

