      return Promise.resolve(null);
    }
    return IfluxApiClient.authMe(token).then(function (profile) {
      var user = apiProfileToAppUser(profile);
      establishSession(user, token, { refresh: true });
      return user;
    }).catch(function () {
      logout();
      return null;
    });
  }

  function loginWithEmailLocal(email, password, opts) {
    opts = opts || {};
    var identifier = String(email || '').trim();
    if (!identifier) throw new Error('Nhập email');
    if (!/@/.test(identifier)) throw new Error('Nhập đúng định dạng email.');
    var loginEmail = normEmail(identifier);

    if (!opts.skipPasswordCheck) {
      if (!password) throw new Error('Nhập mật khẩu');
      if (!global.IfluxCredentialsStore) throw new Error('Không tải được hệ thống xác thực.');
      if (!IfluxCredentialsStore.verifyPassword(loginEmail, password)) {
        throw new Error('Email hoặc mật khẩu không đúng.');
      }
    }

    var user = resolveUserForLogin({ email: loginEmail });
    var isNewSocial = false;
    if (!user && opts.skipPasswordCheck && opts.socialProvider) {
      isNewSocial = true;
      user = {
        id: 'usr_social_' + opts.socialProvider.toLowerCase(),
        display_name: 'Thành viên ' + opts.socialProvider,
        email: loginEmail || identifier,
        phone: '',
        username: '@social.' + opts.socialProvider.toLowerCase(),
        tier: 'free',
        tier_label: 'Miễn phí',
        subscription_phase: 'trial_eligible',
        trial_expiry_pending: false,
        status: 'active',
        status_label: 'Hoạt động',
        role: 'Thành viên',
        referral_code: 'IFLUX' + Math.random().toString(36).slice(2, 6).toUpperCase(),
        joined_at: new Date().toLocaleDateString('vi-VN'),
        stats: { posts: 0, followers: 0, following: 0 },
        plan: {
          name: 'Miễn phí',
          tier: 'free',
          cycle: 'freemium',
          price: 0,
          currency: '₫',
          period: '',
          days_left: null,
          days_total: null,
          expires_at: null
        }
      };
    }
    if (!user) throw new Error('Không tìm thấy tài khoản với email này.');

    user = Object.assign({}, user, { email: loginEmail });
    if (opts.socialProvider) {
      user.display_name = user.display_name || ('Thành viên ' + opts.socialProvider);
    }
    establishSession(user);
    if (isNewSocial) markPendingOnboarding();
    if (!opts.skipReferrer) applyReferrerToUser(user.id);
    return user;
  }

  function loginWithSocial(provider, tokens, opts) {
    opts = opts || {};
    var p = String(provider || '').toLowerCase();
    if (useApi()) {
      return IfluxApiClient.authSocial(p, tokens || {}, opts).then(function (res) {
        return IfluxApiClient.authMe(res.token).then(function (profile) {
          var user = apiProfileToAppUser(profile);
          establishSession(user, res.token, { refresh: true });
          if (res.is_new) markPendingOnboarding();
          if (!opts.skipReferrer) applyReferrerToUser(user.id);
          return user;
        });
      });
    }
    var label = p.charAt(0).toUpperCase() + p.slice(1);
    return loginWithEmail('social+' + p + '@iflux.local', '', {
      skipPasswordCheck: true,
      socialProvider: label,
      skipReferrer: opts.skipReferrer
    });
  }

  function loginWithEmail(email, password, opts) {
    if (useApi() && !(opts && opts.skipPasswordCheck)) {
      return loginWithEmailApi(email, password, opts);
    }
    try {
      return Promise.resolve(loginWithEmailLocal(email, password, opts));
    } catch (e) {
      return Promise.reject(e);
    }
  }

  function loginWithPhone(phone, password) {
    if (useApi()) {
      return Promise.reject(new Error('Đăng nhập SĐT sẽ có sau — vui lòng dùng tab Email.'));
    }
    phone = String(phone || '').trim();
    if (!phone) throw new Error('Nhập số điện thoại');
    if (!password) throw new Error('Nhập mật khẩu');
    if (!global.IfluxCredentialsStore) throw new Error('Không tải được hệ thống xác thực.');
    if (!IfluxCredentialsStore.verifyPasswordByPhone(phone, password)) {
      throw new Error('Số điện thoại hoặc mật khẩu không đúng.');
    }

    var user = resolveUserForLogin({ phone: phone });
    if (!user) throw new Error('Số điện thoại chưa đăng ký.');

    user = Object.assign({}, user, { phone: phone });
    establishSession(user);
    applyReferrerToUser(user.id);
    return user;
  }

  function loginWithPhoneAsync(phone, otp) {
    try {
      return Promise.resolve(loginWithPhone(phone, otp));
    } catch (e) {
      return Promise.reject(e);
    }
  }

  function completeLocalRegistration(data) {
    data = data || {};
    var password = String(data.password || '');
    if (!password || password.length < 8) {
      throw new Error('Thiếu mật khẩu đăng ký. Vui lòng đăng ký lại từ đầu.');
    }

    var regEmail = data.email && /@/.test(String(data.email)) ? normEmail(data.email) : '';
    var regPhone = String(data.phone || '').trim();
    if (data.registration_mode === 'email' && !regEmail) {
      throw new Error('Thiếu email đăng ký. Vui lòng đăng ký lại.');
    }

    var user = {
      id: 'usr_' + Date.now(),
      display_name: String(data.display_name).trim(),
      email: regEmail,
      phone: regPhone,
      username: data.username || '@user' + Date.now().toString().slice(-4),
      tier: 'free',
      tier_label: 'Miễn phí',
      subscription_phase: 'trial_eligible',
      trial_expiry_pending: false,
      status: 'active',
      status_label: 'Hoạt động',
      role: 'Thành viên',
      referral_code: 'IFLUX' + Math.random().toString(36).slice(2, 6).toUpperCase(),
      joined_at: new Date().toLocaleDateString('vi-VN'),
      stats: { posts: 0, followers: 0, following: 0 },
      plan: {
        name: 'Miễn phí',
        tier: 'free',
        cycle: 'freemium',
        price: 0,
        currency: '₫',
        period: '',
        days_left: null,
        days_total: null,
        expires_at: null
      }
    };
    user.referral_link = '';

    applyRegistrationReferral(user, data);

    if (!global.IfluxCredentialsStore) throw new Error('Không tải được hệ thống xác thực.');
    var saved = IfluxCredentialsStore.setPasswords({
      email: user.email,
      phone: user.phone,
      password: password
    });
    if (!saved) {
      throw new Error('Không lưu được mật khẩu đăng ký. Vui lòng thử đăng ký lại.');
    }

    establishSession(user);
    markPendingOnboarding();
    return user;
  }

  function registerLocal(data) {
    data = data || {};
    if (!data.display_name || !String(data.display_name).trim()) {
      throw new Error('Nhập họ tên.');
    }
    if (!data.password || String(data.password).length < 8) {
      throw new Error('Mật khẩu tối thiểu 8 ký tự.');
    }

    var email = normEmail(data.email);
    var phone = String(data.phone || '').trim();
    var regMode = data.registration_mode || 'email';

    if (regMode === 'phone') {
      if (!phone) throw new Error('Nhập số điện thoại.');
    } else {
      if (!email) throw new Error('Nhập email để đăng ký.');
    }
    if (!email && !phone) {
      throw new Error('Nhập email hoặc số điện thoại.');
    }

    assertRegistrationUnique({ email: email, phone: phone });

    var verifyTarget = email || phone;
    var err = new Error('Nhập mã OTP để hoàn tất đăng ký lần đầu.');
    err.code = 'VERIFY_EMAIL';
    err.email = verifyTarget;
    err.verificationMode = 'demo';
    err.demoCode = MOCK_OTP;
    err.pendingProfile = { display_name: data.display_name, phone: phone };
    err.registrationDraft = Object.assign({}, data, {
      email: email,
      phone: phone,
      registration_mode: regMode
    });
    throw err;
  }

  function register(data) {
    if (useApi()) return registerApi(data);
    try {
      registerLocal(data);
      return Promise.resolve();
    } catch (e) {
      return Promise.reject(e);
    }
  }

  function logout() {
    clearActiveSession();
    var s = read();
    if (global.IfluxUserDataSync) IfluxUserDataSync.resetHydration();
    write(null);
  }

  function guestHomePath() {
    if (global.IfluxRoutes) return IfluxRoutes.siteRoot();
    return '/';
  }

  function appHomePath() {
    return global.IfluxRoutes ? IfluxRoutes.to('home') : '../home/index.html';
  }

  function currentReturnPath() {
    if (global.IfluxRoutes) return IfluxRoutes.currentReturnPath();
    if (global.location.protocol === 'file:') {
      var parts = global.location.href.split('/');
      var file = parts[parts.length - 1].split('?')[0];
      var dir = parts[parts.length - 2];
      return dir + '/' + file;
    }
    var path = global.location.pathname || '';
    var segs = path.split('/').filter(Boolean);
    if (segs.length >= 2) {
      return segs.slice(-2).join('/');
    }
    return segs[segs.length - 1] || 'index.html';
  }

  function requireAuth(loginPath) {
    if (!isLoggedIn()) {
      var dest;
      if (global.IfluxRoutes) {
        dest = IfluxRoutes.loginWithReturn(IfluxRoutes.pathname());
      } else {
        dest = (loginPath || '../auth/login.html') + '?return=' + encodeURIComponent(currentReturnPath());
      }
      global.location.replace(dest);
      return false;
    }
    return true;
  }

  function redirectAfterAuth(defaultPath) {
    var params = new URLSearchParams(global.location.search);
    var ret = params.get('return');
    if (ret && ret.indexOf('auth') === -1) {
      var path = decodeURIComponent(ret);
      if (path.indexOf('http') === 0 || path.indexOf('/') === 0) {
        global.location.replace(path);
      } else if (path.indexOf('../') === 0) {
        global.location.replace(path);
      } else if (global.IfluxRoutes && IfluxRoutes.route(path)) {
        global.location.replace(IfluxRoutes.to(path));
      } else {
        global.location.replace('../' + path);
      }
      return;
    }
    global.location.replace(defaultPath || (global.IfluxRoutes ? IfluxRoutes.to('home') : '../home/index.html'));
  }

  captureRefFromUrl();
  validateLocalSession();
  initCrossTabSync();
  if (!useApi()) {
    ensureDemoAccount();
    var bootUser = getUser();
    if (bootUser) saveProfile(bootUser);
  } else if (isLoggedIn()) {
    refreshSessionFromApi();
  }

  global.IfluxUserStorage = {
    DEMO_USER_ID: DEFAULT_USER.id,
    currentUserId: function () {
      var u = getUser();
      return (u && u.id) ? u.id : 'anon';
    },
    scopedKey: function (baseKey, userId) {
      userId = userId || global.IfluxUserStorage.currentUserId();
      return baseKey + '_' + userId;
    },
    migrateLegacyOnce: function (baseKey, userId) {
      userId = userId || global.IfluxUserStorage.currentUserId();
      if (userId !== DEFAULT_USER.id) return false;
      var scoped = global.IfluxUserStorage.scopedKey(baseKey, userId);
      if (localStorage.getItem(scoped)) return false;
      var legacy = localStorage.getItem(baseKey);
      if (!legacy) return false;
      localStorage.setItem(scoped, legacy);
      localStorage.removeItem(baseKey);
      return true;
    },
    readJson: function (baseKey, fallback, userId) {
      global.IfluxUserStorage.migrateLegacyOnce(baseKey, userId);
      try {
        var raw = localStorage.getItem(global.IfluxUserStorage.scopedKey(baseKey, userId));
        if (raw) return JSON.parse(raw);
      } catch (e) { /* ignore */ }
      return typeof fallback === 'function' ? fallback() : fallback;
    },
    writeJson: function (baseKey, value, userId) {
      localStorage.setItem(global.IfluxUserStorage.scopedKey(baseKey, userId), JSON.stringify(value));
    },
    removeScoped: function (baseKey, userId) {
      localStorage.removeItem(global.IfluxUserStorage.scopedKey(baseKey, userId));
    }
  };

  global.IfluxAuth = {
    MOCK_OTP: MOCK_OTP,
    DEMO_EMAIL: DEFAULT_USER.email,
    DEMO_PASSWORD: DEMO_PASSWORD,
    useApi: useApi,
    isLoggedIn: isLoggedIn,
    getUser: getUser,
    getToken: getToken,
    getPlanDaysLeft: function () { return getPlanDaysLeft(); },
    getMenuTierLabel: function () { return getMenuTierLabel(); },
    getSubscriptionState: function () { return getSubscriptionState(); },
    syncSubscriptionLifecycle: syncSubscriptionLifecycle,
    activateTrial: activateTrial,
    acknowledgeTrialExpiry: acknowledgeTrialExpiry,
    updateUser: updateUser,
    loginWithEmail: loginWithEmail,
    loginWithSocial: loginWithSocial,
    loginWithPhone: loginWithPhoneAsync,
    resetPasswordWithOtp: resetPasswordWithOtpAsync,
    register: register,
    assertRegistrationUnique: assertRegistrationUnique,
    verifyEmailAndRegister: verifyEmailAndRegister,
    resendVerificationEmail: resendVerificationEmail,
    goToVerifyOtpPage: goToVerifyOtpPage,
    loadRegistrationDraft: loadRegistrationDraft,
    loadPendingVerification: loadPendingVerification,
    clearPendingVerification: clearPendingVerification,
    markPendingOnboarding: markPendingOnboarding,
    hasPendingOnboarding: hasPendingOnboarding,
    clearPendingOnboarding: clearPendingOnboarding,
    logout: logout,
    guestHomePath: guestHomePath,
    appHomePath: appHomePath,
    hasActiveSessionElsewhere: hasActiveSessionElsewhere,
    getActiveSessionInfo: getActiveSessionInfo,
    submitEmergencyLockRequest: submitEmergencyLockRequest,
    requireAuth: requireAuth,
    redirectAfterAuth: redirectAfterAuth,
    refreshSessionFromApi: refreshSessionFromApi,
    patchUserById: patchUserById
  };
})(window);

/**
 * iFlux Block Templates — SoT giao diện block (map Design Sandbox §15).
 * Chỉ dùng design tokens (--ix-*, --color-*, --ifx-*). Không hardcode hex/rgba.
 */

/* ── TPL-SHELL-CARD / TPL-SHELL-SIDEBAR — canonical shell ── */
.ifx-block,
.ifx-mkt-card,
.ifx-flow-card,
.ifx-mkt-sidebar-widget,
.ifx-mkt-liq-block,
.ifx-com-overview,
.ifx-com-breadth-sidebar {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  overflow: hidden;
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
}

.ifx-mkt-sidebar-widget,
.ifx-com-breadth-sidebar,
.ifx-mkt-card,
.ifx-flow-card,
.ifx-mkt-liq-block {
  display: flex;
  flex-direction: column;
}

/* Widget Header Block do widget-shell.css sở hữu. */
.ifx-com-breadth-sidebar > .ifx-widget__subtitle {
  padding: 0 var(--ifx-inset-widget);
  margin: 0;
  border-bottom: 1px solid var(--ix-border);
}
.ifx-com-breadth-sidebar > .ifx-mkt-sidebar-widget__body {
  flex: 1;
  min-width: 0;
}

.ifx-block__body,
.ifx-mkt-card__body,
.ifx-flow-card__body,
.ifx-mkt-sidebar-widget__body,
.ifx-com-overview__body,
.ifx-mkt-liq-block__body {
  padding: var(--ifx-inset-widget);
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
}

.ifx-block__foot,
.ifx-mkt-card__foot,
.ifx-flow-card__foot {
  padding: var(--ifx-inset-widget);
  border-top: 1px solid var(--ix-border);
}

.ifx-flow-card__sub,
.ifx-mkt-section__sub {
  margin: 0;
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-muted);
  line-height: 1.5;
}

/* ── TPL-BREADTH / TMP-BREADTH — CSS owner duy nhất (6-stat + ratio) ──
 * Mật độ mặc định = giao diện sidebar Thị trường (3 cột × 2 hàng).
 * Page placement (community.css) chỉ được override mật độ hẹp — không copy core.
 */
.ifx-breadth-block { min-width: 0; }

.ifx-breadth-visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--ifx-space-16);
}
.ifx-breadth-visual--6 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--ifx-space-8);
}

.ifx-breadth-stat {
  text-align: center;
  padding: 10px 8px;
  border-radius: var(--ix-radius);
  border: 1px solid var(--ix-border);
}
.ifx-breadth-stat.is-total { background: var(--ifx-alpha-white-4); }
.ifx-breadth-stat.is-up { background: var(--ix-success-soft); }
.ifx-breadth-stat.is-down { background: var(--ix-danger-soft); }
.ifx-breadth-stat.is-ref { background: var(--ix-warning-soft); }
.ifx-breadth-stat.is-ceiling { background: var(--ifx-market-ceiling-soft); }
.ifx-breadth-stat.is-floor { background: var(--ifx-market-floor-soft); }

.ifx-breadth-stat__num {
  font-size: var(--ifx-font-size-24);
  font-weight: 800;
  font-family: var(--ifx-font-mono);
  line-height: 1.1;
}

.ifx-breadth-stat__label {
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  margin-top: 6px;
  line-height: 1.25;
}

.ifx-breadth-stat.is-total .ifx-breadth-stat__num { color: var(--ix-text-primary); }
.ifx-breadth-stat.is-up .ifx-breadth-stat__num { color: var(--ix-success); }
.ifx-breadth-stat.is-down .ifx-breadth-stat__num { color: var(--ix-danger); }
.ifx-breadth-stat.is-ref .ifx-breadth-stat__num { color: var(--ix-warning); }
.ifx-breadth-stat.is-ceiling .ifx-breadth-stat__num { color: var(--ifx-market-ceiling); }
.ifx-breadth-stat.is-floor .ifx-breadth-stat__num { color: var(--ifx-market-floor); }

.ifx-breadth-ratio {
  display: flex;
  height: 6px;
  border-radius: 3px;
  overflow: hidden;
  margin-top: var(--ifx-space-12);
  background: var(--ix-bg-input);
}
.ifx-breadth-ratio__up { background: var(--ix-success); }
.ifx-breadth-ratio__down { background: var(--ix-danger); }

@media (max-width: 768px) {
  .ifx-breadth-visual--6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .ifx-breadth-visual--6 .ifx-breadth-stat__num { font-size: var(--ifx-font-size-20); }
}

/* ── TPL-TREEMAP — heat / cap tiles ── */
.ifx-treemap { position: relative; width: 100%; }

.ifx-treemap-tile,
.ifx-mkt-heat-tile,
.ifx-cap-tile {
  position: absolute;
  box-sizing: border-box;
}

.ifx-treemap-tile__link,
.ifx-mkt-heat-tile__link,
.ifx-cap-tile__link {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border-radius: var(--ix-radius);
  text-decoration: none;
  padding: 6px;
  box-sizing: border-box;
  text-align: center;
  gap: var(--ifx-space-4);
  transition: filter var(--ifx-duration-fast), transform var(--ifx-duration-fast);
}
.ifx-treemap-tile__link:hover,
.ifx-mkt-heat-tile__link:hover,
.ifx-cap-tile__link:hover {
  filter: brightness(1.08);
  transform: scale(1.01);
}

.ifx-treemap-tile__link.is-up,
.ifx-mkt-heat-tile__link.is-up,
.ifx-cap-tile__link.is-up {
  background: var(--ifx-market-up);
  color: var(--color-text-on-success);
}
.ifx-treemap-tile__link.is-down,
.ifx-mkt-heat-tile__link.is-down,
.ifx-cap-tile__link.is-down {
  background: var(--ifx-market-down);
  color: var(--color-text-on-danger);
}
.ifx-treemap-tile__link.is-ref,
.ifx-mkt-heat-tile__link.is-ref,
.ifx-cap-tile__link.is-ref {
  background: var(--ifx-market-ref);
  color: var(--color-text-on-warning);
}
.ifx-treemap-tile__link.is-ceiling,
.ifx-cap-tile__link.is-ceiling {
  background: var(--ifx-market-ceiling);
  color: var(--color-text-on-primary);
}
.ifx-treemap-tile__link.is-floor,
.ifx-cap-tile__link.is-floor {
  background: var(--ifx-market-floor);
  color: var(--color-text-on-info);
}

.ifx-treemap-tile__name,
.ifx-mkt-heat-tile__name,
.ifx-cap-tile__name {
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-semibold);
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.ifx-treemap-tile__perf,
.ifx-mkt-heat-tile__perf,
.ifx-cap-tile__perf {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  font-family: var(--ifx-font-mono);
}

/* Heatmap tail — gộp phần còn lại ≤5% vốn hóa thành một ô "..." */
.ifx-mkt-heat-tile--remainder,
.ifx-cap-tile--remainder {
  pointer-events: none;
}
.ifx-mkt-heat-tile__remainder,
.ifx-cap-tile__remainder,
.ifx-treemap-tile__remainder {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border-radius: 6px;
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-muted);
  background: var(--ix-bg-muted);
  letter-spacing: 0.12em;
}
.ifx-mkt-heat-tile__remainder.is-remainder,
.ifx-cap-tile__remainder.is-remainder,
.ifx-treemap-tile__remainder.is-remainder {
  background: var(--ix-bg-hover);
}

/* ── TPL-WGT-HEAD — dùng .ifx-widget__header (widget-shell.css) ── */

/* ── Market direction utilities (text / border only) ── */
.is-up { color: var(--ix-success); }
.is-down { color: var(--ix-danger); }
.is-ref { color: var(--ix-warning); }
.is-flat { color: var(--ix-text-muted); }
.is-ceiling { color: var(--ifx-market-ceiling); }
.is-floor { color: var(--ifx-market-floor); }

/* ── TPL-RANK-BAR — horizontal rank list ── */
.ifx-rank-bar__head,
.ifx-mkt-rank-head {
  display: grid;
  grid-template-columns: 28px minmax(100px, 140px) minmax(0, 1fr) minmax(72px, 88px);
  gap: var(--ifx-inline-md);
  padding: 0 4px 8px;
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ix-text-muted);
}
.ifx-rank-bar__head span:nth-child(2),
.ifx-mkt-rank-head span:nth-child(2) { grid-column: 2; }
.ifx-rank-bar__head span:nth-child(3),
.ifx-mkt-rank-head span:nth-child(3) { grid-column: 3 / span 2; text-align: right; }

.ifx-rank-bar__list,
.ifx-mkt-rank-list {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-inline-md);
}

.ifx-rank-bar__row,
.ifx-mkt-rank-row {
  display: grid;
  grid-template-columns: 28px minmax(100px, 140px) minmax(0, 1fr) minmax(72px, 88px);
  align-items: center;
  gap: var(--ifx-inline-md);
}

.ifx-rank-bar__idx,
.ifx-mkt-rank-idx {
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-muted);
  text-align: center;
}

.ifx-rank-bar__name,
.ifx-mkt-rank-name {
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ifx-rank-bar__track,
.ifx-mkt-rank-bar-track {
  height: 10px;
  background: var(--ix-accent-soft);
  border-radius: 5px;
  overflow: hidden;
}

.ifx-rank-bar__fill,
.ifx-mkt-rank-bar {
  height: 100%;
  border-radius: 5px;
  min-width: 4px;
  transition: width var(--ifx-duration-normal) ease;
}
.ifx-rank-bar__fill.is-up,
.ifx-mkt-rank-bar.is-up {
  background: linear-gradient(90deg, var(--ix-success-soft), var(--ix-success));
}
.ifx-rank-bar__fill.is-down,
.ifx-mkt-rank-bar.is-down {
  background: linear-gradient(90deg, var(--ix-danger-soft), var(--ix-danger));
}
.ifx-rank-bar__fill.is-flat,
.ifx-mkt-rank-bar.is-flat { background: var(--ix-text-muted); }

.ifx-rank-bar__val,
.ifx-mkt-rank-val {
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-bold);
  font-family: var(--ifx-font-mono);
  text-align: right;
}
.ifx-rank-bar__val.is-up,
.ifx-mkt-rank-val.is-up { color: var(--ix-success); }
.ifx-rank-bar__val.is-down,
.ifx-mkt-rank-val.is-down { color: var(--ix-danger); }
.ifx-rank-bar__val.is-flat,
.ifx-mkt-rank-val.is-flat { color: var(--ix-text-muted); }

/* ── TPL-DIVERGING-BARS / TMP-DIVERGING-BARS — CSS owner duy nhất ──
 * Cột hai chiều quanh trục 0 (dương lên / âm xuống) + chú thích.
 * HTML producer: IfluxBlockTemplates.renderDivergingBars* (block-templates.js).
 * Trước đây hardcode ở stock.css (Giao dịch theo chủ thể) — đã dời về đây.
 */
.ifx-stock-flow-chart {
  margin-top: var(--ifx-space-4);
}

.ifx-stock-flow-hint {
  margin: 0 0 12px;
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
}

.ifx-stock-flow-chart__inner {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: var(--ifx-inline-sm);
  align-items: start;
}

.ifx-stock-flow-chart__yaxis {
  position: relative;
  height: 200px;
  font-size: 9px;
  color: var(--ix-text-muted);
}

.ifx-stock-flow-chart__ytick {
  position: absolute;
  left: 0;
  transform: translateY(-50%);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  opacity: 0.25;
  line-height: 1;
}

.ifx-stock-flow-chart__plot {
  position: relative;
  min-width: 0;
}

.ifx-stock-flow-chart__bars-wrap {
  position: relative;
  height: 200px;
}

.ifx-stock-flow-chart__bars {
  display: flex;
  gap: var(--ifx-space-4);
  height: 100%;
  align-items: stretch;
}

.ifx-stock-flow-chart__zero {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
  background: var(--ix-text-muted);
  opacity: 0.25;
  z-index: 2;
  pointer-events: none;
}

.ifx-stock-flow-chart__col {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  height: 100%;
}

.ifx-stock-flow-chart__half {
  flex: 1;
  display: flex;
  min-height: 0;
}

.ifx-stock-flow-chart__half.is-top {
  align-items: flex-end;
  justify-content: center;
}

.ifx-stock-flow-chart__half.is-bottom {
  align-items: flex-start;
  justify-content: center;
}

.ifx-stock-flow-chart__bar {
  width: 72%;
  max-width: 28px;
  border-radius: 3px 3px 0 0;
  min-height: 2px;
}

.ifx-stock-flow-chart__bar.is-pos {
  background: var(--ix-success);
  border-radius: 3px 3px 0 0;
}

.ifx-stock-flow-chart__bar.is-neg {
  background: var(--ix-danger);
  border-radius: 0 0 3px 3px;
}

.ifx-stock-flow-chart__xlabels {
  display: flex;
  gap: var(--ifx-space-4);
  margin-top: var(--ifx-space-8);
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
}

.ifx-stock-flow-chart__xlabels span {
  flex: 1;
  min-width: 0;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

/* ── TPL-ZONE-POSITION / TMP-ZONE-POSITION — CSS owner duy nhất ──
 * Mỗi dòng = 1 giai đoạn: nhãn · thanh vị trí (trái/phải + marker) · vùng + giá giữa.
 * HTML producer: IfluxBlockTemplates.renderZonePosition*
 * Màu: trái = success (hỗ trợ) · phải = danger (kháng cự) — token DS.
 */
.ifx-zone-pos {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-space-16);
  min-width: 0;
}

.ifx-zone-pos__row {
  min-width: 0;
}

.ifx-zone-pos__period {
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-primary);
  margin-bottom: var(--ifx-space-8);
}

.ifx-zone-pos__track-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: var(--ifx-space-8);
  align-items: center;
}

.ifx-zone-pos__side-label {
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  white-space: nowrap;
}
.ifx-zone-pos__side-label.is-left { color: var(--ix-success); }
.ifx-zone-pos__side-label.is-right { color: var(--ix-danger); }

.ifx-zone-pos__bar {
  position: relative;
  display: flex;
  align-items: stretch;
  height: 22px;
  border-radius: var(--ix-radius);
  overflow: hidden;
  background: var(--ix-bg-input);
  min-width: 0;
}

.ifx-zone-pos__seg {
  display: flex;
  align-items: center;
  min-width: 0;
  overflow: hidden;
}
.ifx-zone-pos__seg.is-left {
  justify-content: center;
  background: var(--ix-success-soft);
}
.ifx-zone-pos__seg.is-right {
  justify-content: center;
  background: var(--ix-danger-soft);
}

.ifx-zone-pos__pct {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-semibold);
  font-family: var(--ifx-font-mono);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  white-space: nowrap;
  padding: 0 4px;
}
.ifx-zone-pos__seg.is-left .ifx-zone-pos__pct { color: var(--ix-success); }
.ifx-zone-pos__seg.is-right .ifx-zone-pos__pct { color: var(--ix-danger); }

.ifx-zone-pos__marker {
  flex: 0 0 2px;
  width: 2px;
  align-self: stretch;
  background: var(--ix-text-primary);
  z-index: 1;
  box-shadow: 0 0 0 1px var(--ix-bg-card);
}

.ifx-zone-pos__values {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: var(--ifx-space-8);
  margin-top: var(--ifx-space-4);
  font-size: var(--ifx-font-size-10);
  font-family: var(--ifx-font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--ix-text-muted);
}

.ifx-zone-pos__range.is-left { text-align: left; }
.ifx-zone-pos__range.is-right { text-align: right; }

.ifx-zone-pos__center {
  text-align: center;
  font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-primary);
  font-size: var(--ifx-font-size-12);
}

@media (max-width: 480px) {
  .ifx-zone-pos__track-row {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--ifx-space-4);
  }
  .ifx-zone-pos__side-label {
    display: none;
  }
  .ifx-zone-pos__values {
    font-size: var(--ifx-font-size-10);
  }
}

/* ── TPL-SR-HISTORY / TMP-SR-HISTORY — Lịch sử Hỗ trợ | Kháng cự ──
 * Tabs (ix-segmented) · nhãn 3 cột · thanh trái/phải + chấm Hiện tại · vùng giá · hint %.
 * HTML: IfluxBlockTemplates.renderSrHistory · chỉ token DS.
 */
.ifx-sr-hist {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-space-16);
  min-width: 0;
}
.ifx-sr-hist__tabs {
  width: 100%;
  flex-wrap: wrap;
}
.ifx-sr-hist__panel {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-space-8);
  min-width: 0;
}
.ifx-sr-hist__labels,
.ifx-sr-hist__values {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: var(--ifx-space-8);
  align-items: end;
}
.ifx-sr-hist__label {
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-muted);
}
.ifx-sr-hist__label.is-left {
  text-align: left;
  color: var(--ix-success);
}
.ifx-sr-hist__label.is-center {
  text-align: center;
  color: var(--ix-text-secondary);
}
.ifx-sr-hist__label.is-right {
  text-align: right;
  color: var(--ix-danger);
}
.ifx-sr-hist__bar {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-4);
  min-height: 14px;
  min-width: 0;
}
.ifx-sr-hist__seg {
  height: 12px;
  border-radius: var(--ix-radius);
  min-width: 0;
}
.ifx-sr-hist__seg.is-left {
  background: var(--ix-success);
  opacity: 0.85;
}
.ifx-sr-hist__seg.is-right {
  background: var(--ix-danger);
  opacity: 0.85;
}
.ifx-sr-hist__dot {
  flex: 0 0 10px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--ix-text-primary);
  box-shadow: 0 0 0 2px var(--ix-bg-card);
}
.ifx-sr-hist__range,
.ifx-sr-hist__price {
  font-family: var(--ifx-font-mono);
  font-variant-numeric: tabular-nums;
  font-size: var(--ifx-font-size-12);
}
.ifx-sr-hist__range.is-left {
  text-align: left;
  color: var(--ix-text-secondary);
}
.ifx-sr-hist__range.is-right {
  text-align: right;
  color: var(--ix-text-secondary);
}
.ifx-sr-hist__price {
  text-align: center;
  font-weight: var(--ifx-font-weight-semibold);
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-primary);
}
.ifx-sr-hist__hints {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--ifx-space-8);
}
.ifx-sr-hist__hint {
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
}
.ifx-sr-hist__hint.is-left {
  text-align: left;
  color: var(--ix-success);
}
.ifx-sr-hist__hint.is-right {
  text-align: right;
  color: var(--ix-danger);
}

/* ── TPL-FLOW-SPLIT — symmetric net-flow ── */
.ifx-flow-split-block { min-width: 0; }

.ifx-flow-split__head {
  display: grid;
  grid-template-columns: 1fr minmax(52px, 88px) minmax(52px, 88px) 1fr;
  gap: var(--ifx-space-8);
  margin-bottom: 10px;
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--ix-text-muted);
}
.ifx-flow-split__col-h--buy { text-align: right; }
.ifx-flow-split__col-h--tick-buy { text-align: right; }
.ifx-flow-split__col-h--tick-sell { text-align: left; }
.ifx-flow-split__col-h--sell { text-align: left; }
.ifx-flow-split__dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  margin-right: 5px;
  vertical-align: middle;
}
.ifx-flow-split__dot.is-buy { background: var(--ifx-flow-in); }
.ifx-flow-split__dot.is-sell { background: var(--ifx-flow-out); }

.ifx-flow-split__row {
  display: grid;
  grid-template-columns: 1fr minmax(52px, 88px) minmax(52px, 88px) 1fr;
  gap: var(--ifx-space-8);
  align-items: center;
  min-height: 34px;
  margin-bottom: var(--ifx-space-8);
}
.ifx-flow-split__row:hover {
  background: var(--ix-accent-soft);
  border-radius: var(--ix-radius);
}

.ifx-flow-split__buy,
.ifx-flow-split__sell {
  display: flex;
  align-items: center;
  min-height: 28px;
}
.ifx-flow-split__buy { justify-content: flex-end; }
.ifx-flow-split__sell { justify-content: flex-start; }

.ifx-flow-split__bar {
  position: relative;
  height: 22px;
  min-width: 36px;
  max-width: 100%;
  border-radius: 4px;
  display: flex;
  align-items: center;
}
.ifx-flow-split__bar--buy {
  background: var(--ifx-market-up-soft);
  justify-content: flex-end;
}
.ifx-flow-split__bar--sell {
  background: var(--ifx-market-down-soft);
  justify-content: flex-start;
}
.ifx-flow-split__val {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  padding: 0 6px;
  white-space: nowrap;
}
.ifx-flow-split__bar--buy .ifx-flow-split__val { color: var(--ifx-flow-in); }
.ifx-flow-split__bar--sell .ifx-flow-split__val { color: var(--ifx-flow-out); }

.ifx-flow-split__ticker {
  display: block;
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-primary);
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ifx-flow-split__ticker--buy { text-align: right; padding-right: 2px; }
.ifx-flow-split__ticker--sell { text-align: left; padding-left: 2px; }
.ifx-flow-split__ticker:hover { color: var(--ix-accent); }
.ifx-flow-split__ticker--empty {
  color: var(--ix-text-muted);
  font-weight: var(--ifx-font-weight-regular);
}

/* ── TPL-INDEX-GRID — exchange mini cards ── */
.ifx-index-grid,
.ifx-com-ex-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--ifx-inline-md);
}

.ifx-index-card,
.ifx-com-ex-card {
  background: var(--ix-bg-body);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius);
  padding: var(--ifx-space-12) 14px;
}

.ifx-index-card__name,
.ifx-com-ex-card__name {
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: var(--ifx-space-4);
}

.ifx-index-card__val,
.ifx-com-ex-card__val {
  font-size: var(--ifx-font-size-18);
  font-weight: var(--ifx-font-weight-bold);
  font-family: var(--ifx-font-mono);
  color: var(--ix-text-primary);
  line-height: 1.2;
}

.ifx-index-card__chg,
.ifx-com-ex-card__chg {
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-semibold);
  margin-top: var(--ifx-space-4);
  font-family: var(--ifx-font-mono);
}
.ifx-index-card__chg.is-up,
.ifx-com-ex-card__chg.is-up { color: var(--ix-success); }
.ifx-index-card__chg.is-down,
.ifx-com-ex-card__chg.is-down { color: var(--ix-danger); }

/* Chart series stroke — dùng trong SVG Top 10 */
.ix-top10-market__line[data-series="1"] { stroke: var(--ifx-color-chart-1); }
.ix-top10-market__line[data-series="2"] { stroke: var(--ifx-color-chart-2); }
.ix-top10-market__line[data-series="3"] { stroke: var(--ifx-color-chart-3); }
.ix-top10-market__line[data-series="4"] { stroke: var(--ifx-color-chart-4); }
.ix-top10-market__line[data-series="5"] { stroke: var(--ifx-color-chart-5); }
.ix-top10-market__line[data-series="6"] { stroke: var(--ifx-color-chart-6); }
.ix-top10-market__line[data-series="7"] { stroke: var(--ifx-color-chart-7); }
.ix-top10-market__line[data-series="8"] { stroke: var(--ifx-color-chart-8); }
.ix-top10-market__line[data-series="9"] { stroke: var(--ifx-color-chart-9); }
.ix-top10-market__line[data-series="10"] { stroke: var(--ifx-color-chart-10); }

.ix-top10-market__legend-dot[data-series="1"] { background: var(--ifx-color-chart-1); }
.ix-top10-market__legend-dot[data-series="2"] { background: var(--ifx-color-chart-2); }
.ix-top10-market__legend-dot[data-series="3"] { background: var(--ifx-color-chart-3); }
.ix-top10-market__legend-dot[data-series="4"] { background: var(--ifx-color-chart-4); }
.ix-top10-market__legend-dot[data-series="5"] { background: var(--ifx-color-chart-5); }
.ix-top10-market__legend-dot[data-series="6"] { background: var(--ifx-color-chart-6); }
.ix-top10-market__legend-dot[data-series="7"] { background: var(--ifx-color-chart-7); }
.ix-top10-market__legend-dot[data-series="8"] { background: var(--ifx-color-chart-8); }
.ix-top10-market__legend-dot[data-series="9"] { background: var(--ifx-color-chart-9); }
.ix-top10-market__legend-dot[data-series="10"] { background: var(--ifx-color-chart-10); }

/* ── TPL-LIST-ROW — stock / entity row ── */
.ifx-list-row,
.ifx-stock-row {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) minmax(0, auto) 72px 64px 64px;
  align-items: center;
  gap: var(--ifx-inline-sm) 8px;
  min-height: 44px;
  padding: 10px 12px;
  text-decoration: none;
  color: inherit;
  white-space: nowrap;
}
.ifx-stock-row__ticker {
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-primary);
}
.ifx-stock-row__name {
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}
.ifx-stock-row__price,
.ifx-stock-row__chg,
.ifx-stock-row__vol {
  font-family: var(--ifx-font-mono);
  text-align: right;
}
.ifx-stock-row__price { font-size: var(--ifx-font-size-16); font-weight: var(--ifx-font-weight-bold); }
.ifx-stock-row__chg { font-size: var(--ifx-font-size-14); font-weight: var(--ifx-font-weight-semibold); }
.ifx-stock-row__vol { font-size: var(--ifx-font-size-12); color: var(--ix-text-muted); }
.ifx-stock-row.is-up .ifx-stock-row__price,
.ifx-stock-row.is-up .ifx-stock-row__chg { color: var(--ix-success); }
.ifx-stock-row.is-down .ifx-stock-row__price,
.ifx-stock-row.is-down .ifx-stock-row__chg { color: var(--ix-danger); }

/* TPL-LIST-ROW responsive — cùng biên Breakpoint SoT với StockRow component. */
@media (max-width: 1023.98px) {
  .ifx-list-row.ifx-stock-row {
    grid-template-columns: 48px minmax(0, 1fr) minmax(0, auto) 64px 52px;
  }
  .ifx-list-row.ifx-stock-row .ifx-stock-row__vol { display: none; }
}

@media (max-width: 767.98px) {
  .ifx-list-row.ifx-stock-row {
    grid-template-columns: 48px minmax(56px, 1fr) minmax(52px, auto);
  }
  .ifx-list-row.ifx-stock-row .ifx-stock-row__name,
  .ifx-list-row.ifx-stock-row .ifx-stock-row__vol { display: none; }
}

/* Preview/Widget host có container context: phản hồi theo không gian được cấp,
   dùng cùng biên bp-md/bp-lg thay vì viewport thật của trang Authoring. */
@container (max-width: 1023.98px) {
  .ifx-list-row.ifx-stock-row {
    grid-template-columns: 48px minmax(0, 1fr) minmax(0, auto) 64px 52px;
  }
  .ifx-list-row.ifx-stock-row .ifx-stock-row__vol { display: none; }
}

@container (max-width: 767.98px) {
  .ifx-list-row.ifx-stock-row {
    grid-template-columns: 48px minmax(56px, 1fr) minmax(52px, auto);
  }
  .ifx-list-row.ifx-stock-row .ifx-stock-row__name,
  .ifx-list-row.ifx-stock-row .ifx-stock-row__vol { display: none; }
}

/* ── TPL-FEED-CARD — community post ── */
.ifx-feed-card,
.ifx-com-post {
  display: flex;
  flex-direction: column;
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  overflow: hidden;
  transition: transform var(--ifx-duration-fast), box-shadow var(--ifx-duration-fast), border-color var(--ifx-duration-fast);
}
.ifx-feed-card:hover,
.ifx-com-post:hover {
  transform: translateY(-2px);
  box-shadow: var(--ifx-shadow-topnav);
  border-color: var(--ix-accent);
}
.ifx-com-card {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: var(--ifx-space-16) 18px;
  transition: border-color var(--ifx-duration-fast), box-shadow var(--ifx-duration-fast);
}
.ifx-com-card:hover {
  border-color: var(--ix-accent);
  box-shadow: var(--ifx-shadow-topnav);
}
.ifx-com-card__avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--ix-accent-soft);
  color: var(--ix-accent);
  font-weight: var(--ifx-font-weight-bold);
  font-size: var(--ifx-font-size-14);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.ifx-com-post__thumb {
  display: block;
  aspect-ratio: 16 / 9;
  background: var(--ix-bg-hover);
  overflow: hidden;
  position: relative;
}
.ifx-com-post__thumb-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--ix-accent-soft), var(--ix-info-soft));
}
.ifx-com-post__thumb-fallback i {
  font-size: 42px;
  color: var(--ix-text-muted);
  opacity: 0.35;
}

/**
 * iFlux Block Templates — registry + render API (Design Sandbox SoT §15).
 * Mỗi template = 1 nhóm block cùng hình thức; truyền data → HTML chuẩn.
 */
(function (global) {
  'use strict';

  /* Phase A: guard nạp trùng (Shell đã có → Feature CORE_TIERS không execute lại). */
  if (global.IfluxBlockTemplates) return;

  var BREADTH_STATS = [
    { key: 'total', label: 'Toàn bộ', cls: 'is-total' },
    { key: 'up', label: 'Mã tăng', cls: 'is-up' },
    { key: 'down', label: 'Mã giảm', cls: 'is-down' },
    { key: 'ref', label: 'Mã tham chiếu', cls: 'is-ref' },
    { key: 'ceiling_purple', label: 'Mã tím trần', cls: 'is-ceiling' },
    { key: 'floor_green', label: 'Mã sàn xanh', cls: 'is-floor' }
  ];

  var BREADTH_EXCHANGES = [
    { key: 'vnindex', label: 'VN-Index' },
    { key: 'hose', label: 'HOSE' },
    { key: 'hnx', label: 'HNX' },
    { key: 'upcom', label: 'UPCOM' }
  ];

  /** SoT: nhóm template ↔ block IDs (map §13 Design Sandbox) */
  var REGISTRY = [
    {
      id: 'TPL-SHELL-CARD',
      label: 'Card shell (head + body)',
      classes: 'ifx-block ifx-block--card',
      blocks: [
        'BLK-MKT-HEAT', 'BLK-MKT-LIQ', 'BLK-MKT-RANKINGS',
        'BLK-FLW-NET-STOCK', 'BLK-FLW-NET-SECTOR', 'BLK-FLW-NET-HST', 'BLK-FLW-NET-CHUDE',
        'BLK-FLW-SCORE', 'BLK-FLW-CTX', 'BLK-FLW-SMART'
      ]
    },
    {
      id: 'TPL-SHELL-SIDEBAR',
      label: 'Sidebar widget shell',
      classes: 'ifx-block ifx-block--sidebar',
      blocks: ['BLK-MKT-OVERVIEW', 'BLK-MKT-BREADTH', 'BLK-COM-OVERVIEW', 'BLK-COM-BREADTH']
    },
    {
      id: 'TPL-SHELL-WIDGET',
      label: 'Dashboard widget shell',
      classes: 'ifx-widget',
      blocks: ['WGT-*']
    },
    {
      id: 'TPL-BREADTH',
      label: 'Breadth stat grid + ratio bar',
      classes: 'ifx-breadth-block, ifx-breadth-stat, ifx-breadth-ratio',
      blocks: ['BLK-MKT-BREADTH', 'BLK-COM-BREADTH']
    },
    {
      id: 'TPL-TREEMAP',
      label: 'Treemap heat tile',
      classes: 'ifx-treemap-tile, ifx-mkt-heat-tile, ifx-cap-tile',
      blocks: ['BLK-MKT-HEAT-SECTOR', 'BLK-MKT-HEAT-FAMILY', 'BLK-MKT-HEAT-CHUDE', 'BLK-COM-TREND']
    },
    {
      id: 'TPL-DIVERGING-BARS',
      label: 'Cột hai chiều quanh trục 0 (dương / âm)',
      classes: 'ifx-stock-flow-chart',
      blocks: ['BLK-STK-FLOW']
    },
    {
      id: 'TPL-ZONE-POSITION',
      label: 'Vị trí giữa hai vùng (thanh + %)',
      classes: 'ifx-zone-pos',
      blocks: []
    },
    {
      id: 'TPL-SR-HISTORY',
      label: 'Lịch sử Hỗ trợ — Kháng cự (tab + thanh vị trí)',
      classes: 'ifx-sr-hist',
      blocks: []
    },
    {
      id: 'TPL-RANK-BAR',
      label: 'Horizontal rank / Top 10 bars',
      classes: 'ifx-rank-bar, ix-top10-market',
      blocks: ['BLK-MKT-RANKINGS', 'WGT-TOP-001', 'WGT-TOP-002', 'WGT-TOP-003', 'WGT-MKT-003']
    },
    {
      id: 'TPL-FLOW-SPLIT',
      label: 'Symmetric net-flow chart',
      classes: 'ifx-flow-split, ifx-flow-split-block',
      blocks: ['BLK-FLW-NET-STOCK', 'BLK-FLW-NET-SECTOR', 'BLK-FLW-NET-HST', 'BLK-FLW-NET-CHUDE']
    },
    {
      id: 'TPL-INDEX-GRID',
      label: 'Exchange index mini cards',
      classes: 'ifx-com-ex-grid, ifx-com-ex-card',
      blocks: ['BLK-MKT-OVERVIEW', 'BLK-COM-OVERVIEW']
    },
    {
      id: 'TPL-LIST-ROW',
      label: 'Stock / entity list row',
      classes: 'ifx-stock-row',
      blocks: ['BLK-MKT-MOVERS', 'WGT-WAT-001']
    },
    {
      id: 'TPL-FEED-CARD',
      label: 'Community post card',
      classes: 'ifx-com-card',
      blocks: ['BLK-COM-FEED']
    }
  ];

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  var ENTITY_KINDS = { stock: 1, sector: 1, family: 1, 'cau-chuyen': 1 };

  /**
   * Entity Renderer — marker semantic duy nhất (CP / Ngành / HST / Câu chuyện).
   * Widget chỉ gọi helper; Permission không gắn marker từng file.
   * opts: { className, title, tiny }
   */
  function entityName(label, kind, opts) {
    opts = opts || {};
    kind = ENTITY_KINDS[kind] ? kind : 'stock';
    var text = opts.tiny && label ? String(label).split(' ')[0] : String(label == null ? '' : label);
    var cls = 'ifx-entity-name' + (opts.className ? ' ' + opts.className : '');
    var title = opts.title != null ? opts.title : text;
    return (
      '<span class="' + esc(cls) + '" data-ifx-role="entity-name" data-ifx-entity-kind="' + esc(kind) + '"' +
        (title ? ' title="' + esc(title) + '"' : '') +
        ' data-ifx-entity-raw="' + esc(text) + '">' +
        esc(text) +
      '</span>'
    );
  }

  function maskBullet(len) {
    var n = Math.max(3, Math.min(12, Number(len) || 6));
    var out = '';
    var i;
    for (i = 0; i < n; i++) out += '•';
    return out;
  }

  function maskEntityNames(root) {
    if (!root || !root.querySelectorAll) return;
    root.querySelectorAll('[data-ifx-role="entity-name"]').forEach(function (el) {
      var raw = el.getAttribute('data-ifx-entity-raw');
      if (raw == null) {
        raw = el.textContent || '';
        el.setAttribute('data-ifx-entity-raw', raw);
      }
      el.textContent = maskBullet(String(raw).length);
      el.setAttribute('data-ifx-entity-masked', '1');
      el.removeAttribute('title');
    });
  }

  function unmaskEntityNames(root) {
    if (!root || !root.querySelectorAll) return;
    root.querySelectorAll('[data-ifx-role="entity-name"][data-ifx-entity-masked]').forEach(function (el) {
      var raw = el.getAttribute('data-ifx-entity-raw') || '';
      el.textContent = raw;
      el.removeAttribute('data-ifx-entity-masked');
      if (raw) el.setAttribute('title', raw);
    });
  }

  function templateForBlock(blockId) {
    var i;
    for (i = 0; i < REGISTRY.length; i++) {
      var t = REGISTRY[i];
      var j;
      for (j = 0; j < t.blocks.length; j++) {
        var b = t.blocks[j];
        if (b === blockId) return t;
        if (b.indexOf('*') >= 0) {
          var prefix = b.replace('*', '');
          if (blockId.indexOf(prefix) === 0) return t;
        }
      }
    }
    return null;
  }

  /**
   * TPL-SHELL-CARD | TPL-SHELL-SIDEBAR
   * opts: { variant, title, icon, desc, sub, body, foot, attrs, tag }
   */
  function renderShell(opts) {
    opts = opts || {};
    var variant = opts.variant || 'card';
    var tag = opts.tag || 'div';
    var extra = opts.attrs ? ' ' + opts.attrs : '';
    var shellCls = 'ifx-block ifx-block--' + variant;
    if (opts.shellClass) shellCls += ' ' + opts.shellClass;

    /* Widget Header thuộc Widget Shell; Template chỉ cung cấp body/sub/foot. */
    var headHtml = opts.title
      ? renderWgtHead(opts.title, opts.desc || '', opts.icon)
      : '';
    var subHtml = opts.sub
      ? '<div class="ifx-block__sub">' + esc(opts.sub) + '</div>'
      : '';
    var bodyHtml = opts.body != null
      ? '<div class="ifx-block__body">' + opts.body + '</div>'
      : '';
    var footHtml = opts.foot
      ? '<div class="ifx-block__foot">' + opts.foot + '</div>'
      : '';

    return (
      '<' + tag + ' class="' + shellCls + '"' + extra + '>' +
        headHtml + subHtml + bodyHtml + footHtml +
      '</' + tag + '>'
    );
  }

  /**
   * WIDGET SHELL HEADER — One Producer.
   * API: renderWgtHead(title, description, iconKey)
   * Definition chỉ lưu key ngữ nghĩa ("chart-line"); Design System map sang
   * implementation icon hiện tại. Không lưu class/SVG/HTML/URL vào Definition.
   *
   * HTML Contract (immutable DOM order — SoT):
   *   Icon → Identity (title + subtitle) → Actions
   * CẤM đổi thứ tự khi mở rộng / migrate Runtime Phase B.
   *
   * Phase A compatibility: consumer Runtime cũ truyền undefined hoặc class "ti ..."
   * vẫn nhận nguyên HTML legacy. Compatibility nằm trong implementation, không
   * thay đổi API và không được persist ngược class legacy vào Definition.
   */
  function normalizeIconKey(iconKey) {
    if (iconKey == null) return null;
    var raw = String(iconKey).trim();
    if (!raw) return null;
    if (/^ti\s/.test(raw)) {
      var parts = raw.split(/\s+/);
      for (var i = 0; i < parts.length; i++) {
        if (/^ti-[a-z0-9-]+$/.test(parts[i])) return parts[i].slice(3);
      }
      return null;
    }
    if (/^ti-[a-z0-9-]+$/.test(raw)) return raw.slice(3);
    return /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(raw) ? raw : null;
  }

  function renderWgtHead(title, description, iconKey) {
    var legacyInput = typeof iconKey === 'undefined' ||
      (typeof iconKey === 'string' && (/^ti\s/.test(iconKey.trim()) || /^ti-/.test(iconKey.trim())));
    if (legacyInput) {
      var legacyIcon = iconKey ? '<i class="' + esc(iconKey) + '"></i> ' : '';
      var legacyHtml = '<div class="ifx-widget__header"><h3>' + legacyIcon + esc(title || '') + '</h3>';
      if (description) legacyHtml += '<p class="ifx-widget__subtitle">' + esc(description) + '</p>';
      return legacyHtml + '</div>';
    }

    var key = normalizeIconKey(iconKey);
    var iconHtml = key
      ? '<span class="ifx-widget__icon" aria-hidden="true"><i class="ti ti-' + esc(key) + '"></i></span>'
      : '<span class="ifx-widget__icon" aria-hidden="true" hidden></span>';
    var identityHtml =
      '<div class="ifx-widget__identity">' +
        '<h3 class="ifx-widget__title">' + esc(title || '') + '</h3>' +
        (description ? '<p class="ifx-widget__subtitle">' + esc(description) + '</p>' : '') +
      '</div>';
    var actionsHtml =
      '<div class="ifx-widget__actions">' +
        '<span class="ifx-block-share-actions">' +
          '<button type="button" class="ifx-insight-share-btn" title="Chia sẻ Insight Widget" aria-label="Chia sẻ Insight Widget">' +
            '<i class="ti ti-share-3"></i>' +
          '</button>' +
        '</span>' +
      '</div>';
    return '<div class="ifx-widget__header">' + iconHtml + identityHtml + actionsHtml + '</div>';
  }

  /** Legacy sidebar shell — alias ifx-mkt-sidebar-widget */
  function renderSidebarShell(opts) {
    opts = opts || {};
    var title = opts.title || '';
    var head = title ? renderWgtHead(title, opts.desc || '', opts.icon) : '';
    var body = opts.body != null
      ? '<div class="ifx-mkt-sidebar-widget__body ifx-block__body">' + opts.body + '</div>'
      : '';
    var extra = opts.attrs ? ' ' + opts.attrs : '';
    var shellCls = 'ifx-block ifx-block--sidebar ifx-mkt-sidebar-widget';
    if (opts.shellClass) shellCls += ' ' + opts.shellClass;
    return (
      '<div class="' + shellCls + '"' + extra + '>' +
        head + body +
      '</div>'
    );
  }

  function exchangeTabsHtml(active, attrName, exchanges) {
    attrName = attrName || 'data-ifx-breadth-exchange';
    exchanges = exchanges && exchanges.length ? exchanges : BREADTH_EXCHANGES;
    return exchanges.map(function (ex) {
      return (
        '<button type="button" class="ix-segment' + (ex.key === active ? ' is-active' : '') +
        '" ' + attrName + '="' + esc(ex.key) + '">' + esc(ex.label) + '</button>'
      );
    }).join('');
  }

  function statCard(stat, value) {
    return (
      '<div class="ifx-breadth-stat ' + esc(stat.cls || '') + '">' +
        '<div class="ifx-breadth-stat__num">' + (value != null && value !== '' ? esc(value) : '—') + '</div>' +
        '<div class="ifx-breadth-stat__label">' + esc(stat.label) + '</div>' +
      '</div>'
    );
  }

  /**
   * TMP-BREADTH / TPL-BREADTH inner content (tabs + 6-stat grid + ratio).
   * opts: { exchange, data, stats?, exchanges?, ratioUpKey?, ratioDownKey? }
   */
  function renderBreadthContent(opts) {
    opts = opts || {};
    var exchange = opts.exchange || 'vnindex';
    var data = opts.data || {};
    var stats = opts.stats && opts.stats.length ? opts.stats : BREADTH_STATS;
    var exchanges = opts.exchanges && opts.exchanges.length ? opts.exchanges : BREADTH_EXCHANGES;
    var upKey = opts.ratioUpKey || 'up';
    var downKey = opts.ratioDownKey || 'down';
    var up = Number(data[upKey]) || 0;
    var down = Number(data[downKey]) || 0;
    var ratioTotal = up + down || 1;
    var upPct = Math.round((up / ratioTotal) * 100);

    return (
      '<div class="ix-segmented" data-ifx-breadth-exchange-tabs>' +
        exchangeTabsHtml(exchange, null, exchanges) +
      '</div>' +
      '<div class="ifx-breadth-visual ifx-breadth-visual--6">' +
        stats.map(function (stat) {
          return statCard(stat, data[stat.key]);
        }).join('') +
      '</div>' +
      '<div class="ifx-breadth-ratio" title="Tỷ lệ tăng ' + upPct + '%">' +
        '<div class="ifx-breadth-ratio__up" style="width:' + upPct + '%"></div>' +
        '<div class="ifx-breadth-ratio__down" style="width:' + (100 - upPct) + '%"></div>' +
      '</div>'
    );
  }

  /**
   * TMP-BREADTH / TPL-BREADTH — opts: { exchange, data, stats?, exchanges? }
   */
  function renderBreadth(opts) {
    opts = opts || {};
    var exchange = opts.exchange || 'vnindex';
    return (
      '<div class="ifx-breadth-block" data-ifx-breadth-block data-exchange="' + esc(exchange) + '">' +
        renderBreadthContent(opts) +
      '</div>'
    );
  }

  /**
   * TPL-TREEMAP tile link — opts: { name, perf, direction, href, tier }
   * direction: up | down | ref | ceiling | floor
   */
  function renderTreemapTile(opts) {
    opts = opts || {};
    var dir = opts.direction || 'ref';
    var cls = 'is-' + dir;
    var tier = opts.tier ? ' ifx-treemap-tile--' + opts.tier : '';
    var name = opts.name || '';
    var perf = opts.perf != null ? opts.perf : '';
    var href = opts.href || '#';
    var kind = opts.entityKind || 'stock';
    var inner = opts.tiny
      ? entityName(name, kind, { className: 'ifx-treemap-tile__name', tiny: true })
      : entityName(name, kind, { className: 'ifx-treemap-tile__name' }) +
        (perf !== '' ? '<span class="ifx-treemap-tile__perf">' + esc(perf) + '</span>' : '');

    return (
      '<div class="ifx-treemap-tile ifx-mkt-heat-tile' + tier + '">' +
        '<a class="ifx-treemap-tile__link ifx-mkt-heat-tile__link ' + cls + '" href="' + esc(href) + '">' +
          inner +
        '</a>' +
      '</div>'
    );
  }

  function perfDirection(p, thresholds) {
    thresholds = thresholds || { up: 0.08, down: -0.08 };
    if (p > thresholds.up) return 'up';
    if (p < thresholds.down) return 'down';
    return 'ref';
  }

  function perfValClass(p, thresholds) {
    thresholds = thresholds || { up: 0.05, down: -0.05 };
    if (p > thresholds.up) return 'is-up';
    if (p < thresholds.down) return 'is-down';
    return 'is-flat';
  }

  function fmtPct(n) {
    if (n == null || isNaN(n)) return '—';
    return (n >= 0 ? '+' : '') + Number(n).toFixed(2) + '%';
  }

  function fmtPct1(n) {
    var sign = n > 0 ? '+' : '';
    return sign + Number(n).toFixed(1);
  }

  function dirClass(n) {
    if (n == null || n === 0) return '';
    return n > 0 ? 'is-up' : 'is-down';
  }

  var CHART_SERIES_COUNT = 10;

  function chartSeriesIndex(i) {
    return (i % CHART_SERIES_COUNT) + 1;
  }

  function readToken(name) {
    if (typeof document === 'undefined' || !document.documentElement) return '';
    return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  }

  /** ApexCharts / SVG — đọc token runtime từ CSS */
  function chartColors() {
    return {
      accent: readToken('--ix-accent'),
      info: readToken('--ix-info'),
      success: readToken('--ix-success'),
      danger: readToken('--ix-danger'),
      warning: readToken('--ix-warning'),
      grid: readToken('--ifx-chart-grid'),
      label: readToken('--ifx-chart-label'),
      text: readToken('--ifx-chart-text'),
      textPrimary: readToken('--ix-text-primary'),
      flowIn: readToken('--ifx-flow-in'),
      flowOut: readToken('--ifx-flow-out'),
      markerStroke: readToken('--ifx-chart-marker-stroke'),
      annotationBg: readToken('--ifx-chart-annotation-bg'),
      border: readToken('--ix-border')
    };
  }

  function marketDirColor(state) {
    var map = {
      up: '--ifx-market-up',
      down: '--ifx-market-down',
      ref: '--ifx-market-ref',
      ceiling: '--ifx-market-ceiling',
      floor: '--ifx-market-floor'
    };
    return readToken(map[state] || map.ref);
  }

  var RANGE_TABS = [
    { days: 7, label: '1 tuần' },
    { days: 30, label: '1 tháng' },
    { days: 90, label: '3 tháng' },
    { days: 180, label: '6 tháng' }
  ];

  var FLOW_SUBJECT_TABS = [
    { key: 'retail', label: 'Cá nhân' },
    { key: 'institutional', label: 'Tổ chức' },
    { key: 'proprietary', label: 'Tự doanh' },
    { key: 'foreign', label: 'Khối ngoại' }
  ];

  function rangeTabsHtml(activeDays, attr) {
    attr = attr || 'data-days';
    return RANGE_TABS.map(function (r) {
      return (
        '<button type="button" class="ix-tab' + (activeDays === r.days ? ' active' : '') +
        '" ' + attr + '="' + r.days + '">' + esc(r.label) + '</button>'
      );
    }).join('');
  }

  /**
   * TPL-RANK-BAR — opts: { items: [{ name, perf }], emptyMsg }
   */
  function renderRankBarList(opts) {
    opts = opts || {};
    var items = opts.items || [];
    if (!items.length) {
      return '<div class="ifx-mkt-empty">' + esc(opts.emptyMsg || 'Chưa có dữ liệu') + '</div>';
    }

    var maxAbs = 0;
    items.forEach(function (it) {
      maxAbs = Math.max(maxAbs, Math.abs(it.perf || 0));
    });
    if (maxAbs < 0.01) maxAbs = 1;

    var rows = items.map(function (it, idx) {
      var pct = Math.min(100, Math.round((Math.abs(it.perf || 0) / maxAbs) * 100));
      var cls = perfValClass(it.perf, { up: 0.08, down: -0.08 });
      return (
        '<div class="ifx-rank-bar__row ifx-mkt-rank-row">' +
          '<span class="ifx-rank-bar__idx ifx-mkt-rank-idx">' + (idx + 1) + '</span>' +
          entityName(it.name, it.entityKind || opts.entityKind || 'stock', {
            className: 'ifx-rank-bar__name ifx-mkt-rank-name'
          }) +
          '<div class="ifx-rank-bar__track ifx-mkt-rank-bar-track">' +
            '<div class="ifx-rank-bar__fill ifx-mkt-rank-bar ' + cls + '" style="width:' + pct + '%"></div>' +
          '</div>' +
          '<span class="ifx-rank-bar__val ifx-mkt-rank-val ' + cls + '">' + fmtPct(it.perf) + '</span>' +
        '</div>'
      );
    }).join('');

    return (
      '<div class="ifx-rank-bar">' +
        '<div class="ifx-rank-bar__head ifx-mkt-rank-head">' +
          '<span>#</span><span>' + esc(opts.headLabel || 'Đối tượng') + '</span><span>' + esc(opts.headValue || 'Hiệu suất (%)') + '</span>' +
        '</div>' +
        '<div class="ifx-rank-bar__list ifx-mkt-rank-list">' + rows + '</div>' +
      '</div>'
    );
  }

  /* ── TPL-DIVERGING-BARS / TMP-DIVERGING-BARS ─────────────────────────────
   * Cột hai chiều quanh trục 0 (dương lên / âm xuống) + tabs nhóm + chú thích.
   * HTML producer duy nhất — CSS owner: block-templates.css (.ifx-stock-flow-*).
   * Scale/ticks trục tung SUY RA từ dữ liệu (derived), không truyền vào.
   */
  function divergingNiceCeil(v) {
    v = Math.max(v, 1);
    if (v <= 10) return 10;
    if (v <= 20) return 20;
    if (v <= 25) return 25;
    if (v <= 50) return 50;
    if (v <= 75) return 75;
    if (v <= 100) return 100;
    if (v <= 150) return 150;
    if (v <= 200) return 200;
    var pow = Math.pow(10, Math.floor(Math.log10(v)));
    var n = v / pow;
    if (n <= 1) return pow;
    if (n <= 2) return 2 * pow;
    if (n <= 5) return 5 * pow;
    return 10 * pow;
  }

  function divergingScale(points) {
    var maxPos = 0;
    var maxNeg = 0;
    (points || []).forEach(function (pt) {
      var v = Number(pt && pt.value) || 0;
      if (v > 0) maxPos = Math.max(maxPos, v);
      if (v < 0) maxNeg = Math.max(maxNeg, Math.abs(v));
    });
    var half = divergingNiceCeil(Math.max(maxPos, maxNeg, 1) * 1.1);
    return { max: half, ticks: [half, half / 2, 0, -half / 2, -half] };
  }

  function defaultAxisFmt(v) {
    return v === 0 ? '0' : String(v);
  }

  /**
   * Plot (trục tung + cột + trục hoành) — dùng khi đổi tab chỉ vẽ lại phần plot.
   * opts: { points: [{ value, label, title? }], formatAxis? }
   */
  function renderDivergingBarsPlot(opts) {
    opts = opts || {};
    var points = opts.points || [];
    if (!points.length) {
      return '<div class="ifx-stock-empty">Chưa có dữ liệu</div>';
    }
    var fmtAxis = opts.formatAxis || defaultAxisFmt;
    var scale = divergingScale(points);
    var max = scale.max || 1;
    var bars = points.map(function (pt) {
      var val = Number(pt.value) || 0;
      var pct = Math.min(100, (Math.abs(val) / max) * 100);
      var pos = val >= 0;
      return (
        '<div class="ifx-stock-flow-chart__col" title="' + esc(pt.title || pt.label || '') + '">' +
          '<div class="ifx-stock-flow-chart__half is-top">' +
            (pos ? '<div class="ifx-stock-flow-chart__bar is-pos" style="height:' + pct.toFixed(1) + '%"></div>' : '') +
          '</div>' +
          '<div class="ifx-stock-flow-chart__half is-bottom">' +
            (!pos ? '<div class="ifx-stock-flow-chart__bar is-neg" style="height:' + pct.toFixed(1) + '%"></div>' : '') +
          '</div>' +
        '</div>'
      );
    }).join('');
    var labels = points.map(function (pt) {
      return '<span>' + esc(pt.label || '') + '</span>';
    }).join('');
    var yticks = scale.ticks.map(function (tick) {
      var pct = ((max - tick) / (max * 2)) * 100;
      return '<span class="ifx-stock-flow-chart__ytick" style="top:' + pct.toFixed(2) + '%">' + esc(fmtAxis(tick)) + '</span>';
    }).join('');
    return (
      '<div class="ifx-stock-flow-chart__inner">' +
        '<div class="ifx-stock-flow-chart__yaxis">' + yticks + '</div>' +
        '<div class="ifx-stock-flow-chart__plot">' +
          '<div class="ifx-stock-flow-chart__bars-wrap">' +
            '<div class="ifx-stock-flow-chart__zero" aria-hidden="true"></div>' +
            '<div class="ifx-stock-flow-chart__bars">' + bars + '</div>' +
          '</div>' +
          '<div class="ifx-stock-flow-chart__xlabels">' + labels + '</div>' +
        '</div>' +
      '</div>'
    );
  }

  /**
   * Block đầy đủ: tabs nhóm + dòng chú thích + plot.
   * opts: { tabs: [{ key, label }], activeKey, hint, points, formatAxis?, tabAttr? }
   */
  function renderDivergingBars(opts) {
    opts = opts || {};
    var tabs = opts.tabs || [];
    var tabAttr = opts.tabAttr || 'data-ifx-flow-subject';
    var tabsHtml = tabs.map(function (t) {
      var on = t.key === opts.activeKey;
      return '<button type="button" class="ix-segment' + (on ? ' is-active' : '') +
        '" role="tab" aria-selected="' + (on ? 'true' : 'false') + '" ' + tabAttr + '="' + esc(t.key) + '">' +
        esc(t.label) + '</button>';
    }).join('');
    return (
      '<div class="ifx-stock-flow-chart" data-ifx-stock-flow-chart>' +
        (tabsHtml ? '<div class="ix-segmented" role="tablist">' + tabsHtml + '</div>' : '') +
        (opts.hint ? '<p class="ifx-stock-flow-hint">' + esc(opts.hint) + '</p>' : '') +
        '<div data-ifx-stock-flow-plot>' + renderDivergingBarsPlot(opts) + '</div>' +
      '</div>'
    );
  }

  /**
   * Format % có dấu cho thanh vị trí — giá trị đã tính sẵn từ Widget/Core.
   * Nhận "-16", "16", "+3", "3%" → chuỗi plain text có dấu + "%".
   */
  function fmtSignedPct(raw) {
    var s = String(raw == null ? '' : raw).trim();
    if (!s) return '—';
    var cleaned = s.replace(/%\s*$/, '').trim();
    var n = parseFloat(cleaned.replace(/[^0-9.\-+]/g, ''));
    if (isNaN(n)) return s;
    var sign = n > 0 ? '+' : (n < 0 ? '−' : '');
    var abs = Math.abs(n);
    var body = abs % 1 === 0 ? String(abs) : abs.toFixed(1).replace(/\.0$/, '');
    return sign + body + '%';
  }

  /**
   * TPL-SR-HISTORY / TMP-SR-HISTORY — Lịch sử Hỗ trợ | Kháng cự.
   * opts: {
   *   tabs: string[],
   *   activeIndex?: number,
   *   leftRange, rightRange, center, leftPct, rightPct,
   *   leftLabel?, centerLabel?, rightLabel?,
   *   emptyMsg?
   * }
   * Tab = ix-segmented (DS). Thanh / nhãn chỉ token DS trong block-templates.css.
   */
  function renderSrHistory(opts) {
    opts = opts || {};
    var tabs = opts.tabs || [];
    var active = Math.max(0, Math.min(tabs.length ? tabs.length - 1 : 0, Number(opts.activeIndex) || 0));
    var leftAbs = Math.abs(parseFloat(String(opts.leftPct == null ? '' : opts.leftPct).replace(/[^0-9.\-]/g, '')) || 0);
    var rightAbs = Math.abs(parseFloat(String(opts.rightPct == null ? '' : opts.rightPct).replace(/[^0-9.\-]/g, '')) || 0);
    var total = leftAbs + rightAbs;
    var leftW = total > 0 ? (leftAbs / total) * 100 : 50;
    var rightW = 100 - leftW;
    var leftLabel = opts.leftLabel != null ? opts.leftLabel : 'Hỗ trợ';
    var centerLabel = opts.centerLabel != null ? opts.centerLabel : 'Hiện tại';
    var rightLabel = opts.rightLabel != null ? opts.rightLabel : 'Kháng cự';
    var leftPctTxt = fmtSignedPct(opts.leftPct);
    var rightPctTxt = fmtSignedPct(opts.rightPct);
    var leftHint = leftPctTxt !== '—' ? ('Còn ' + leftPctTxt + ' nữa') : '';
    var rightHint = rightPctTxt !== '—' ? ('còn ' + rightPctTxt + ' nữa') : '';

    if (!tabs.length && !opts.center && !opts.leftRange && !opts.rightRange) {
      return '<div class="ifx-mkt-empty">' + esc(opts.emptyMsg || 'Chưa có dữ liệu') + '</div>';
    }

    var tabHtml = '';
    if (tabs.length) {
      tabHtml =
        '<div class="ix-segmented ifx-sr-hist__tabs" role="tablist" aria-label="Khung thời gian">' +
          tabs.map(function (lb, i) {
            return (
              '<button type="button" class="ix-segment' + (i === active ? ' is-active' : '') +
                '" role="tab" aria-selected="' + (i === active ? 'true' : 'false') +
                '" data-ifx-sr-hist-tab="' + i + '">' + esc(lb) + '</button>'
            );
          }).join('') +
        '</div>';
    }

    return (
      '<div class="ifx-sr-hist">' +
        tabHtml +
        '<div class="ifx-sr-hist__panel" data-ifx-sr-hist-panel>' +
          '<div class="ifx-sr-hist__labels">' +
            '<span class="ifx-sr-hist__label is-left">' + esc(leftLabel) + '</span>' +
            '<span class="ifx-sr-hist__label is-center">' + esc(centerLabel) + '</span>' +
            '<span class="ifx-sr-hist__label is-right">' + esc(rightLabel) + '</span>' +
          '</div>' +
          '<div class="ifx-sr-hist__bar" role="img" aria-label="' +
            esc(leftLabel + ' · ' + (opts.center || '') + ' · ' + rightLabel) +
          '">' +
            '<div class="ifx-sr-hist__seg is-left" style="width:' + leftW.toFixed(1) + '%"></div>' +
            '<span class="ifx-sr-hist__dot" aria-hidden="true"></span>' +
            '<div class="ifx-sr-hist__seg is-right" style="width:' + rightW.toFixed(1) + '%"></div>' +
          '</div>' +
          '<div class="ifx-sr-hist__values">' +
            '<span class="ifx-sr-hist__range is-left">' + esc(opts.leftRange || '—') + '</span>' +
            '<span class="ifx-sr-hist__price">' + esc(opts.center || '—') + '</span>' +
            '<span class="ifx-sr-hist__range is-right">' + esc(opts.rightRange || '—') + '</span>' +
          '</div>' +
          '<div class="ifx-sr-hist__hints">' +
            '<span class="ifx-sr-hist__hint is-left">' + esc(leftHint) + '</span>' +
            '<span class="ifx-sr-hist__hint is-right">' + esc(rightHint) + '</span>' +
          '</div>' +
        '</div>' +
      '</div>'
    );
  }

  /**
   * TPL-ZONE-POSITION / TMP-ZONE-POSITION — 1 dòng giai đoạn.
   * opts: { period, leftRange, rightRange, center, leftPct, rightPct,
   *         leftLabel?, rightLabel? }
   * Thanh trực quan: tỉ lệ trái/phải SUY RA từ |leftPct| : |rightPct|.
   * Không tính nghiệp vụ — chỉ trình bày.
   */
  function renderZonePositionRow(opts) {
    opts = opts || {};
    var leftAbs = Math.abs(parseFloat(String(opts.leftPct == null ? '' : opts.leftPct).replace(/[^0-9.\-]/g, '')) || 0);
    var rightAbs = Math.abs(parseFloat(String(opts.rightPct == null ? '' : opts.rightPct).replace(/[^0-9.\-]/g, '')) || 0);
    var total = leftAbs + rightAbs;
    var leftW = total > 0 ? (leftAbs / total) * 100 : 50;
    var rightW = 100 - leftW;
    var leftPctTxt = fmtSignedPct(opts.leftPct);
    var rightPctTxt = fmtSignedPct(opts.rightPct);
    var leftLabel = opts.leftLabel != null ? opts.leftLabel : 'Hỗ trợ';
    var rightLabel = opts.rightLabel != null ? opts.rightLabel : 'Kháng cự';

    return (
      '<div class="ifx-zone-pos__row">' +
        '<div class="ifx-zone-pos__period">' + esc(opts.period || '—') + '</div>' +
        '<div class="ifx-zone-pos__track-row">' +
          '<span class="ifx-zone-pos__side-label is-left">' + esc(leftLabel) + '</span>' +
          '<div class="ifx-zone-pos__bar" role="img" aria-label="' +
            esc(leftLabel + ' ' + leftPctTxt + ' · ' + (opts.center || '') + ' · ' + rightLabel + ' ' + rightPctTxt) +
          '">' +
            '<div class="ifx-zone-pos__seg is-left" style="width:' + leftW.toFixed(1) + '%">' +
              '<span class="ifx-zone-pos__pct">' + esc(leftPctTxt) + '</span>' +
            '</div>' +
            '<span class="ifx-zone-pos__marker" aria-hidden="true"></span>' +
            '<div class="ifx-zone-pos__seg is-right" style="width:' + rightW.toFixed(1) + '%">' +
              '<span class="ifx-zone-pos__pct">' + esc(rightPctTxt) + '</span>' +
            '</div>' +
          '</div>' +
          '<span class="ifx-zone-pos__side-label is-right">' + esc(rightLabel) + '</span>' +
        '</div>' +
        '<div class="ifx-zone-pos__values">' +
          '<span class="ifx-zone-pos__range is-left">' + esc(opts.leftRange || '—') + '</span>' +
          '<span class="ifx-zone-pos__center">' + esc(opts.center || '—') + '</span>' +
          '<span class="ifx-zone-pos__range is-right">' + esc(opts.rightRange || '—') + '</span>' +
        '</div>' +
      '</div>'
    );
  }

  /**
   * TPL-ZONE-POSITION — danh sách dòng giai đoạn.
   * opts: { rows: [{ period, leftRange, rightRange, center, leftPct, rightPct }],
   *         leftLabel?, rightLabel?, emptyMsg? }
   */
  function renderZonePosition(opts) {
    opts = opts || {};
    var rows = opts.rows || [];
    if (!rows.length) {
      return '<div class="ifx-mkt-empty">' + esc(opts.emptyMsg || 'Chưa có dữ liệu') + '</div>';
    }
    return (
      '<div class="ifx-zone-pos">' +
        rows.map(function (row) {
          return renderZonePositionRow({
            period: row.period,
            leftRange: row.leftRange,
            rightRange: row.rightRange,
            center: row.center,
            leftPct: row.leftPct,
            rightPct: row.rightPct,
            leftLabel: opts.leftLabel,
            rightLabel: opts.rightLabel
          });
        }).join('') +
      '</div>'
    );
  }

  function renderFlowSplitTicker(item, side) {
    var cls = 'ifx-flow-split__ticker ifx-flow-split__ticker--' + side;
    if (!item) {
      return '<span class="' + cls + ' ifx-flow-split__ticker--empty">—</span>';
    }
    return (
      '<a class="' + cls + '" href="' + esc(item.href || '#') + '" title="' + esc(item.label) + '">' +
        esc(item.label) +
      '</a>'
    );
  }

  function renderFlowSplitRow(buy, sell) {
    var buyHtml = buy
      ? '<div class="ifx-flow-split__buy">' +
          '<div class="ifx-flow-split__bar ifx-flow-split__bar--buy" style="width:' + buy.pct + '%">' +
            '<span class="ifx-flow-split__val">' + esc(buy.value_label) + '</span>' +
          '</div></div>'
      : '<div class="ifx-flow-split__buy ifx-flow-split__buy--empty"></div>';

    var sellHtml = sell
      ? '<div class="ifx-flow-split__sell">' +
          '<div class="ifx-flow-split__bar ifx-flow-split__bar--sell" style="width:' + sell.pct + '%">' +
            '<span class="ifx-flow-split__val">' + esc(sell.value_label) + '</span>' +
          '</div></div>'
      : '<div class="ifx-flow-split__sell ifx-flow-split__sell--empty"></div>';

    return (
      '<div class="ifx-flow-split__row">' +
        buyHtml +
        renderFlowSplitTicker(buy, 'buy') +
        renderFlowSplitTicker(sell, 'sell') +
        sellHtml +
      '</div>'
    );
  }

  function renderFlowSplitBody(data) {
    var html = '';
    var i;
    var rows = (data && data.rows) || 0;
    for (i = 0; i < rows; i++) {
      html += renderFlowSplitRow(
        data.buyers ? data.buyers[i] : null,
        data.sellers ? data.sellers[i] : null
      );
    }
    return html;
  }

  function renderFlowSubjectTabs(active) {
    return (
      '<div class="ifx-flow-toolbar ifx-flow-toolbar--subjects">' +
        '<div class="ix-segmented" data-ifx-flow-subject-tabs>' +
          FLOW_SUBJECT_TABS.map(function (t) {
            return (
              '<button type="button" class="ix-segment' + (t.key === active ? ' is-active' : '') +
              '" data-ifx-flow-subject="' + t.key + '">' + esc(t.label) + '</button>'
            );
          }).join('') +
        '</div></div>'
    );
  }

  /**
   * TPL-FLOW-SPLIT — opts: { scope meta fields, withHead, withSubjectTabs, subject, tickBuy, tickSell, bodyHtml }
   */
  function renderFlowSplitBlock(opts) {
    opts = opts || {};
    var headHtml = opts.withHead ? renderWgtHead(opts.title || '', opts.description) : '';
    var tabsHtml = opts.withSubjectTabs !== false
      ? renderFlowSubjectTabs(opts.subject || 'retail')
      : '';

    return (
      '<div class="ifx-flow-split-block">' +
        headHtml +
        tabsHtml +
        '<div class="ifx-flow-split" data-ifx-flow-split>' +
          '<div class="ifx-flow-split__head">' +
            '<div class="ifx-flow-split__col-h ifx-flow-split__col-h--buy">' +
              '<span class="ifx-flow-split__dot is-buy"></span> ' + esc(opts.headerBuy || 'Top KL mua ròng') + '</div>' +
            '<div class="ifx-flow-split__col-h ifx-flow-split__col-h--tick-buy">' + esc(opts.tickBuy || 'Mã mua') + '</div>' +
            '<div class="ifx-flow-split__col-h ifx-flow-split__col-h--tick-sell">' + esc(opts.tickSell || 'Mã bán') + '</div>' +
            '<div class="ifx-flow-split__col-h ifx-flow-split__col-h--sell">' +
              '<span class="ifx-flow-split__dot is-sell"></span> ' + esc(opts.headerSell || 'Top KL bán ròng') + '</div>' +
          '</div>' +
          '<div class="ifx-flow-split__body" data-ifx-flow-split-body>' +
            (opts.bodyHtml != null ? opts.bodyHtml : '') +
          '</div>' +
        '</div>' +
      '</div>'
    );
  }

  /**
   * TPL-INDEX-GRID — opts: { exchanges: [{ name, value, change_pct }] }
   */
  function renderIndexCard(ex) {
    return (
      '<div class="ifx-index-card ifx-com-ex-card">' +
        '<div class="ifx-index-card__name ifx-com-ex-card__name">' + esc(ex.name) + '</div>' +
        '<div class="ifx-index-card__val ifx-com-ex-card__val">' +
          (ex.value != null
            ? Number(ex.value).toLocaleString('vi-VN', { maximumFractionDigits: 2 })
            : '—') +
        '</div>' +
        '<div class="ifx-index-card__chg ifx-com-ex-card__chg ' + dirClass(ex.change_pct) + '">' +
          fmtPct(ex.change_pct) +
        '</div>' +
      '</div>'
    );
  }

  function renderIndexGrid(exchanges) {
    return (
      '<div class="ifx-index-grid ifx-com-ex-grid">' +
        (exchanges || []).map(renderIndexCard).join('') +
      '</div>'
    );
  }

  /**
   * TPL-INDEX-GRID + overview shell
   * opts: { title, icon, description, status, exchanges, includeBreadth, sidebar, marketSidebar, hideHead }
   */
  function renderOverviewShell(opts) {
    opts = opts || {};
    var cls = opts.sidebar !== false ? ' ifx-com-overview--sidebar' : '';
    if (opts.marketSidebar) cls += ' ifx-com-overview--market-sidebar';
    var showHead = opts.hideHead !== true;
    var iconClass = opts.icon || 'ti ti-chart-line';

    var overviewHead = '';
    if (showHead && opts.title) {
      overviewHead = renderWgtHead(opts.title, opts.description || '', iconClass);
      if (opts.status) {
        overviewHead = overviewHead.replace(
          '</div>',
          '<span class="ifx-com-overview__status">' + esc(opts.status) + '</span></div>'
        );
      }
    }

    return (
      '<section class="ifx-block ifx-com-overview' + cls + '">' +
        overviewHead +
        '<div class="ifx-com-overview__indices">' +
          renderIndexGrid(opts.exchanges) +
        '</div>' +
        (opts.includeBreadth !== false
          ? '<div class="ifx-com-overview__breadth">' +
              renderWgtHead('Độ rộng thị trường') +
              '<div data-ifx-com-breadth-mount></div>' +
            '</div>'
          : '') +
      '</section>'
    );
  }

  /**
   * TPL-LIST-ROW — opts: { href, hideVol, extraClass }
   */
  function renderStockRow(s, opts) {
    opts = opts || {};
    if (!s) return '';
    var href = opts.href || '#';
    var chg = s.change_pct;
    var cls = dirClass(chg);
    var extra = opts.extraClass ? ' ' + opts.extraClass : '';
    return (
      '<a class="ifx-list-row ifx-stock-row ' + cls + extra + '" href="' + esc(href) + '" data-ticker="' + esc(s.ticker) + '">' +
        entityName(s.ticker, 'stock', { className: 'ifx-stock-row__ticker' }) +
        entityName(s.name || '', 'stock', { className: 'ifx-stock-row__name' }) +
        '<span class="ifx-stock-row__price">' + (s.price != null ? esc(s.price) : '—') + '</span>' +
        '<span class="ifx-stock-row__chg">' + fmtPct(chg) + '</span>' +
        (opts.hideVol ? '' : '<span class="ifx-stock-row__vol">' + esc(s.volume || '—') + '</span>') +
      '</a>'
    );
  }

  /**
   * TPL-LIST-ROW wrap — opts: { href, actionsHtml, badgesHtml, folderId, ... }
   */
  function renderStockRowWrap(s, opts) {
    opts = opts || {};
    if (!s) return '';
    var chg = s.change_pct;
    var actions = opts.actionsHtml || '';
    var badges = opts.badgesHtml || '';
    return (
      '<div class="ifx-list-row-wrap ifx-stock-row-wrap ' + dirClass(chg) + '" data-ticker="' + esc(s.ticker) + '">' +
        renderStockRow(s, opts) +
        (actions ? '<div class="ifx-stock-row__actions">' + actions + '</div>' : '') +
        (badges ? '<div class="ifx-stock-row__badges-row" data-ifx-stock-badges>' + badges + '</div>' : '') +
      '</div>'
    );
  }

