    var faq = (raw.faq && raw.faq.length) ? raw.faq : legacyFaq;
    return {
      summary: raw.summary || (post && post.excerpt) || '',
      key_takeaways: normalizeList(raw.key_takeaways),
      faq: faq.map(function (f) {
