        slug: post.slug,
        variant: 'compact',
        bodyHtml: postCardInnerHtml(post, opts || {})
      });
    }
    return (
      '<article class="ifx-com-post ifx-com-post--compact" data-ifx-com-slug="' + post.slug + '">' +
        postCardInnerHtml(post, opts || {}) +
      '</article>'
    );
  }

  function setMeta(name, content, attr) {
    if (!content) return;
    attr = attr || 'name';
    var sel = 'meta[' + attr + '="' + name + '"]';
    var el = document.querySelector(sel);
    if (!el) {
      el = document.createElement('meta');
      el.setAttribute(attr, name);
      document.head.appendChild(el);
    }
    el.setAttribute('content', content);
  }

  function applySeoToDocument(post, basePath) {
    if (!post) return;
    basePath = basePath || '../community/';
    var seo = post.seo || {};
    var geo = post.geo || {};
    var pageUrl = location.href.split('#')[0];
    var canonical = seo.canonical_url ||
      (global.IfluxSeoUrl ? IfluxSeoUrl.postCanonical(post) : pageUrl);
    if (global.IfluxPageDefinition && IfluxPageDefinition.applyPatch) {
      IfluxPageDefinition.applyPatch({
        title: post.title,
        intro: post.excerpt || '',
        documentTitle: seo.meta_title || post.title,
        seo: {
          description: seo.meta_description || post.excerpt,
          robots: seo.robots || 'index,follow',
          keywords: [seo.focus_keyword].concat(seo.secondary_keywords || []).concat(geo.geo_keywords || []).filter(Boolean).join(', '),
          canonical: canonical,
          'geo.region': geo.country === 'VN' ? 'VN' : geo.country,
          'geo.placename': geo.region || 'Việt Nam',
          language: geo.language || 'vi-VN',
          'og:title': seo.og_title || post.title,
          'og:description': seo.og_description || post.excerpt,
          'og:type': 'article',
          'og:locale': geo.target_locale || 'vi_VN',
          'og:image': seo.og_image || null,
          'og:url': canonical,
          'twitter:card': 'summary_large_image',
          'twitter:title': seo.og_title || post.title,
          'twitter:description': seo.og_description || post.excerpt,
          'twitter:image': seo.og_image || null,
          jsonLd: [{ id: 'ifx-com-jsonld', data: store().buildJsonLd(post, canonical) }]
        }
      });
      return;
    }
    /* Phase B: không fallback ghi title/meta — Page Definition là SoT. */
  }

  function storyOptionsHtml() {
    var t = tax();
    if (!t) return '';
    var groups = t.getGroups('story');
    return groups.map(function (g) {
      return '<option value="' + g.id + '">' + g.name + '</option>';
    }).join('');
  }

  function seoHint(len, min, max) {
    var cls = 'ifx-com-hint';
    if (len < min || len > max) cls += ' is-warn';
    else cls += ' is-ok';
    return cls;
  }

  function currentUserId() {
    var u = auth() && auth().getUser();
    return u && u.id ? u.id : 'usr_local';
  }

  function shareUrl(slug) {
    var post = store().getPostBySlug(slug);
    if (global.IfluxSeoUrl) {
      if (post) return (location.origin || IfluxSeoUrl.PROD_ORIGIN) + IfluxSeoUrl.postSlugPath(post);
      return (location.origin || IfluxSeoUrl.PROD_ORIGIN) + '/cong-dong/bai-viet/' + encodeURIComponent(slug);
    }
    return (location.origin || '') + '/cong-dong/bai-viet/' + encodeURIComponent(slug);
  }

  function getPostStories(post) {
    var story = getPrimaryStory(post);
    return story ? [story] : [];
  }

  /* Link chủ đề: market story → /chu-de/:slug; nếu là chủ đề cộng đồng → trang topic */
  function storyEntityLink(sourceId) {
    var s = seo();
    if (s && s.chuDeHref) return s.chuDeHref(sourceId);
    if (s && s.storyHref) return s.storyHref(sourceId);
    return '/chu-de/' + encodeURIComponent(String(sourceId || ''));
  }

  /* Gom ngành / hệ sinh thái duy nhất mà các mã CP trong bài thuộc về */
  function aggregateMemberships(post, source) {
    var t = tax();
    if (!t || !t.getTickerMemberships) return [];
    var seen = {};
    var out = [];
    (post.tickers || []).forEach(function (tk) {
      var m = t.getTickerMemberships(tk);
      var g = m && m[source];
      if (g && g.id != null && !seen[g.id]) {
        seen[g.id] = true;
        out.push(g);
      }
    });
    return out;
  }

  function sideLinkRowHtml(href, icon, name, perf, extra) {
    var cls = 'ifx-com-side-row' + (dirClass(perf) ? ' ' + dirClass(perf) : '');
    return (
      '<a class="' + cls + '" href="' + href + '">' +
        '<span class="ifx-com-side-row__name"><i class="ti ' + icon + '"></i> ' + escHtml(name) + (extra || '') + '</span>' +
        '<span class="ifx-com-side-row__val">' + (perf != null ? fmtPct(perf) : '—') + '</span>' +
      '</a>'
    );
  }

  /* ── Chủ đề: liệt kê tất cả story_tags, bấm mở trang chủ đề ── */
  function sidebarStoryRowsHtml(post) {
    var stories = (post.story_tags || []).filter(function (t) {
      return t.source === 'chu-de' || t.source === 'story' || !t.source;
    });
    if (!stories.length) {
      return '<div class="ifx-com-side-empty">Bài chưa gắn chủ đề</div>';
    }
    return stories.map(function (story) {
      var perf = getGroupPerformance('story', story.sourceId);
      return sideLinkRowHtml(storyEntityLink(story.sourceId), 'ti-bookmark', story.name, perf);
    }).join('');
  }

  /* ── Ngành: suy ra từ các mã CP, bấm mở trang ngành ── */
  function sidebarSectorRowsHtml(post) {
    var groups = aggregateMemberships(post, 'sector');
    if (!groups.length) {
      return '<div class="ifx-com-side-empty">Bài chưa gắn ngành</div>';
    }
    return groups.map(function (g) {
      var perf = getGroupPerformance('sector', g.id);
      var href = seo() ? seo().sectorHref(g.id) : '/nganh/' + encodeURIComponent(g.id);
      return sideLinkRowHtml(href, 'ti-chart-dots-3', g.name, perf);
    }).join('');
  }

  /* ── Hệ sinh thái (họ CP): suy ra từ các mã CP, bấm mở trang hệ sinh thái ── */
  function sidebarEcosystemRowsHtml(post) {
    var groups = aggregateMemberships(post, 'family');
    if (!groups.length) {
      return '<div class="ifx-com-side-empty">Bài chưa gắn hệ sinh thái</div>';
    }
    return groups.map(function (g) {
      var perf = getGroupPerformance('family', g.id);
      var href = seo() ? seo().ecosystemHref(g.id) : '/he-sinh-thai/' + encodeURIComponent(g.id);
      return sideLinkRowHtml(href, 'ti-hierarchy-2', g.name, perf);
    }).join('');
  }

  /* ── Cổ phiếu: bấm mở trang cổ phiếu tương ứng ── */
  function sidebarTickerRowsHtml(post) {
    var tickers = post.tickers || [];
    if (!tickers.length) {
      return '<div class="ifx-com-side-empty">Chưa nhắc mã CP trong bài</div>';
    }
    return tickers.map(function (tk) {
      var q = getStockQuote(tk);
      var chg = q && q.change_pct;
      var cls = 'ifx-com-side-row' + (dirClass(chg) ? ' ' + dirClass(chg) : '');
      return (
        '<a class="' + cls + '" href="' + tickerArchiveUrl(tk) + '">' +
          '<span class="ifx-com-side-row__name"><strong>' + escHtml(tk) + '</strong>' +
            (q && q.name ? '<small>' + escHtml(q.name) + '</small>' : '') +
          '</span>' +
          '<span class="ifx-com-side-row__val">' +
            (q && q.price != null ? q.price + ' ' : '') +
            (chg != null ? fmtPct(chg) : '') +
          '</span>' +
        '</a>'
      );
    }).join('');
  }

  function sortComments(comments, mode) {
    var list = (comments || []).slice();
    if (mode === 'liked') {
      list.sort(function (a, b) {
        return (b.likes || 0) - (a.likes || 0) || new Date(b.created_at) - new Date(a.created_at);
      });
    } else if (mode === 'debate') {
      list.sort(function (a, b) {
        var sa = (a.replies || 0) * 3 + (a.likes || 0);
        var sb = (b.replies || 0) * 3 + (b.likes || 0);
        return sb - sa || new Date(b.created_at) - new Date(a.created_at);
      });
    } else if (mode === 'shared') {
      list.sort(function (a, b) {
        return (b.shares || 0) - (a.shares || 0) || new Date(b.created_at) - new Date(a.created_at);
      });
    } else {
      list.sort(function (a, b) {
        return new Date(b.created_at) - new Date(a.created_at);
      });
    }
    return list;
  }

  function commentItemHtml(c) {
    var nameHtml = global.IfluxProfileLinks && c.user_id
      ? IfluxProfileLinks.nameLink(c.user_id, c.user_name, 'ifx-com-comment__author', { base: '../account/' })
      : '<strong>' + String(c.user_name).replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</strong>';
    return (
      '<div class="ifx-com-comment" data-ifx-com-comment-id="' + c.id + '">' +
        '<div class="ifx-com-comment__head">' +
          nameHtml +
          '<span>' + fmtRelative(c.created_at) + '</span>' +
        '</div>' +
        '<p>' + String(c.body).replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</p>' +
        '<div class="ifx-com-comment__stats">' +
          '<span><i class="ti ti-heart"></i> ' + (c.likes || 0) + '</span>' +
          '<span><i class="ti ti-message"></i> ' + (c.replies || 0) + '</span>' +
          '<span><i class="ti ti-share"></i> ' + (c.shares || 0) + '</span>' +
        '</div>' +
      '</div>'
    );
  }

  function applyStorySeoExtras(post) {
    applySeoToDocument(post);
    var canonical = (post.seo && post.seo.canonical_url) ||
      (global.IfluxSeoUrl ? IfluxSeoUrl.storyCanonical(post) : location.href.split('#')[0]);
    var communityUrl = global.IfluxSeoUrl
      ? IfluxSeoUrl.PROD_ORIGIN + '/cong-dong'
      : location.href.split('#')[0].replace(/story\.html.*/, 'index.html');
    var breadcrumb = {
      '@context': 'https://schema.org',
      '@type': 'BreadcrumbList',
      itemListElement: [
        { '@type': 'ListItem', position: 1, name: 'Cộng đồng', item: communityUrl },
        { '@type': 'ListItem', position: 2, name: (post.tickers && post.tickers[0]) || 'Thị trường',
          item: global.IfluxSeoUrl ? IfluxSeoUrl.stockCanonical((post.tickers && post.tickers[0]) || '') : '' },
        { '@type': 'ListItem', position: 3, name: post.title, item: canonical }
      ]
    };
    var scriptId = 'ifx-com-breadcrumb-ld';
    var old = document.getElementById(scriptId);
    if (old) old.remove();
    var script = document.createElement('script');
    script.id = scriptId;
    script.type = 'application/ld+json';
    script.textContent = JSON.stringify(breadcrumb);
    document.head.appendChild(script);

    if (global.IfluxCommunityGeoAi) {
      var g = IfluxCommunityGeoAi.normalizeGeoAi(post);
      if (g.summary) setMeta('abstract', g.summary);
      var geoLdId = 'ifx-com-geo-ai-ld';
      var oldGeo = document.getElementById(geoLdId);
      if (oldGeo) oldGeo.remove();
      var geoScript = document.createElement('script');
      geoScript.id = geoLdId;
      geoScript.type = 'application/ld+json';
      geoScript.textContent = JSON.stringify(
        IfluxCommunityGeoAi.buildJsonLdBlocks(post, canonical),
        null,
        2
      );
      document.head.appendChild(geoScript);
    }
  }

  function articleHeroImageHtml(post) {
    var seo = post.seo || {};
    if (!seo.og_image) return '';
    return (
      '<figure class="ifx-com-article__figure" itemprop="image" itemscope itemtype="https://schema.org/ImageObject">' +
        '<img src="' + seo.og_image + '" alt="' + (seo.og_image_alt || post.title) + '" itemprop="url" loading="eager" />' +
        (seo.og_image_alt ? '<figcaption itemprop="caption">' + seo.og_image_alt + '</figcaption>' : '') +
      '</figure>'
    );
  }

  function articleGeoFooterHtml(post) {
    var geo = post.geo || {};
    var seo = post.seo || {};
    var parts = [];
    if (geo.language) parts.push('Ngôn ngữ: ' + geo.language);
    if (geo.region || geo.country) parts.push('Khu vực: ' + (geo.region || geo.country));
    if (seo.focus_keyword) parts.push('Từ khóa: ' + seo.focus_keyword);
    if (!parts.length) return '';
    return (
      '<footer class="ifx-com-article__geo">' +
        '<span class="ifx-com-article__geo-label"><i class="ti ti-map-pin"></i> GEO / SEO</span>' +
        '<p>' + parts.join(' · ') + '</p>' +
      '</footer>'
    );
  }

  global.IfluxCommunityUI = {
    fmtDate: fmtDate,
    fmtRelative: fmtRelative,
    fmtPct: fmtPct,
    postCardHtml: postCardHtml,
    featuredPostHtml: featuredPostHtml,
    compactPostHtml: compactPostHtml,
    postTagsHtml: postTagsHtml,
    getPrimaryStory: getPrimaryStory,
    tickerArchiveUrl: tickerArchiveUrl,
    getGroupPerformance: getGroupPerformance,
    getPostStories: getPostStories,
    sidebarStoryRowsHtml: sidebarStoryRowsHtml,
    sidebarSectorRowsHtml: sidebarSectorRowsHtml,
    sidebarEcosystemRowsHtml: sidebarEcosystemRowsHtml,
    sidebarTickerRowsHtml: sidebarTickerRowsHtml,
    sortComments: sortComments,
    commentItemHtml: commentItemHtml,
    applySeoToDocument: applySeoToDocument,
    applyStorySeoExtras: applyStorySeoExtras,
    articleHeroImageHtml: articleHeroImageHtml,
    articleGeoFooterHtml: articleGeoFooterHtml,
    storyOptionsHtml: storyOptionsHtml,
    seoHint: seoHint,
    currentUserId: currentUserId,
    shareUrl: shareUrl,
    tierBadge: tierBadge
  };
})(window);

/* Cộng đồng — feed, bài viết, form SEO/GEO */

.ifx-com-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--ifx-space-12);
  margin-bottom: var(--ifx-space-12);
}
.ifx-com-toolbar__left {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--ifx-inline-md);
  flex: 1;
  min-width: 0;
}
.ifx-com-search {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
  flex: 1;
  min-width: 180px;
  max-width: 360px;
}
.ifx-com-search i { color: var(--ix-text-muted); font-size: var(--ifx-font-size-16); }
.ifx-com-search .ix-input { flex: 1; }

.ifx-com-intro {
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-muted);
  margin: 0 0 20px;
  line-height: 1.55;
}

.ifx-com-feed {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-space-16);
}

.ifx-com-card {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: var(--ifx-space-16) 18px;
  transition: border-color 0.12s, box-shadow 0.12s;
}
.ifx-com-card:hover {
  border-color: rgba(105, 108, 255, 0.35);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.12);
}

.ifx-com-card__head { margin-bottom: 10px; }
.ifx-com-card__author {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-md);
}
.ifx-com-card__avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--ix-accent-soft);
  color: var(--ix-accent);
  font-weight: var(--ifx-font-weight-bold);
  font-size: var(--ifx-font-size-14);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.ifx-com-card__author-name {
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-semibold);
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-sm);
  flex-wrap: wrap;
}
.ifx-com-card__meta { font-size: var(--ifx-font-size-12); color: var(--ix-text-muted); margin-top: 2px; }

.ifx-com-card__title {
  display: block;
  font-size: var(--ifx-font-size-18);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-primary);
  text-decoration: none;
  margin-bottom: var(--ifx-space-8);
  line-height: 1.35;
}
.ifx-com-card__title:hover { color: var(--ix-accent); }

.ifx-com-card__excerpt {
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-secondary);
  line-height: 1.55;
  margin: 0 0 12px;
}

.ifx-com-card__tags,
.ifx-com-article__tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ifx-inline-sm);
  margin-bottom: 10px;
}

.ifx-com-card__foot {
  display: flex;
  gap: var(--ifx-space-16);
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
  padding-top: 10px;
  border-top: 1px solid var(--ix-border);
}
.ifx-com-card__foot i { margin-right: 4px; vertical-align: -1px; }

.ifx-com-empty {
  text-align: center;
  padding: 48px 20px;
  color: var(--ix-text-muted);
  font-size: var(--ifx-font-size-14);
}
.ifx-com-empty p { margin: 12px 0 16px; }

.ifx-com-write-lock {
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
  display: inline-flex;
  align-items: center;
  gap: var(--ifx-space-4);
}

.ifx-com-breadcrumb {
  margin-bottom: var(--ifx-space-16);
  font-size: var(--ifx-font-size-14);
}
.ifx-com-breadcrumb a {
  color: var(--ix-text-muted);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: var(--ifx-inline-sm);
}
.ifx-com-breadcrumb a:hover { color: var(--ix-accent); }

.ifx-com-clear {
  margin-left: 4px;
  color: inherit;
  text-decoration: none;
  font-weight: var(--ifx-font-weight-bold);
}

/* Article detail — SEO/GEO layout + sidebar */
.ifx-main.ifx-main--article {
  max-width: 1200px;
}

.ifx-com-breadcrumb__sep {
  margin: 0 8px;
  color: var(--ix-text-muted);
  opacity: 0.5;
}
.ifx-com-breadcrumb__current {
  color: var(--ix-text-muted);
  font-size: var(--ifx-font-size-14);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: min(480px, 50vw);
  display: inline-block;
  vertical-align: bottom;
}

.ifx-com-story-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: var(--ifx-space-24);
  align-items: start;
}
.ifx-com-story-main { min-width: 0; }

.ifx-com-article {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: 0;
  margin-bottom: 0;
  overflow: hidden;
}
.ifx-com-article__header {
  padding: 28px 32px 0;
}
.ifx-com-article__kicker {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ix-accent);
  margin: 0 0 10px;
}
.ifx-com-article__title {
  font-size: var(--ifx-font-size-32);
  font-weight: 800;
  line-height: 1.25;
  margin: 0 0 14px;
  color: var(--ix-text-primary);
  letter-spacing: -0.02em;
}
.ifx-com-article__lead {
  font-size: var(--ifx-font-size-18);
  line-height: 1.65;
  color: var(--ix-text-secondary);
  margin: 0 0 20px;
  font-weight: var(--ifx-font-weight-regular);
}
.ifx-com-article__figure {
  margin: 0 0 20px;
  border-radius: var(--ix-radius-lg);
  overflow: hidden;
  border: 1px solid var(--ix-border);
}
.ifx-com-article__figure img {
  width: 100%;
  display: block;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}
.ifx-com-article__figure figcaption {
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
  padding: var(--ifx-space-8) 12px;
  background: var(--ix-bg-body);
}
.ifx-com-article__byline {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--ifx-space-12);
  flex-wrap: wrap;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--ix-border);
  margin-bottom: 14px;
}
.ifx-com-article__author {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-md);
}
.ifx-com-article__dates {
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
  margin-top: var(--ifx-space-4);
}
.ifx-com-article__dates time { display: inline; }
.ifx-com-article__tags {
  margin-bottom: 14px;
}
.ifx-com-article__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ifx-space-8);
  margin-bottom: 0;
  padding-bottom: 20px;
  border-bottom: none;
}
.ifx-com-article__body {
  font-size: var(--ifx-font-size-16);
  line-height: 1.8;
  color: var(--ix-text-primary);
  padding: var(--ifx-space-container) 32px 32px;
  max-width: 72ch;
}
.ifx-com-article__body h2 {
  font-size: var(--ifx-font-size-20);
  font-weight: var(--ifx-font-weight-bold);
  margin: 28px 0 12px;
  color: var(--ix-text-primary);
  scroll-margin-top: calc(var(--ifx-topnav-h, 56px) + 20px);
}
.ifx-com-article__body h3 {
  font-size: var(--ifx-font-size-18);
  font-weight: var(--ifx-font-weight-semibold);
  margin: 20px 0 10px;
}
.ifx-com-article__body p { margin: 0 0 16px; }
.ifx-ticker-link {
  color: var(--ix-accent);
  font-weight: var(--ifx-font-weight-semibold);
  text-decoration: none;
  border-bottom: 1px dashed rgba(105, 108, 255, 0.45);
}
.ifx-ticker-link:hover { color: var(--ix-primary); border-bottom-color: currentColor; }
.ifx-com-article__body ul,
.ifx-com-article__body ol {
  margin: 0 0 16px 20px;
}
.ifx-com-article__geo {
  margin: 0;
  padding: var(--ifx-space-16) 32px 24px;
  border-top: 1px solid var(--ix-border);
  background: var(--ix-bg-body);
}
.ifx-com-article__geo-label {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-sm);
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ix-text-muted);
  margin-bottom: 6px;
}
.ifx-com-article__geo p {
  margin: 0;
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-secondary);
  line-height: 1.5;
}
.ifx-com-article .ifx-com-faq {
  margin: 0;
  padding: var(--ifx-space-container) 32px 32px;
  border-top: 1px solid var(--ix-border);
}

/* Sidebar cột phải bài viết */
.ifx-com-story-aside {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-space-16);
  min-width: 0;
}
.ifx-com-side-card--toc {
  max-height: min(320px, calc(100vh - var(--ifx-topnav-h, 56px) - 280px));
  display: flex;
  flex-direction: column;
}
.ifx-com-toc {
  overflow-y: auto;
  flex: 1;
  min-height: 0;
  margin: 0 -4px;
  padding: 0 4px;
}
.ifx-com-toc__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ifx-com-toc__link {
  display: block;
  font-size: var(--ifx-font-size-14);
  line-height: 1.45;
  color: var(--ix-text-secondary);
  text-decoration: none;
  padding: var(--ifx-space-8) 10px;
  border-radius: var(--ix-radius);
  border-left: 2px solid transparent;
  transition: background 0.12s, color 0.12s, border-color 0.12s;
}
.ifx-com-toc__link:hover {
  background: var(--ix-bg-hover);
  color: var(--ix-accent);
}
.ifx-com-side-card {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: var(--ifx-space-16);
}
.ifx-com-side-card__title {
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-bold);
  margin: 0 0 4px;
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-sm);
}
.ifx-com-side-card__sub {
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  margin: 0 0 12px;
}
.ifx-com-side-count {
  font-size: var(--ifx-font-size-10);
  background: var(--ix-bg-hover);
  padding: 1px 7px;
  border-radius: 10px;
  color: var(--ix-text-muted);
  font-weight: var(--ifx-font-weight-semibold);
}
.ix-tab.active .ifx-com-side-count {
  background: var(--ix-accent);
  color: #fff;
}
.ifx-com-side-list {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-inline-sm);
}
.ifx-com-side-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ifx-inline-md);
  padding: 10px 12px;
  border-radius: var(--ix-radius);
  border: 1px solid var(--ix-border);
  background: var(--ix-bg-body);
  text-decoration: none;
  color: inherit;
  transition: border-color 0.12s, background 0.12s;
}
.ifx-com-side-row:hover {
  border-color: var(--ix-accent);
  background: var(--ix-bg-hover);
}
.ifx-com-side-row.is-up { border-color: rgba(113, 221, 55, 0.3); }
.ifx-com-side-row.is-down { border-color: rgba(255, 62, 29, 0.3); }
.ifx-com-side-row__name {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-semibold);
  color: var(--ix-text-primary);
  min-width: 0;
}
.ifx-com-side-row__name small {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-regular);
  color: var(--ix-text-muted);
}
.ifx-com-side-row__val {
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-bold);
  font-family: var(--ifx-font-mono);
  white-space: nowrap;
  color: var(--ix-text-secondary);
}
.ifx-com-side-row.is-up .ifx-com-side-row__val { color: var(--ix-success); }
.ifx-com-side-row.is-down .ifx-com-side-row__val { color: var(--ix-danger); }
.ifx-com-side-empty {
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
  padding: var(--ifx-space-8) 0;
}

.ifx-com-side-card--comments {
  display: flex;
  flex-direction: column;
}
.ifx-com-cmt-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ifx-space-4);
  margin-bottom: var(--ifx-space-12);
}
.ifx-com-cmt-tab {
  padding: 5px 10px;
  border-radius: 16px;
  border: 1px solid var(--ix-border);
  background: transparent;
  color: var(--ix-text-muted);
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-semibold);
  cursor: pointer;
  font-family: var(--ix-font);
  transition: all 0.12s;
}
.ifx-com-cmt-tab:hover { border-color: var(--ix-accent); color: var(--ix-accent); }
.ifx-com-cmt-tab.is-active {
  background: var(--ix-accent-soft);
  border-color: var(--ix-accent);
  color: var(--ix-accent);
}
.ifx-com-comment-form--side { margin-bottom: var(--ifx-space-12); }
.ifx-com-comments__list--side {
  overflow-y: auto;
  max-height: 420px;
  padding-right: 4px;
}
.ifx-com-comment__stats {
  display: flex;
  gap: var(--ifx-space-12);
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  margin-top: 6px;
}
.ifx-com-comment__stats i { margin-right: 2px; }

.ifx-com-action {
  display: inline-flex;
  align-items: center;
  gap: var(--ifx-inline-sm);
  padding: var(--ifx-space-8) 14px;
  border-radius: var(--ix-radius);
  border: 1px solid var(--ix-border);
  background: transparent;
  color: var(--ix-text-secondary);
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-medium);
  cursor: pointer;
  transition: background 0.12s, color 0.12s, border-color 0.12s;
}
.ifx-com-action:hover {
  background: var(--ix-bg-hover);
  color: var(--ix-text-primary);
}
.ifx-com-action.is-active {
  border-color: var(--ix-accent);
  color: var(--ix-accent);
  background: var(--ix-accent-soft);
}

.ifx-com-faq {
  margin-top: 28px;
  padding-top: 20px;
  border-top: 1px solid var(--ix-border);
}
.ifx-com-faq h2 { font-size: var(--ifx-font-size-16); margin-bottom: var(--ifx-space-12); }
.ifx-com-faq__item {
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius);
  padding: 10px 14px;
  margin-bottom: var(--ifx-space-8);
  background: var(--ix-bg-body);
}
.ifx-com-faq__item summary {
  cursor: pointer;
  font-weight: var(--ifx-font-weight-semibold);
  font-size: var(--ifx-font-size-14);
}
.ifx-com-faq__item p {
  margin: 10px 0 0;
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-secondary);
}

/* Comments */
.ifx-com-comments {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: 20px;
}
.ifx-com-comments__title {
  font-size: var(--ifx-font-size-16);
  font-weight: var(--ifx-font-weight-semibold);
  margin: 0 0 14px;
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
}
.ifx-com-comment-form {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-inline-md);
  margin-bottom: 20px;
}
.ifx-com-comment-form textarea { resize: vertical; min-height: 72px; }
.ifx-com-comment {
  padding: var(--ifx-space-12) 0;
  border-bottom: 1px solid var(--ix-border);
}
.ifx-com-comment:last-child { border-bottom: none; }
.ifx-com-comment__head {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-md);
  margin-bottom: 6px;
  font-size: var(--ifx-font-size-14);
}
.ifx-com-comment__head span { color: var(--ix-text-muted); font-size: var(--ifx-font-size-12); }
.ifx-com-comment p { margin: 0; font-size: var(--ifx-font-size-14); line-height: 1.5; }
.ifx-com-comments__empty {
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-muted);
  padding: var(--ifx-space-12) 0;
}

/* Write form */
.ifx-com-write__section {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: 18px 20px;
  margin-bottom: var(--ifx-space-16);
}
.ifx-com-write__section h2 {
  font-size: var(--ifx-font-size-16);
  font-weight: var(--ifx-font-weight-bold);
  margin: 0 0 16px;
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
  color: var(--ix-accent);
}
.ifx-com-write__grid2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--ifx-space-12);
}
.ifx-com-write__grid3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--ifx-space-12);
}
.ifx-com-write__body {
  font-family: var(--ifx-font-mono);
  font-size: var(--ifx-font-size-14);
}
.ifx-com-write__actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--ifx-inline-md);
  margin-top: var(--ifx-space-8);
  padding-bottom: 32px;
}

.ifx-com-hint {
  display: block;
  font-size: var(--ifx-font-size-10);
  margin-top: var(--ifx-space-4);
  color: var(--ix-text-muted);
}
.ifx-com-hint.is-ok { color: var(--ix-success); }
.ifx-com-hint.is-warn { color: var(--ix-warning); }

.ifx-com-faq-row {
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  gap: var(--ifx-space-8);
  margin-bottom: var(--ifx-space-8);
  align-items: start;
}
.ifx-com-faq-editor { margin-top: var(--ifx-space-8); }

.ifx-com-seo-json {
  background: var(--ix-bg-body);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius);
  padding: var(--ifx-space-12);
  font-size: var(--ifx-font-size-10);
  line-height: 1.45;
  overflow: auto;
  max-height: 50vh;
  white-space: pre-wrap;
  word-break: break-word;
}

#ifxComSeoModal { display: none; }
#ifxComSeoModal.open { display: flex; }

.ix-chip-sm { font-size: var(--ifx-font-size-10); padding: 2px 8px; }

/* ── Feed list layout + sidebar ─────────────────────────── */
.ifx-main.ifx-main--community {
  max-width: 1240px;
}

.ifx-com-feed-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  gap: var(--ifx-space-24);
  align-items: start;
  min-width: 0;
  max-width: 100%;
}
.ifx-com-feed-main {
  min-width: 0;
  width: 100%;
}
.ifx-com-feed-sidebar {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-space-16);
  min-width: 0;
  max-width: 100%;
}

/* ── Market overview ───────────────────────────────────── */
.ifx-com-overview {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: 18px 20px;
  margin-bottom: 0;
}
.ifx-com-overview--sidebar {
  padding: var(--ifx-space-16);
}
.ifx-com-overview--sidebar .ifx-widget__header {
  flex-wrap: wrap;
  margin-bottom: var(--ifx-space-12);
}
.ifx-com-overview--sidebar .ifx-com-overview__indices {
  margin-bottom: 0;
}
.ifx-com-breadth-sidebar {
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: var(--ifx-space-16);
}
.ifx-com-breadth-sidebar > .ifx-widget__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ifx-space-8);
  margin-bottom: var(--ifx-space-12);
}
.ifx-com-breadth-sidebar > .ifx-widget__header:has(> .ifx-block-share-actions) {
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-start;
}
.ifx-com-breadth-sidebar > .ifx-widget__header:has(> .ifx-block-share-actions) > h3 {
  flex: 1 1 auto;
  min-width: 0;
  order: 1;
}
.ifx-com-breadth-sidebar > .ifx-widget__header:has(> .ifx-block-share-actions) > .ifx-block-share-actions {
  flex: 0 0 auto;
  margin-left: auto;
  order: 2;
}
.ifx-com-breadth-sidebar > .ifx-widget__header:has(> .ifx-block-share-actions) > .ifx-widget__subtitle {
  flex: 1 0 100%;
  order: 3;
}
.ifx-com-breadth-sidebar .ifx-breadth-visual--6 {
  grid-template-columns: repeat(2, 1fr);
}
.ifx-com-breadth-sidebar .ifx-breadth-stat__num {
  font-size: var(--ifx-font-size-16);
}
.ifx-com-breadth-sidebar .ifx-breadth-stat__label {
  font-size: 8px;
}
.ifx-com-overview--sidebar .ifx-com-ex-card {
  padding: 10px;
}
.ifx-com-overview--sidebar .ifx-com-ex-card__val {
  font-size: var(--ifx-font-size-16);
}
.ifx-com-overview--sidebar .ifx-com-ex-card__chg {
  font-size: var(--ifx-font-size-10);
}
.ifx-com-overview--sidebar .ifx-breadth-visual--6 {
  grid-template-columns: repeat(2, 1fr);
}
.ifx-com-overview--sidebar .ifx-breadth-stat__num {
  font-size: var(--ifx-font-size-16);
}
.ifx-com-overview--sidebar .ifx-breadth-stat__label {
  font-size: 8px;
}

/* ── Top Watchlist (Elite) — head SoT .ifx-widget__header ── */
.ifx-com-topwl {
  position: relative;
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: var(--ifx-space-16);
  margin-top: var(--ifx-space-16);
  overflow: hidden;
}
.ifx-com-topwl > .ifx-widget__header {
  margin-bottom: var(--ifx-space-4);
  padding: 0;
  border-bottom: none;
  min-height: 0;
}
.ifx-com-topwl > .ifx-widget__subtitle {
  margin: 0 0 var(--ifx-space-12);
}
.ifx-com-topwl-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ifx-inline-sm);
  margin-bottom: var(--ifx-space-12);
}
.ifx-com-topwl-tab {
  border: 1px solid var(--ix-border);
  background: transparent;
  color: var(--ix-text-secondary);
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-semibold);
  padding: 5px 10px;
  border-radius: 999px;
  cursor: pointer;
}
.ifx-com-topwl-tab.is-active {
  background: rgba(105, 108, 255, 0.12);
  border-color: var(--ix-accent);
  color: var(--ix-accent);
}
.ifx-com-topwl-list {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-inline-md);
}
.ifx-com-topwl-row {
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-md);
  padding: 10px;
  background: rgba(255, 255, 255, 0.02);
}
.ifx-com-topwl-row__main {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: var(--ifx-space-8);
  align-items: center;
}
.ifx-com-topwl-rank {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-muted);
  min-width: 22px;
}
.ifx-com-topwl-user {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
  text-decoration: none;
  color: inherit;
  min-width: 0;
}
.ifx-com-topwl-user strong {
  display: block;
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-primary);
}
.ifx-com-topwl-user small {
  display: block;
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 160px;
}
.ifx-com-topwl-perf {
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-bold);
  white-space: nowrap;
}
.ifx-com-topwl-perf.is-up { color: var(--ix-success); }
.ifx-com-topwl-perf.is-down { color: var(--ix-danger); }
.ifx-com-topwl-copy {
  width: 100%;
  margin-top: var(--ifx-space-8);
  justify-content: center;
}
.ifx-com-topwl--locked .ifx-com-topwl-list {
  filter: blur(4px);
  pointer-events: none;
  user-select: none;
}
.ifx-com-topwl-lock {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(15, 17, 28, 0.55);
  padding: var(--ifx-space-16);
}
.ifx-com-topwl-lock__inner {
  text-align: center;
  max-width: 220px;
}
.ifx-com-topwl-lock__inner i {
  font-size: var(--ifx-font-size-28);
  color: var(--ix-warning);
  display: block;
  margin-bottom: var(--ifx-space-8);
}
.ifx-com-topwl-lock__inner strong {
  display: block;
  font-size: var(--ifx-font-size-14);
  margin-bottom: 6px;
}
.ifx-com-topwl-lock__inner p {
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
  margin: 0 0 12px;
  line-height: 1.45;
}
.ifx-com-overview > .ifx-widget__header {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--ifx-space-12);
  margin-bottom: var(--ifx-space-16);
}
.ifx-com-overview__status {
  font-size: var(--ifx-font-size-10);
  color: var(--ix-success);
  background: var(--ix-success-soft);
  padding: 3px 10px;
  border-radius: 20px;
  font-weight: var(--ifx-font-weight-semibold);
}
.ifx-com-overview__grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr);
  gap: var(--ifx-space-16);
  align-items: start;
}
.ifx-com-ex-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--ifx-inline-md);
}
.ifx-com-ex-card {
  background: var(--ix-bg-body);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius);
  padding: var(--ifx-space-12) 14px;
}
.ifx-com-ex-card__name {
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: var(--ifx-space-4);
}
.ifx-com-ex-card__val {
  font-size: var(--ifx-font-size-18);
  font-weight: var(--ifx-font-weight-bold);
  font-family: var(--ifx-font-mono);
  color: var(--ix-text-primary);
  line-height: 1.2;
}
.ifx-com-ex-card__chg {
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-semibold);
  margin-top: var(--ifx-space-4);
  font-family: var(--ifx-font-mono);
}
.ifx-com-ex-card__chg.is-up { color: var(--ix-success); }
.ifx-com-ex-card__chg.is-down { color: var(--ix-danger); }
.ifx-com-overview__breadth .ifx-breadth-visual--6 { gap: var(--ifx-inline-sm); }
.ifx-com-overview__breadth .ifx-breadth-stat { padding: var(--ifx-space-8) 6px; }
.ifx-com-overview__breadth .ifx-breadth-stat__num { font-size: var(--ifx-font-size-18); }
