/* ── Daily feed: khối ngày + chuyên gia nổi bật (spotlight + list) ── */
.ifx-ec-daily-feed { margin-bottom: var(--ifx-space-16); }
.ifx-com-day-block { margin-bottom: 8px; }
.ifx-com-day-head {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-12);
  margin: 12px 0 18px;
}
.ifx-com-day-head__label {
  display: inline-flex;
  align-items: center;
  gap: var(--ifx-space-8);
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-secondary);
  white-space: nowrap;
  text-transform: capitalize;
}
.ifx-com-day-head__line {
