  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-secondary);
}
.ifx-com-expert-spotlight__stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--ifx-space-8);
  width: 100%;
  margin-top: var(--ifx-space-8);
}
.ifx-com-expert-spotlight__stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: var(--ifx-space-8);
  border-radius: var(--ix-radius-md);
