  align-items: center;
  color: var(--ix-warning);
  font-size: var(--ifx-font-size-14);
}

.ifx-com-expert-row--rich { align-items: center; }
.ifx-com-expert-row__body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1;
  min-width: 0;
}
.ifx-com-expert-row__line1 {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ifx-space-8);
  min-width: 0;
}
.ifx-com-expert-row__line1 strong {
  font-size: var(--ifx-font-size-14);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ifx-com-expert-row__members {
  display: inline-flex;
  align-items: center;
  gap: var(--ifx-space-4);
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
  white-space: nowrap;
}
.ifx-com-expert-row__line2 {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-12);
  font-size: var(--ifx-font-size-12);
