}
.ifx-com-expert-row__line2 i { vertical-align: -2px; }
.ifx-com-expert-row__line2 .ifx-com-expert-stars { font-size: var(--ifx-font-size-12); }

@media (max-width: 960px) {
  .ifx-com-experts-layout { grid-template-columns: 1fr; }
}

/* Thành viên tích cực — sidebar */
.ifx-com-active-members {
  margin-top: var(--ifx-space-16);
  padding: var(--ifx-space-16) 18px;
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  background: var(--ix-bg-card);
}
.ifx-com-active-members__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ifx-space-8);
  margin-bottom: 6px;
}
.ifx-com-active-members__title {
  margin: 0;
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-bold);
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
}
.ifx-com-active-members__title i { color: var(--ix-success); }
.ifx-com-active-members__desc {
  margin: 0 0 12px;
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  line-height: 1.45;
}
.ifx-com-active-list {
  display: flex;
  flex-direction: column;
  gap: var(--ifx-space-8);
}
.ifx-com-active-row {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-md);
  padding: var(--ifx-space-8) 10px;
  border-radius: var(--ix-radius-lg);
  background: var(--ix-bg-hover);
}
.ifx-com-active-row__rank {
  font-size: var(--ifx-font-size-10);
  font-weight: 800;
  color: var(--ix-text-muted);
  min-width: 22px;
}
.ifx-com-active-row__user {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
  flex: 1;
  min-width: 0;
  color: inherit;
  text-decoration: none;
  font-size: var(--ifx-font-size-14);
}
.ifx-com-active-row__user:hover strong { color: var(--ix-accent); }
.ifx-com-active-row__user strong {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ifx-com-active-row__score {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.ifx-com-active-row__score.is-up .ifx-com-active-row__pos { color: var(--ix-success); }
.ifx-com-active-row__score.is-down .ifx-com-active-row__neg { color: var(--ix-danger); }
.ifx-com-active-row__sep {
  margin: 0 2px;
  color: var(--ix-text-muted);
  font-weight: var(--ifx-font-weight-regular);
}
.ifx-com-active-row__neg { color: var(--ix-text-muted); }

.ifx-com-filter-block { margin-bottom: 14px; }
.ifx-com-filter-label {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ix-text-muted);
  margin-bottom: var(--ifx-space-8);
}
.ifx-com-pills {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ifx-inline-sm);
}
.ifx-com-pills--scroll {
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: thin;
}
.ifx-com-pill {
  display: inline-flex;
  align-items: center;
  gap: var(--ifx-space-4);
  padding: 6px 12px;
  border-radius: 20px;
  border: 1px solid var(--ix-border);
  background: transparent;
  color: var(--ix-text-secondary);
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-medium);
  font-family: var(--ix-font);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.12s;
}
.ifx-com-pill:hover { border-color: var(--ix-accent); color: var(--ix-accent); }
.ifx-com-pill.is-active {
  background: var(--ix-accent);
  border-color: var(--ix-accent);
  color: #fff;
}
.ifx-com-pill.is-up:not(.is-active) { border-color: rgba(113, 221, 55, 0.35); color: var(--ix-success); }
.ifx-com-pill.is-down:not(.is-active) { border-color: rgba(255, 62, 29, 0.35); color: var(--ix-danger); }
.ifx-com-pill__n {
  font-size: var(--ifx-font-size-10);
  opacity: 0.85;
  background: rgba(255,255,255,0.15);
  padding: 0 5px;
  border-radius: 8px;
}
.ifx-com-pill:not(.is-active) .ifx-com-pill__n {
  background: var(--ix-bg-hover);
  color: var(--ix-text-muted);
}
.ifx-com-tax__tabs {
  display: flex;
  gap: var(--ifx-space-4);
  margin-bottom: var(--ifx-space-8);
}
.ifx-com-tax-tab {
  padding: 6px 14px;
  border-radius: var(--ix-radius);
  border: 1px solid var(--ix-border);
  background: transparent;
  color: var(--ix-text-secondary);
  font-size: var(--ifx-font-size-12);
  font-weight: var(--ifx-font-weight-semibold);
  cursor: pointer;
  font-family: var(--ix-font);
}
.ifx-com-tax-tab.is-active {
  background: var(--ix-accent-soft);
  border-color: var(--ix-accent);
  color: var(--ix-accent);
}
.ifx-com-tax__pills {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ifx-inline-sm);
}

/* ── Trending / Widget đặc thù main (span từ Product Composition) ── */
.ifx-com-dedicated-grid {
  margin-bottom: 20px;
}
.ifx-com-dedicated-grid > .ifx-rt-widget,
.ifx-com-dedicated-grid > [data-widget-id] {
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.ifx-com-dedicated-grid .ifx-com-trending-panel,
.ifx-com-dedicated-grid .ifx-wgt-block {
  flex: 1 1 auto;
  height: 100%;
  box-sizing: border-box;
}
/* Giữ class cũ cho InsightShare / markup khác — không còn dùng 1fr 1fr cứng */
.ifx-com-trending-row {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: var(--ifx-space-16);
  margin-bottom: 20px;
  align-items: stretch;
}
.ifx-com-trending-row > [data-ifx-com-001],
.ifx-com-trending-row > [data-ifx-com-story-top],
.ifx-com-trending-row > [data-widget-id],
.ifx-com-trending-row > .ifx-rt-widget {
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.ifx-com-trending-row .ifx-com-trending-panel,
.ifx-com-trending-row .ifx-wgt-block {
  flex: 1 1 auto;
  height: 100%;
  box-sizing: border-box;
}
.ifx-com-trending-panel {
  display: flex;
  flex-direction: column;
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  padding: var(--ifx-space-16) 18px 18px;
  min-height: 0;
}
.ifx-com-trending-panel--stocks .ifx-cap-treemap {
  flex: 1 1 auto;
}
.ifx-com-trending-panel__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--ifx-space-8);
  margin-bottom: 0;
}
.ifx-com-trending-empty {
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
  padding: var(--ifx-space-12) 0;
}
.ifx-com-ticker-heat__hint {
  margin: 0 0 10px;
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
}

/* Treemap vốn hóa — absolute tiles only, không flex/grid cho layout ô */
.ifx-cap-treemap {
  position: relative;
  display: block;
  width: 100%;
  min-height: 200px;
  overflow: hidden;
  border-radius: var(--ix-radius-md);
  background: var(--ix-bg-hover);
}
.ifx-cap-tile {
  position: absolute;
  box-sizing: border-box;
  overflow: hidden;
  transition: left 280ms ease, top 280ms ease, width 280ms ease, height 280ms ease;
}
.ifx-cap-tile__link {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.2em;
  width: 100%;
  height: 100%;
  padding: 0.35em 0.4em;
  box-sizing: border-box;
  text-decoration: none;
  border-radius: 3px;
  color: inherit;
  transition: filter 0.12s;
}
.ifx-cap-tile--large .ifx-cap-tile__link {
  align-items: flex-start;
  justify-content: flex-start;
  padding: 0.5em 0.55em;
  text-align: left;
}
.ifx-cap-tile__link:hover {
  filter: brightness(1.07);
  z-index: 2;
}
.ifx-cap-tile__heart {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 3;
}
.ifx-cap-tile__heart .ifx-stock-row__heart {
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: rgba(255, 255, 255, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.ifx-cap-tile__link.is-ref .ifx-cap-tile__heart .ifx-stock-row__heart {
  color: rgba(45, 45, 58, 0.75);
}
.ifx-cap-tile__tk {
  font-weight: 800;
  line-height: 1.1;
}
.ifx-cap-tile__name {
  font-size: 0.55em;
  font-weight: var(--ifx-font-weight-semibold);
  opacity: 0.9;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ifx-cap-tile__chg {
  font-weight: var(--ifx-font-weight-bold);
  opacity: 0.95;
}
.ifx-cap-tile__cap {
  font-size: 0.58em;
  font-weight: var(--ifx-font-weight-bold);
  opacity: 0.9;
}
.ifx-cap-tile__stars {
  font-size: 0.52em;
  letter-spacing: 0.04em;
  margin-top: auto;
}
.ifx-cap-tile__star-dim { opacity: 0.35; }
/* Tile colors → block-templates.css (TPL-TREEMAP) */

/* legacy heat classes — giữ heart ref cho story panel */
.ifx-com-ticker-heat__heart {
