  display: flex;
  flex-direction: column;
  gap: var(--ifx-inline-md);
  min-height: 0;
}
.ifx-com-post--featured .ifx-com-post__excerpt {
  margin: 0 0 12px;
  font-size: 0.95rem;
  line-height: 1.6;
  color: var(--ix-text-secondary);
