  -webkit-box-orient: vertical;
  overflow: hidden;
}
.ifx-com-ticker-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ifx-space-12);
  flex-wrap: wrap;
  margin: 12px 0 4px;
  padding: var(--ifx-space-12) 14px;
  border-radius: var(--ix-radius-md);
  border: 1px solid rgba(105, 108, 255, 0.25);
  background: rgba(105, 108, 255, 0.06);
}
.ifx-com-ticker-banner__text {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
  font-size: 0.95rem;
}
.ifx-com-side-row--static {
  cursor: default;
  pointer-events: none;
}

/* ── Post grid (card) ──────────────────────────────────── */
.ifx-com-feed-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--ifx-space-16);
  margin-bottom: var(--ifx-space-16);
}
.ifx-com-post {
  display: flex;
  flex-direction: column;
  background: var(--ix-bg-card);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius-lg);
  overflow: hidden;
  transition: transform 0.15s, box-shadow 0.15s, border-color 0.15s;
}
.ifx-com-post:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.14);
  border-color: rgba(105, 108, 255, 0.35);
}
.ifx-com-post__thumb {
  display: block;
  aspect-ratio: 16 / 9;
  background: var(--ix-bg-hover);
  overflow: hidden;
  position: relative;
}
.ifx-com-post__thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.ifx-com-post__thumb-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, rgba(105,108,255,0.08), rgba(3,195,236,0.06));
}
.ifx-com-post__thumb-fallback i {
  font-size: 42px;
  color: var(--ix-text-muted);
  opacity: 0.35;
}
.ifx-com-post__body { padding: 14px 16px 16px; flex: 1; display: flex; flex-direction: column; }
.ifx-com-post__author {
  display: flex;
  align-items: center;
  gap: var(--ifx-inline-sm);
  flex-wrap: nowrap;
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  min-width: 0;
  justify-content: flex-start;
  flex: 1;
}
.ifx-com-post__author-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 140px;
}
.ifx-com-post__author .ifx-com-card__avatar {
  width: 22px;
  height: 22px;
  font-size: 9px;
  flex-shrink: 0;
}
.ifx-com-post__title-row {
  margin-bottom: 10px;
  line-height: 1.45;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  overflow: hidden;
}
.ifx-com-post__time {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-regular);
  color: var(--ix-text-muted);
  vertical-align: baseline;
}
.ifx-com-post__title-sep {
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-regular);
  color: var(--ix-text-muted);
}
.ifx-com-post__title-text {
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-primary);
  text-decoration: none;
}
.ifx-com-post:hover .ifx-com-post__title-text { color: var(--ix-accent); }
.ifx-com-post__tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ifx-space-4);
  margin-bottom: var(--ifx-space-12);
  flex: 1;
  align-content: flex-start;
}
.ifx-com-post__tags a.ix-chip,
.ifx-com-article__tags a.ix-chip {
  text-decoration: none;
  font-weight: var(--ifx-font-weight-bold);
}
.ifx-com-post__tags .ix-stat-trend,
.ifx-com-article__tags .ix-stat-trend {
  margin-top: 0;
  font-size: var(--ifx-font-size-10);
  font-family: var(--ix-font);
  font-weight: var(--ifx-font-weight-semibold);
}
.ifx-com-post__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ifx-inline-md);
  padding-top: 10px;
  border-top: 1px solid var(--ix-border);
  margin-top: auto;
}
.ifx-com-post__stats {
  display: flex;
  gap: 14px;
  font-size: var(--ifx-font-size-10);
  color: var(--ix-text-muted);
  flex-shrink: 0;
  margin-left: auto;
}
.ifx-com-post__stats i { margin-right: 3px; vertical-align: -1px; }

/* Hero card variants — đặt sau base .ifx-com-post */
.ifx-com-post--featured .ifx-com-post__thumb { aspect-ratio: 16 / 10; }
.ifx-com-post--featured .ifx-com-post__title-text {
  font-size: 1.3rem;
  line-height: 1.35;
}
.ifx-com-post--featured .ifx-com-post__title-row {
  -webkit-line-clamp: 3;
  margin-bottom: var(--ifx-space-8);
}
.ifx-com-post--featured .ifx-com-post__time,
.ifx-com-post--featured .ifx-com-post__title-sep {
  font-size: var(--ifx-font-size-10);
}
.ifx-com-post--featured .ifx-com-post__body { padding: var(--ifx-space-16) 18px 18px; }
.ifx-com-post--featured .ifx-com-post__tags { flex: 0; margin-bottom: 10px; }
.ifx-com-post--featured .ifx-com-post__footer { margin-top: 0; }

.ifx-com-post.ifx-com-post--compact {
  flex-direction: row;
  align-items: stretch;
  min-height: 92px;
}
.ifx-com-hero__side .ifx-com-post--compact { flex: 1; }
.ifx-com-post--compact .ifx-com-post__thumb {
  width: 120px;
  min-width: 120px;
  max-width: 120px;
  aspect-ratio: unset;
  height: auto;
  align-self: stretch;
  flex-shrink: 0;
  border-radius: 0;
  border-top-left-radius: var(--ix-radius-lg);
  border-bottom-left-radius: var(--ix-radius-lg);
}
.ifx-com-post--compact .ifx-com-post__thumb-img,
.ifx-com-post--compact .ifx-com-post__thumb-fallback {
  height: 100%;
  min-height: 100%;
}
.ifx-com-post--compact .ifx-com-post__thumb-fallback i { font-size: var(--ifx-font-size-28); }
.ifx-com-post--compact .ifx-com-post__body {
  flex: 1;
  min-width: 0;
  padding: 10px 14px 10px 12px;
  justify-content: flex-start;
}
.ifx-com-post--compact .ifx-com-post__title-text {
  font-size: 0.9rem;
}
.ifx-com-post--compact .ifx-com-post__title-row {
  margin-bottom: 6px;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}
.ifx-com-post--compact .ifx-com-post__tags {
  flex: 0;
  margin-bottom: 6px;
}
.ifx-com-post--compact .ifx-com-post__footer {
  margin-top: auto;
  padding-top: 6px;
}
.ifx-com-post--compact .ifx-com-post__author-name { max-width: 72px; }

.ifx-com-load-more,
.ifx-com-end {
  text-align: center;
  padding: var(--ifx-space-16);
  font-size: var(--ifx-font-size-14);
  color: var(--ix-text-muted);
}
.ifx-com-spinner {
  display: inline-block;
  width: 14px;
  height: 14px;
  border: 2px solid var(--ix-border);
  border-top-color: var(--ix-accent);
  border-radius: 50%;
  animation: ifx-com-spin 0.7s linear infinite;
  vertical-align: -2px;
  margin-right: 6px;
}
@keyframes ifx-com-spin { to { transform: rotate(360deg); } }

@media (max-width: 960px) {
  .ifx-com-feed-layout {
    grid-template-columns: 1fr;
  }
  .ifx-com-story-layout {
    grid-template-columns: 1fr;
  }
  .ifx-com-side-card--toc {
    max-height: none;
  }
  .ifx-com-side-card--comments {
    max-height: none;
  }
  .ifx-com-comments__list--side {
    max-height: none;
  }
  .ifx-com-article__title { font-size: 26px; }
  .ifx-com-article__header { padding: 20px 20px 0; }
  .ifx-com-article__body { padding: 20px; }
  .ifx-com-overview__grid { grid-template-columns: 1fr; }
  .ifx-com-trending-row,
  .ifx-com-dedicated-grid {
    grid-template-columns: 1fr;
  }
  .ifx-com-trending-row > [data-widget-id],
  .ifx-com-trending-row > .ifx-rt-widget,
  .ifx-com-dedicated-grid > [data-widget-id],
  .ifx-com-dedicated-grid > .ifx-rt-widget {
    grid-column: 1 / -1 !important;
  }
  .ifx-com-hero { grid-template-columns: 1fr; }
  .ifx-com-feed-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 768px) {
  .ifx-com-write__grid2,
  .ifx-com-write__grid3,
  .ifx-com-faq-row {
    grid-template-columns: 1fr;
  }
  .ifx-com-article { padding: var(--ifx-space-16); }
  .ifx-com-article__title { font-size: var(--ifx-font-size-24); }
  .ifx-com-toolbar__right { width: 100%; }
  .ifx-com-feed-grid { grid-template-columns: 1fr; }
  .ifx-com-ex-grid { grid-template-columns: 1fr 1fr; }
}

/* ── GEO Metadata (AI Search) ─────────────────────────── */
.ifx-geo-ai {
  margin: 0;
  padding: 28px 32px 32px;
  border-top: 1px solid var(--ix-border);
  background: linear-gradient(180deg, rgba(105, 108, 255, 0.04) 0%, transparent 48%);
}
.ifx-geo-ai__head { margin-bottom: 20px; }
.ifx-geo-ai__kicker {
  display: inline-flex;
  align-items: center;
  gap: var(--ifx-inline-sm);
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ix-accent);
}
.ifx-geo-ai__hint {
  margin: 6px 0 0;
  font-size: var(--ifx-font-size-12);
  color: var(--ix-text-muted);
}
.ifx-geo-ai__section {
  padding: var(--ifx-space-16) 0;
  border-bottom: 1px solid var(--ix-border);
}
.ifx-geo-ai__section:last-child { border-bottom: none; padding-bottom: 0; }
.ifx-geo-ai__title {
  display: flex;
  align-items: center;
  gap: var(--ifx-space-8);
  margin: 0 0 10px;
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-text-primary);
}
.ifx-geo-ai__title i { color: var(--ix-accent); font-size: var(--ifx-font-size-16); }
.ifx-geo-ai__summary {
  margin: 0;
  font-size: var(--ifx-font-size-14);
  line-height: 1.6;
  color: var(--ix-text-secondary);
}
.ifx-geo-ai__list {
  margin: 0;
  padding-left: 18px;
  font-size: var(--ifx-font-size-14);
  line-height: 1.55;
  color: var(--ix-text-secondary);
}
.ifx-geo-ai__list li { margin-bottom: 6px; }
.ifx-geo-ai__faq {
  margin-bottom: var(--ifx-space-8);
  border: 1px solid var(--ix-border);
  border-radius: var(--ix-radius);
  background: var(--ix-bg-hover);
  overflow: hidden;
}
.ifx-geo-ai__faq summary {
  padding: 10px 12px;
  font-size: var(--ifx-font-size-14);
  font-weight: var(--ifx-font-weight-semibold);
  cursor: pointer;
  color: var(--ix-text-primary);
}
.ifx-geo-ai__faq p {
  margin: 0;
  padding: 0 12px 12px;
  font-size: var(--ifx-font-size-14);
  line-height: 1.5;
  color: var(--ix-text-secondary);
}
.ifx-geo-ai__claims {
  margin: 0;
  padding-left: 20px;
  font-size: var(--ifx-font-size-14);
  line-height: 1.55;
  color: var(--ix-text-secondary);
}
.ifx-geo-ai__claim-id {
  display: inline-block;
  font-size: var(--ifx-font-size-10);
  font-weight: var(--ifx-font-weight-bold);
  color: var(--ix-accent);
  margin-right: 4px;
}
.ifx-geo-ai__evidence {
  margin: 0;
  padding-left: 18px;
  font-size: var(--ifx-font-size-14);
  line-height: 1.55;
  color: var(--ix-text-secondary);
}
.ifx-geo-ai__ref {
  font-size: var(--ifx-font-size-10);
  color: var(--ix-accent);
  font-weight: var(--ifx-font-weight-semibold);
}
.ifx-geo-ai__sources {
  margin: 0;
  padding-left: 18px;
  font-size: var(--ifx-font-size-14);
}
.ifx-geo-ai__sources a { color: var(--ix-accent); text-decoration: none; }
.ifx-geo-ai__sources a:hover { text-decoration: underline; }
.ifx-geo-ai__pub { color: var(--ix-text-muted); font-size: var(--ifx-font-size-12); }
.ifx-geo-ai__topics {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ifx-space-8);
}
.ifx-geo-ai__topic {
  font-size: var(--ifx-font-size-12);
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--ix-bg-hover);
  border: 1px solid var(--ix-border);
  color: var(--ix-text-secondary);
}

.ifx-geo-ai-form__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ifx-space-12);
  flex-wrap: wrap;
  margin-bottom: var(--ifx-space-4);
}
.ifx-geo-ai-form__head h2 { margin: 0; }
.ifx-geo-ai-form__nav {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ifx-inline-sm);
  margin-bottom: var(--ifx-space-16);
}
.ifx-geo-ai-form__chip {
  display: inline-flex;
  align-items: center;
  gap: var(--ifx-space-4);
  font-size: var(--ifx-font-size-10);
  padding: 4px 8px;
  border-radius: var(--ix-radius);
  background: var(--ix-bg-hover);
  color: var(--ix-text-muted);
  border: 1px solid var(--ix-border);
}
.ifx-geo-ai-form__chip i { font-size: var(--ifx-font-size-12); }
.ifx-geo-ai-form__block { margin-bottom: var(--ifx-space-16); }
.ifx-geo-ai-form__row {
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  gap: var(--ifx-space-8);
  margin-bottom: var(--ifx-space-8);
  align-items: start;
}
.ifx-geo-ai-form__row--evidence {
  grid-template-columns: 1fr 100px auto;
}
.ifx-geo-ai-form__row--source {
  grid-template-columns: 1fr 1fr 120px auto;
}
@media (max-width: 720px) {
  .ifx-geo-ai { padding: 20px 16px; }
  .ifx-geo-ai-form__row,
  .ifx-geo-ai-form__row--evidence,
  .ifx-geo-ai-form__row--source {
    grid-template-columns: 1fr;
  }
}

a.ifx-profile-link { color: inherit; text-decoration: none; font-weight: inherit; }
a.ifx-profile-link:hover { color: var(--ix-accent); text-decoration: underline; }
a.ifx-profile-link-avatar { text-decoration: none; color: inherit; }
a.ifx-com-post__author-name.ifx-profile-link { font-weight: var(--ifx-font-weight-semibold); }
a.ifx-com-card__avatar.ifx-profile-link-avatar:hover { opacity: .88; }

/* iFlux — HTTP API client (ApiDataProvider). Requires: iflux-runtime-config → iflux-data-provider → iflux-api-config */
(function (global) {
  'use strict';

  function baseUrl() {
    return global.IfluxApiConfig ? IfluxApiConfig.getBaseUrl() : '';
  }

  function authHeaders(token) {
    var h = { 'Content-Type': 'application/json' };
    if (token) h.Authorization = 'Bearer ' + token;
    return h;
  }

  function friendlyNetworkError(err) {
    var msg = (err && err.message) || '';
    if (msg === 'Failed to fetch' || (err && err.name === 'TypeError')) {
      if (global.IfluxData && !IfluxData.isApi()) {
        var mode = global.IfluxRuntime ? IfluxRuntime.getDataMode() : 'sandbox';
        return new Error('dataMode=' + mode + ' — UI dùng ' + (IfluxData.getProvider().label || 'local provider') + ', không gọi HTTP API.');
      }
      var base = baseUrl();
      if (!base) {
        return new Error('dataMode=api nhưng chưa cấu hình apiBaseUrl trong runtime manifest.');
      }
      return new Error(
        'Không kết nối được API (' + base + '). ' +
        (base.indexOf('localhost') >= 0
          ? 'Chạy backend: cd backend && npm start (port 3001), hoặc đổi ?dataMode=sandbox.'
          : 'Kiểm tra server hoặc đổi dataMode trong iflux-runtime-manifest.json.')
      );
    }
    return err;
  }

  function request(path, options) {
    if (!global.IfluxData || !IfluxData.isApi()) {
      var provider = global.IfluxData ? IfluxData.getProvider().label : 'SandboxDataProvider';
      return Promise.reject(new Error('Provider hiện tại: ' + provider + ' — không dùng HTTP request.'));
    }
    if (!global.IfluxApiConfig || !IfluxApiConfig.isEnabled()) {
      return Promise.reject(new Error('dataMode=api nhưng apiBaseUrl chưa được cấu hình.'));
    }
    options = options || {};
    var url = baseUrl() + path;
    var headers = Object.assign({ 'Content-Type': 'application/json' }, options.headers || {});
    return fetch(url, {
      method: options.method || 'GET',
      headers: headers,
      body: options.body != null ? JSON.stringify(options.body) : undefined
    }).then(function (res) {
      return res.json().catch(function () { return {}; }).then(function (data) {
        if (!res.ok) {
          var msg = data.error || (data.error && data.error.message) || data.message || ('HTTP ' + res.status);
          if (typeof msg === 'object') msg = msg.message || JSON.stringify(msg);
          if (msg === 'Invalid credentials') msg = 'Email hoặc mật khẩu không đúng.';
          if (msg === 'Email already registered') msg = 'Email đã được đăng ký.';
          if (msg === 'Phone already registered') msg = 'Số điện thoại này đã được liên kết với tài khoản khác.';
          if (msg === 'Invalid verification code') msg = 'Mã xác thực không đúng.';
          if (msg === 'Verification code expired') msg = 'Mã xác thực đã hết hạn. Vui lòng đăng ký lại hoặc gửi lại mã.';
          if (msg === 'Too many verification attempts') msg = 'Nhập sai quá nhiều lần. Vui lòng gửi lại mã.';
          if (msg === 'Email not verified') msg = 'Email chưa xác thực. Hoàn tất xác thực trước khi đăng nhập.';
          if (msg === 'Email service not configured') msg = 'Hệ thống email chưa cấu hình. Liên hệ quản trị viên.';
          if (msg.indexOf('Please wait') === 0) msg = msg.replace('Please wait', 'Vui lòng đợi').replace('seconds before resending', 'giây trước khi gửi lại');
          throw new Error(msg);
        }
        return data;
      });
    }).catch(function (err) {
      throw friendlyNetworkError(err);
    });
  }

  function authRegister(email, password, referralCode, extra) {
    extra = extra || {};
    return request('/auth/register', {
      method: 'POST',
      body: {
        email: email,
        password: password,
        referral_code: referralCode || null,
        display_name: extra.display_name || null,
        phone: extra.phone || null
      }
    });
  }

  function authVerifyEmail(email, code) {
    return request('/auth/verify-email', {
      method: 'POST',
      body: { email: email, code: code }
    });
  }

  function authResendVerification(email) {
    return request('/auth/resend-verification', {
      method: 'POST',
      body: { email: email }
    });
  }

  function authLogin(email, password, rememberMe) {
    return request('/auth/login', {
      method: 'POST',
      body: { email: email, password: password, remember_me: !!rememberMe }
    });
  }

  function authSocial(provider, tokens, opts) {
    opts = opts || {};
    tokens = tokens || {};
    var body = {
      provider: provider,
      referral_code: opts.referral_code || null
    };
    if (tokens.id_token) body.id_token = tokens.id_token;
    if (tokens.access_token) body.access_token = tokens.access_token;
    if (tokens.oauth_code) body.oauth_code = tokens.oauth_code;
    if (opts.remember_me) body.remember_me = !!opts.remember_me;
    return request('/auth/social', { method: 'POST', body: body });
  }

  function getSocialAuthConfig() {
    return request('/auth/social/config', { method: 'GET' });
  }

  function authMe(token) {
    return request('/auth/me', { headers: authHeaders(token) });
  }

  function validateReferralCode(code) {
    return request('/auth/referral/validate/' + encodeURIComponent(String(code || '').trim().toUpperCase()));
  }

  function getAffiliateSync(token) {
    return request('/auth/referrals/sync', { headers: authHeaders(token) });
  }

  function updateProfile(token, patch) {
    return request('/users/profile', {
      method: 'PUT',
      headers: authHeaders(token),
      body: patch
    });
  }

  function getUserDataSync(token) {
    return request('/user-data/sync', { headers: authHeaders(token) });
  }

  function getWatchlist(token) {
    return request('/user-data/watchlist', { headers: authHeaders(token) });
  }

  function saveWatchlist(token, data) {
    return request('/user-data/watchlist', {
      method: 'PUT',
      headers: authHeaders(token),
      body: { data: data }
    });
  }

  function getAlerts(token) {
    return request('/user-data/alerts', { headers: authHeaders(token) });
  }

  function saveAlerts(token, data) {
    return request('/user-data/alerts', {
      method: 'PUT',
      headers: authHeaders(token),
      body: { data: data }
    });
