    function runCapture() {
      flattenCardToPng(clone, function (url) {
        if (clone.parentNode) clone.parentNode.removeChild(clone);
        cb(url);
      });
    }
    if (!pending) {
      runCapture();
      return;
    }
    imgs.forEach(function (im) {
      function tick() {
        pending -= 1;
        if (pending <= 0) runCapture();
      }
      if (im.complete) tick();
      else {
        im.onload = tick;
        im.onerror = tick;
      }
    });
  }

