    applyCardLayout: applyCardLayout,
    computeCardLayout: computeCardLayout,
    resolveGroupProfile: resolveGroupProfile,
    INSIGHT_BLOCK_GROUPS: INSIGHT_BLOCK_GROUPS
  };
})(window);

