    if (!map) return [];
    return ['vnindex', 'hose', 'hnx', 'upcom'].map(function (key) {
      var ex = map[key];
      if (!ex) return null;
      return { key: key, name: ex.name, value: ex.value, change_pct: ex.change_pct };
