    .filter(function (w) { return w && w.enabled !== false; })
    .sort(function (a, b) { return (a.position || 0) - (b.position || 0); });

  for (var i = 0; i < slots.length; i++) {
    var slot = slots[i];
    var sectionEl = sectionMap[slot.section];
    if (!sectionEl) {
      if (window.console && console.warn) {
