    var scope = root || document;
    if (!scope._ifxWlHeartBound) {
      scope.addEventListener('click', onHeartPointer);
      scope._ifxWlHeartBound = true;
    }
    refreshHearts();
    if (global.IfluxAlertUI) IfluxAlertUI.bindAlerts(scope);
